import{m as a}from"./courses-t_iS-qhy.js";function h(e){const n=`manifest-${e.number}`;return{schemaVersion:2,revision:1,id:n,courseId:"manifest",locale:"de",title:e.title,goal:e.goal,minutes:{learning:5,suggestedAction:5,review:2},direction:{hook:e.hook,reason:{id:`${n}-reason`,label:e.reason,kind:"text",maxLength:160,optional:!0,suggestions:["Mein Ziel; weniger Wiederholungen","Erst handeln, dann weiter vorbereiten","Erst Unterstützung, dann weiterprobieren"]},why:{id:`${n}-purpose`,label:"Warum lohnt sich dieser Schritt in deiner Woche?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:e.paragraphs,example:e.example},move:{invitation:"Bleib bei deinem Ziel. Wähle eine sinnvolle Handlung.",instructions:e.instructions,prompts:[],suggestions:{action:e.action,minimum:e.minimum,cue:e.cue,place:e.place,fallback:e.fallback,observation:e.observation,minutes:[5,2,10],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}]},suggested:{action:e.action[0],minimum:e.minimum[0],minutes:5,cueHint:e.cue[0],placeHint:e.place[0],obstacleHint:e.obstacle,fallbackHint:e.fallback[0],observationHint:e.observation[0]},accessibleAlternative:"Du kannst das Ritual tippen, diktieren oder beschreiben. Du brauchst dafür weder Zubehör noch lebhafte innere Bilder.",stopRule:e.stopRule},result:{question:"Hast du dein gewähltes Minimum tatsächlich erledigt?",observationPrompt:"Was hast du tatsächlich getan, getrennt vom Ritual selbst?"},judgment:{primary:{id:`${n}-decision`,scenario:e.scenario,question:e.question,options:e.options.map(t=>({id:`${n}-${t.key}`,text:t.text,feedback:t.feedback})),bestOptionId:`${n}-${e.best}`}},carry:{takeaway:e.takeaway,followUp:{questionId:`${n}-return`,question:e.review,observationPrompt:"Was ist bei deiner gespeicherten Gelegenheit passiert, auch an Antworten von anderen?",adjustmentPrompt:"Welche einzelne Änderung passt zu deiner nächsten Gelegenheit?"}},goDeeper:{sections:e.deeper,sourceIds:e.sources}}}const s=[{id:"manifest-T01",title:"Wang, Wang & Gai · 2021 · Mental contrasting with implementation intentions",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"24 unabhängige Effekte aus 21 Artikeln mit 15.907 Teilnehmenden: Mentales Kontrastieren zusammen mit Wenn-dann-Plänen unterstützte das Erreichen von Zielen im Durchschnitt, g = 0,336 [0,229; 0,443]. Nach Korrektur möglicher Verzerrungen lag die Schätzung bei 0,242 [0,143; 0,342].",limitation:"Die Effekte unterschieden sich; es gab Hinweise auf Publikationsverzerrung. Das garantiert keinen Erfolg, belegt nicht, dass Unbehagen nötig ist, und prüft weder diese Bibliothek noch ihre angepassten Rituale."},{id:"manifest-T02",title:"Gollwitzer & Sheeran · 2006 · Implementation intentions and goal achievement",url:"https://www.socmot.uni-konstanz.de/sites/default/files/06_Gollwitzer_Sheeran_Implementation_Intentions_And_Goal.pdf",type:"research",finding:"Eine grundlegende Metaanalyse von 94 unabhängigen Tests mit 8.461 Teilnehmenden fand im Durchschnitt einen Vorteil beim Erreichen von Zielen durch konkrete Wenn-dann-Pläne, d = 0,65 [0,60; 0,70].",limitation:"Ältere, uneinheitliche Forschung, nicht durchgängig vorab registriert. Ein Plan beseitigt weder äußere Hindernisse noch die nötige Anstrengung und garantiert keine Entscheidung eines anderen Menschen."},{id:"manifest-T03",title:"Harkin et al. · 2016 · Monitoring goal progress",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"138 randomisierte Experimente mit insgesamt 19.951 Teilnehmenden: Die Aufforderung, Fortschritte zu beobachten, verbesserte das Erreichen von Zielen im Durchschnitt, d = 0,40 [0,32; 0,48]. Über die Studien hinweg ging das schriftliche Festhalten mit größeren Effekten einher.",limitation:"Übungen und Ziele unterschieden sich. Zusammenhänge mit Studienmerkmalen belegen nicht, dass jede Funktion zum Festhalten von Fortschritten wirkt. Der Rückblick am nächsten Tag ist eine ODA-Anpassung, kein nachgewiesener optimaler Rhythmus."},{id:"manifest-T04",title:"Cole et al. · 2021 · Mental simulation and behavior change",url:"https://link.springer.com/article/10.3758/s13423-021-01880-6",type:"research",finding:"94 Studien, 123 Effekte, 5.685 Teilnehmende: Gedankliches Durchspielen unterstützte späteres Verhalten im Durchschnitt, g = 0,49 [0,37; 0,62]. Der Gesamttest zum Vergleich der einzelnen Formen belegte keine Unterschiede zwischen ihnen.",limitation:"Meist Studierende, unterschiedliche Aufgaben und Vorstellungsübungen. Einige Untergruppen enthielten nur wenige Effekte. Weder eine verlässliche Rangfolge der Formen noch das Anziehen äußerer Ereignisse oder ein besonderer Vorteil vor dem Schlafengehen wurde belegt."},{id:"manifest-T05",title:"Kappes & Oettingen · 2011 · Idealized positive fantasies",url:"https://bpb-us-e1.wpmucdn.com/wp.nyu.edu/dist/c/6235/files/2019/02/kappes-et-al-2011-positive-fantasies-about-idealized-futures-sap-energu.pdf",type:"research",finding:"Vier Experimente fanden nach manchen idealisierten positiven Zukunftsfantasien unmittelbar weniger Energie; auch einige spätere Erfolgsmaße unterschieden sich. Das unterscheidet angenehmes Fantasieren von der Vorbereitung auf Anstrengung.",limitation:"Kurze Experimente, überwiegend mit Studierenden. Nicht jede Form von Optimismus oder Vorstellung ist schädlich. Das vermutete Gehirnsignal, ein Ziel sei bereits erreicht, wurde nicht gemessen."},{id:"manifest-T06",title:"Wood, Perunovic & Lee · 2009 · Positive self-statements",url:"https://journals.sagepub.com/doi/abs/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"Zwei Experimente fanden: Das Wiederholen einer stark positiven Aussage über sich selbst konnte bei Teilnehmenden mit geringem Selbstwertgefühl die Stimmung verschlechtern. Bei hohem Selbstwertgefühl waren die Vorteile begrenzt.",limitation:"Untersucht wurden bestimmte Aussagen, Stichproben und kurzfristige Ergebnisse. Das zeigt weder, dass jede Ermutigung schadet, noch prüft es alle Affirmationsübungen. Ein glaubwürdiger Satz über das eigene Handeln ist eine ODA-Anpassung."},{id:"manifest-T07",title:"Epton et al. · 2015 · Self-affirmation and health behavior",url:"https://pubmed.ncbi.nlm.nih.gov/25133846/",type:"research",finding:"144 experimentelle Tests untersuchten das Bekräftigen wichtiger Werte, Eigenschaften oder Beziehungen zusammen mit Gesundheitsinformationen. Die Effekte auf Akzeptanz und Absichten waren klein. 46 Verhaltenstests mit 2.715 Teilnehmenden ergaben d = 0,32 [0,19; 0,44].",limitation:"Wertebezogene Selbstaffirmation ist etwas anderes als das Wiederholen eines Wunschergebnisses als Tatsache. Befunde zu Gesundheitsinformationen belegen nicht, dass wiederholte Sätze Jobs, Geld oder Beziehungen anziehen."},{id:"manifest-T08",title:"Carrillo et al. · 2019 · Best possible self meta-analysis",url:"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0222386",type:"research",finding:"29 Studien mit 2.909 Teilnehmenden: Das Schreiben über eine bestmögliche Zukunft, die man sich als Ergebnis eigener Anstrengungen vorstellt, verbesserte Wohlbefinden, Optimismus und positive Gefühle im Durchschnitt gegenüber Kontrollgruppen.",limitation:"Meist junge Studierende; keine Studie erfüllte sämtliche Qualitätskriterien. Ergebnisse zu Stimmung und Optimismus belegen weder das Erreichen äußerer Ziele noch die Wirksamkeit von Scripting im Präsens."},{id:"manifest-T09",title:"Davis et al. · 2016 · Gratitude interventions meta-analysis",url:"https://scottbarrykaufman.com/wp-content/uploads/2021/05/davis2016.pdf",type:"research",finding:"Randomisierte Dankbarkeitsstudien zeigten gegenüber einigen Kontrollbedingungen kleine durchschnittliche Vorteile für das Wohlbefinden. Gegenüber anderen Übungen, die ebenfalls psychologische Prozesse ansprechen, war Dankbarkeit beim Wohlbefinden nicht überlegen. Die Ergebnisse zu Angst waren nicht eindeutig.",limitation:"Die Effekte hängen von den Vergleichsübungen und der Studienqualität ab. Das belegt weder ein allgemeingültiges Schreibpensum noch das Anziehen äußerer Ereignisse oder einen zusätzlichen Nutzen von Dankbarkeit für ein als bereits eingetreten beschriebenes Zukunftsereignis."},{id:"manifest-T10",title:"Cregg & Cheavens · 2021, online 2020 · Gratitude and symptom change",url:"https://link.springer.com/article/10.1007/s10902-020-00236-6",type:"research",finding:"27 Studien mit 3.675 Teilnehmenden: Dankbarkeitsübungen hatten kleine durchschnittliche Effekte auf zusammengefasste Depressions- und Angstsymptome. Gegenüber Wartelisten waren die Effekte größer als gegenüber aktiven Kontrollbedingungen. Die gesonderte Angstanalyse umfasste fünf Studien und blieb uneindeutig.",limitation:"Diese begrenzten Befunde zu Symptomen belegen nicht, dass Dankbarkeit als Behandlung ausreicht. Menschen, die Linderung bei Depression oder Angst suchen, empfehlen die Autoren Verfahren mit stärkeren Wirksamkeitsbelegen."},{id:"manifest-T11",title:"Locke & Latham · 2002 · Goal setting and task motivation",url:"https://med.stanford.edu/content/dam/sm/s-spire/documents/PD.locke-and-latham-retrospective_Paper.pdf",type:"research",finding:"Eine Übersicht über Jahrzehnte der Zielsetzungsforschung beschreibt, wie konkrete, anspruchsvolle Ziele Leistung unterstützen können. Zielbindung, Rückmeldung, Fähigkeiten und die Komplexität der Aufgabe beeinflussen die Ergebnisse.",limitation:"Eine beschreibende Theorieübersicht, kein Test von Manifestationsritualen. Ziele brauchen machbare Wege und verfügbare Mittel. Bei neuen oder komplexen Aufgaben können Lernziele hilfreicher sein als Druck, sofort Leistung zu zeigen."},{id:"manifest-T12",title:"Frattaroli · 2006 · Expressive disclosure meta-analysis",url:"https://bpb-us-e2.wpmucdn.com/faculty.sites.uci.edu/dist/c/602/files/2019/08/Frattaroli-psych-bulletin-2006.pdf",type:"research",finding:"146 randomisierte Studien zum Schreiben oder Sprechen über Erlebnisse und Gefühle fanden über verschiedene Ergebnisse hinweg einen kleinen durchschnittlichen Nutzen, mittleres r = 0,075 [0,052; 0,098]. Die Effekte variierten je nach Ergebnis und Vorgehen.",limitation:"Über wirkliche Erlebnisse zu schreiben ist etwas anderes, als ein erhofftes Ereignis als Tatsache aufzuschreiben. Diese Übersicht bestätigt weder jedes Tagebuch noch verspricht sie Erholung von Trauma oder zeigt, dass geschriebene Geschichten äußere Ergebnisse verursachen."},{id:"manifest-T13",title:"Dixon, Hornsey & Hartley · 2025, online 2023 · Manifestation beliefs",url:"https://journals.sagepub.com/doi/full/10.1177/01461672231181162",type:"research",finding:"Drei US-Onlinebefragungen mit 1.023 Teilnehmenden: Manifestationsglaube hing mit Zuversicht und einigen selbst berichteten finanziellen Risiken und Insolvenzen zusammen. Mit selbst berichtetem Einkommen oder Bildungsstand wurde kein Zusammenhang festgestellt.",limitation:"Zusammenhänge und selbst berichtete Ergebnisse belegen weder Ursachen noch die Verbreitung in der Bevölkerung oder die Wirksamkeit jeder einzelnen Technik. Zuversicht ist kein objektiver Erfolgsbeleg."},{id:"manifest-T14",title:"Denrell · 2003 · Undersampling failure and success stories",url:"https://pubsonline.informs.org/doi/10.1287/orsc.14.2.227.15164",type:"research",finding:"Eine Analyse des Lernens von fortbestehenden Organisationen zeigt: Wenn gescheiterte Fälle zu selten berücksichtigt werden, kann eine damit nicht zusammenhängende Praxis als Erfolgsfaktor erscheinen.",limitation:"Untersucht wurden Organisationsmodelle, nicht der beschriebene virale Beitrag. Dieses Prinzip auf Manifestationsberichte zu übertragen ist eine Schlussfolgerung. Es zeigt nicht, dass eine bestimmte erzählende Person unehrlich ist."},{id:"manifest-T15",title:"Awh, Belopolsky & Theeuwes · 2012 · Attentional control",url:"https://research.vu.nl/en/publications/top-down-versus-bottom-up-attentional-control-a-failed-theoretica/",type:"research",finding:"Diese Übersicht zur Aufmerksamkeit beschreibt, wie aktuelle Ziele, auffällige Reize und frühere Auswahl beeinflussen, was wir beachten. Ein Ziel kann neben anderen Einflüssen mitbestimmen, worauf sich Aufmerksamkeit richtet.",limitation:"Die Theorie zur visuellen Aufmerksamkeit prüft weder Vision Boards noch Affirmationen, einen einzelnen RAS-Wunschfilter oder das Entstehen äußerer Gelegenheiten. Eine Gelegenheit zu bemerken und ihr Entstehen zu verursachen sind unterschiedliche Behauptungen."},{id:"manifest-T16",title:"Dai et al. · 2023 · Behavioral priming meta-analysis",url:"https://socialactionlab.org/wp-content/uploads/2024/01/Dai_Priming-Behavior-A-Meta-Analysis-of-the-Effects-of-Behavioral-and-Nonbehavioral-Primes-on-Overt-Behavioral-Outcomes_2023.pdf",type:"research",finding:"351 Studien, 862 Effekte: Die Übersicht fand im Durchschnitt einen Effekt von Priming auf Verhalten. In der kleineren, vorab registrierten Teilmenge waren die Effekte kleiner und statistisch uneindeutig. Das macht Unsicherheit über Verlässlichkeit und Bedingungen sichtbar.",limitation:"Beiläufige Reize im Experiment unterscheiden sich von bewussten Manifestationsritualen. Die kleine vorab registrierte Teilmenge widerlegt nicht jedes Priming. Das Gesamtergebnis bestätigt weder wiederholte Sätze noch genaue Zeitschwellen oder kosmische Anziehung."},{id:"manifest-T17",title:"Pham & Taylor · 1999 · Process versus outcome simulation",url:"https://journals.sagepub.com/doi/abs/10.1177/0146167299025002010",type:"research",finding:"Eine frühe Prüfungsstudie fiel zugunsten des Vorstellens von Lernabläufen gegenüber dem bloßen Vorstellen einer guten Note aus. Planung und Angst halfen, die Notenunterschiede zu erklären. Der Haupteffekt der Ablaufvorstellung auf Noten war statistisch grenzwertig; ein nachträglicher Vergleich von reiner Ablauf- mit reiner Ergebnisvorstellung war signifikant.",limitation:"Der Prüfungseffekt von Ablaufvorstellung gegenüber der Kontrollgruppe war in Coles späterer Synthese nicht signifikant. Diese belegte keine allgemein überlegene Form. Eine eng begrenzte frühe Studie zeigt weder verlässliche Notenvorteile gegenüber einer Kontrollgruppe noch das Anziehen äußerer Ereignisse."},{id:"manifest-T18",title:"Taylor et al. · 1998 · Mental simulation and self-regulation",url:"https://pubmed.ncbi.nlm.nih.gov/9572006/",type:"research",finding:"Diese Darstellung eines Forschungsprogramms unterscheidet das Vorstellen von Abläufen und dem Umgang mit Schwierigkeiten vom bloßen Vorstellen eines erfolgreichen Abschlusses. Sie betont Planung und Problemlösen.",limitation:"Eine Übersicht über ein Forschungsprogramm, keine umfassende Metaanalyse und kein Beleg dafür, dass Ablaufvorstellungen immer überlegen sind. Zusammen mit Coles späterer Synthese und einem tatsächlichen Versuch nutzen."},{id:"manifest-T19",title:"Larson-Prior, Ju & Galvin · 2014 · Sleep, wakefulness and arousal circuits",url:"https://www.frontiersin.org/journals/neurology/articles/10.3389/fneur.2014.00165/full",type:"research",finding:"Eine neurowissenschaftliche Übersicht beschreibt das retikuläre Aktivierungssystem als Teil zusammenwirkender Schaltkreise für Wachheit und die Aktivierung der Großhirnrinde.",limitation:"Neurowissenschaft zu Wachheit belegt weder, dass ein aufgeschriebener Wunsch einen Gehirnfilter auf Gelegenheiten programmiert, noch dass Gedanken im schläfrigen Zustand äußere Ereignisse verändern. Kein Manifestationsritual wurde geprüft."},{id:"manifest-P01",title:"Taylor McGrath · 369 manifestation method",url:"https://www.theselfcollective.com.au/blogs/news/369-manifestation-method",type:"technique",finding:"Anleitung aus der Praxis: Eine Absicht im Präsens morgens dreimal, nachmittags sechsmal und abends neunmal aufschreiben.",limitation:"Beschreibt eine Praxis, liefert aber keine kontrollierten Wirksamkeitsbelege. Wiederholungszahlen, Zyklen, Aussagen zur Aufmerksamkeit und Verbindungen zu Tesla sind keine wissenschaftlichen Befunde."},{id:"manifest-P02",title:"Victoria Jackson · Scripting an ideal day",url:"https://themanifestationcollective.co/scripting-to-manifest/",type:"technique",finding:"Anleitung aus der Praxis: Einen vorgestellten idealen Tag in der Ich-Form und im Präsens ins Tagebuch schreiben, Sinneseindrücke und Gefühle ergänzen und den Text erneut lesen.",limitation:"Beschreibt ein Ritual. Aussagen über die Programmierung des Unterbewusstseins, Schwingungen, Synchronizitäten und persönliche Ergebnisse sind keine kontrollierten Forschungsbelege."},{id:"manifest-P03",title:"Jack Canfield · Creating a vision board",url:"https://jackcanfield.com/blog/vision-board/",type:"technique",finding:"Anleitung aus der Praxis: Ziele und passende Bilder oder Wörter wählen, als Collage auf Papier oder digital anordnen, sichtbar platzieren und regelmäßig betrachten.",limitation:"Eine beschreibende Anleitung, kein Wirksamkeitsbeleg für Vision Boards. Diese Seite belegt weder das Gesetz der Anziehung noch Erfolgsgeschichten als Nachweis oder die RAS-Erklärungen."},{id:"manifest-P04",title:"Jack Canfield · Daily affirmations",url:"https://jackcanfield.com/blog/daily-affirmations/",type:"technique",finding:"Anleitung aus der Praxis: Kurze, konkrete Aussagen in der Ich-Form und im Präsens verfassen und lesen oder wiederholen, häufig morgens und abends.",limitation:"Positive Aussagen unterscheiden sich von der Forschung zu wertebezogener Selbstaffirmation. Diese Anleitung belegt weder einen Nutzen für alle noch Auswirkungen auf äußere Ergebnisse."},{id:"manifest-P05",title:"Jack Canfield · Visualization techniques",url:"https://jackcanfield.com/blog/visualization-techniques-manifest-your-dreams/",type:"technique",finding:"Die Praxisanleitung beschreibt Vorstellungen gewünschter Ergebnisse mit Sinneseindrücken, gedankliches Üben aus der eigenen Perspektive und Vorstellungen des Weges zum Ziel.",limitation:"Eine beschreibende Anleitung, kein Beleg für Garantien oder Anziehung. Empirische Befunde zum gedanklichen Durchspielen müssen anhand der Forschungsquellen geprüft werden."},{id:"manifest-P06",title:"Zanna Keithley · 55x5 method description",url:"https://zannakeithley.com/55x5-manifestation-method-worksheet/",type:"technique",finding:"Anleitung aus der Praxis: An fünf aufeinanderfolgenden Tagen dieselbe Affirmation jeweils 55-mal hintereinander schreiben und sich dabei vorstellen, sie sei bereits wahr.",limitation:"Öffentlich zugängliche Beschreibung; ein Arbeitsblattkauf ist nicht nötig. Wiederholungszahlen und Erklärungen über hohe Schwingungen sind keine gesicherten Wirksamkeitsbelege."},{id:"manifest-P07",title:"Practitioner account · Two-cup method",url:"https://www.reddit.com/r/Manifestation/comments/1poqa0q/insanely_powerful_technique/",type:"technique",finding:"Anleitung aus erster Hand: Zwei Becher mit der aktuellen und der gewünschten Situation beschriften, sich die Veränderung vorstellen, Wasser vom ersten in den zweiten gießen und dann trinken.",limitation:"Anonymer Praxisbericht, kein überprüfter Beleg für Ursache und Wirkung. Wechsel zwischen Wirklichkeiten und erzwungene Ergebnisse sind unbelegte Behauptungen. Nur normales Trinkwasser und saubere Becher verwenden."},{id:"manifest-P08",title:"Sandy · Pillow method guide",url:"https://theprettythoughts.com/the-pillow-method-an-easy-way-to-manifest/",type:"technique",finding:"Anleitung aus der Praxis: Einen Wunsch im Präsens aufschreiben, den gefalteten Zettel unter ein Kopfkissen legen und den Wunsch beim Einschlafen wiederholen oder vorstellen.",limitation:"Wiederholungen und Faltungen unterscheiden sich. Behauptungen über den Zettel, das Unterbewusstsein, Kristalle, Öle und Anziehung sind keine kontrollierten Wirksamkeitsbelege."},{id:"manifest-P09",title:"Sandy · Whisper method guide",url:"https://theprettythoughts.com/the-viral-whisper-method-manifestation-technique/",type:"technique",finding:"Anleitung aus der Praxis: Entspannen, sich vorstellen, zu einem anderen Menschen zu gehen, ihm eine gewünschte Bitte dreimal ins Ohr zu flüstern und die vorgestellte Szene zu verlassen.",limitation:"Ein persönlicher Bericht, kein Beleg für Telepathie. Eine vorgestellte Bitte belegt keine Kontrolle über andere und kann weder deren Zustimmung ersetzen noch ihre Grenzen aufheben."},{id:"manifest-P10",title:"Simi · The Gratitude Game",url:"https://www.thesecret.tv/stories/the-gratitude-game/",type:"technique",finding:"Ein Praxisbericht aus erster Hand beschreibt ein Dankbarkeitstagebuch: Dinge aufschreiben, die man schätzt, die Gründe dafür ergänzen und die Einträge erneut lesen.",limitation:"Ein persönlicher Bericht, keine Interventionsstudie. Die Geschichte belegt nicht, dass Dankbarkeit Ereignisse anzieht oder Probleme beseitigt."},{id:"manifest-P11",title:"Alexandra · Act as if it is already done",url:"https://www.thesecret.tv/stories/act-as-if-its-already-done/",type:"technique",finding:"Ein Bericht aus erster Hand beschreibt, wie Kleidung und Gepäck vorbereitet werden, als sei der erhoffte Job bestätigt, während die Person sich das gewünschte Ergebnis vorstellt.",limitation:"Die Autorin berichtet von einem Angebot durch einen bereits bekannten Menschen. Eine Anekdote kann Ursachen nicht voneinander trennen und kein allgemeines Gesetz der Anziehung bestätigen."},{id:"manifest-P12",title:"Victoria Jackson · Letter from your future self",url:"https://themanifestationcollective.co/wp-content/uploads/2021/04/Scripting-To-Success-Masterclass.pdf",type:"technique",finding:"Die Praxisvorlage beschreibt einen Brief des vorgestellten zukünftigen Ichs an das heutige Ich über Veränderungen im Leben und mitfühlende Worte.",limitation:"Die Seiten 6-7 dokumentieren die Übung, keine Kommunikation mit der Zukunft oder Wirksamkeit für äußere Ergebnisse. Datum und Anrede sind optionale Entscheidungen zur Briefform."},{id:"manifest-P13",title:"Abraham / Esther and Jerry Hicks · 17-second focus",url:"https://spiritlibrary.com/abraham-hicks/only-17-seconds-away-from-your-true-desires",type:"technique",finding:"Das Lehrtranskript fordert dazu auf, einen gewünschten Gedanken 17 Sekunden ohne Widerspruch festzuhalten. Eine Variante nutzt vier Abschnitte mit insgesamt 68 Sekunden.",limitation:"Eine spirituelle Lehre, keine kontrollierten Belege. Genaue Schwellen, ein angebliches „Entzünden“ von Gedanken, das Herbeiführen äußerer Ereignisse und behauptete Entsprechungen in Arbeitsstunden sind nicht belegt."},{id:"manifest-P14",title:"Amy Parker · Creating a manifestation box",url:"https://envibelife.com/creating-a-manifestation-box/",type:"technique",finding:"Anleitung aus eigener Praxis: Karten mit Absichten oder Bilder in eine Box legen, gewünschte Gefühle ergänzen und den Inhalt immer wieder ansehen.",limitation:"Dokumentiert eine symbolische Praxis. Erklärungen über Energiefelder und Manifestation sind Glaubensvorstellungen, keine wissenschaftlichen Befunde. Ein vorhandener Behälter genügt."},{id:"manifest-P15",title:"Neville Goddard · Five Lessons, 1948",url:"https://readnevillegoddard.com/five-lessons/",type:"technique",finding:"Der Originaltext des Lehrers beschreibt schläfrige Entspannung, eine kurze Szene des erfüllten Wunsches, das Miterleben aus eigener Perspektive und Wiederholung, bis sich die vorgestellte Handlung real anfühlt.",limitation:"Die kostenlose Abschrift dokumentiert die SATS-Lehre, keine Wirksamkeit. Metaphysische Behauptungen zu äußeren Ergebnissen und dazu, dass Handeln unnötig sei, sind keine wissenschaftlichen Belege. Schlaf geht vor."}],d=[{number:6,technique:"3-6-9-Methode",title:"3-6-9: Noch ein Satz, noch keine Bewerbung?",goal:"Nutze dein Heft für einen Schritt zu einem konkreten Bewerbungsziel.",hook:"Schon wieder „Ich habe die Stelle“ geschrieben? Schick dem Unternehmen auf der anderen Seite eine Bewerbung.",reason:"Bringt dich das Heft deinem Wunschjob näher, oder fehlt dir Zeit zum Bewerben?",paragraphs:["Bei der 3-6-9-Methode schreibst du eine Affirmation in der Gegenwart: morgens dreimal, mittags sechsmal, abends neunmal. Die Variante mit zwei Seiten setzt Wunschunternehmen nach links und „Ich habe die Stelle“ nach rechts. Nicht belegt: Besondere Zahlen ziehen eine Zusage an. Eine Erfolgsgeschichte trennt Wiederholungen nicht von Bewerbungen und zeigt nicht, wie viele Versuche ohne Erfolg blieben.","Die ODA-Version: Behalte beide Seiten und, wenn du magst, den Rhythmus. Links stehen konkrete Unternehmen und dein heutiger Schritt: bewerben, nachfragen oder vorbereiten. Rechts stehen ein glaubwürdiger Satz über dich und ein Wenn-dann-Plan für ein Hindernis. Forschung stützt solche konkreten Pläne. Erledige heute einen Schritt. Prüfe morgen deine Handlung und eine mögliche Antwort getrennt."],example:{title:"Maja nutzt beide Seiten",text:"Maja notiert links zwei Logistikunternehmen und rechts „Ich bereite sinnvolle Bewerbungen vor“. Nach dem Mittagessen prüft sie eine Stellenanzeige und verschickt einen passenden Lebenslauf. Ihr Plan lautet: „Wenn das Portal streikt, speichere ich den Entwurf und kontaktiere die Personalabteilung.“ Ein Portal streikt. Sie hält ihre Anfrage fest. Keines der Unternehmen hat zugesagt."},instructions:["Linke Seite: Nenne ein Unternehmen und deinen heutigen Schritt zum Bewerben, Nachfragen oder Vorbereiten.","Rechte Seite: Schreibe einen Satz über dich und einen Wenn-dann-Plan für ein mögliches Hindernis.","Erledige den Schritt. Prüfe morgen deinen Versuch und eine mögliche Antwort getrennt."],action:["Passende Bewerbung senden","Beim Unternehmen nachfragen"],minimum:["Eine passende Bewerbung einreichen","Eine Rückfrage senden"],cue:["Nach dem Mittagessen","Nach dem morgendlichen Schreiben"],place:["An meinem Bewerbungsschreibtisch","Im Bewerbungsportal des Unternehmens"],obstacle:"Das Bewerbungsportal lädt nicht",fallback:["Entwurf speichern, Personalabteilung kontaktieren","Eine andere verfügbare Bewerbungsgelegenheit nutzen"],observation:["Bewerbung oder Anfrage und mögliche Antwort","Mein erledigter Bewerbungsschritt"],stopRule:"Lass Wiederholungen weg, die deine Handlung verdrängen. Pausiere Bewerbungen, die nicht passen oder die du dir nicht leisten kannst.",scenario:"Maja hat alle 18 Wiederholungen geschrieben und drei Unternehmen aufgelistet. Eine passende Stelle hat heute Abend Bewerbungsschluss. Für die Bewerbung fehlt noch ein kurzer Absatz zu ihrer Berufserfahrung.",question:"Was sollte bei ihrer nächsten Runde mit dem Heft entstehen?",options:[{key:"repeat",text:"Den Schreibrhythmus beibehalten und zuerst einen längeren Satz über sich formulieren, bevor sie mit der Bewerbung weitermacht.",feedback:"Der Satz darf Teil ihres Rituals bleiben. Eine längere Fassung ergänzt aber nicht den fehlenden Absatz. Weil die Frist bald endet, sollte das Heft sie jetzt an genau diesen Absatz erinnern."},{key:"submit",text:"Den fehlenden Absatz schreiben, die Bewerbung abschicken und das Abschicken getrennt von einer möglichen Antwort des Unternehmens festhalten.",feedback:"Das passt zum konkreten Unternehmen und zur Frist. Die Bewerbung ist ihre Handlung. Eine Antwort liegt weiterhin außerhalb ihrer Kontrolle. Wenn sie mag, behält sie das Ritual und prüft danach, was tatsächlich passiert ist."},{key:"expand",text:"Erst die Liste der Unternehmen erweitern, damit sie morgen aus mehr möglichen Stellen auswählen und weitere Bewerbungen planen kann.",feedback:"Eine breitere Suche kann später helfen. Heute Abend gibt es jedoch eine passende Stelle mit einer festen Frist. Weitere Unternehmen aufzulisten würde diese Bewerbung verzögern. Zuerst braucht sie den noch fehlenden Absatz."}],best:"submit",takeaway:"Lass dich vom Heft ans Bewerben erinnern. Zähle Handlungen und Antworten getrennt.",review:"Welchen Bewerbungsschritt hast du versucht? Hat eines der Unternehmen geantwortet?",deeper:[{heading:"Die bekannte Anleitung, auch mit zwei Seiten",paragraphs:["1. Wähle ein gewünschtes Ergebnis und formuliere es so, als wäre es schon wahr. 2. Schreibe diese Affirmation morgens dreimal. 3. Wiederhole sie um die Mittagszeit sechsmal. 4. Schreibe sie abends neunmal. Diese Zahlen gehören zur verbreiteten Anleitung. Sie sind keine wissenschaftlich begründete Dosis. Wie lange der Rhythmus wiederholt wird, unterscheidet sich je nach Anleitung aus der Praxis. [manifest-P01]","5. Im bereitgestellten Zwei-Seiten-Beispiel steht rechts „Ich habe die Stelle“. Links listet die Verfasserin Unternehmen, bei denen sie sich beworben hat und arbeiten möchte. Sie berichtet von einer Zusage eines aufgelisteten Unternehmens. Das ist eine für den Kurs beigesteuerte Geschichte, keine unabhängig geprüfte Studienangabe. Hier einen Überlebendenfehler zu vermuten, ist eine Schlussfolgerung: Der sichtbare Erfolg zeigt nicht die Menschen, die das Ritual ohne Zusage ausprobiert haben. Die Geschichte kann ehrlich erzählt sein. Warum die Zusage kam, bleibt trotzdem offen. [manifest-T14]"]},{heading:"Behalte den Rhythmus und ergänze den nächsten Schritt",paragraphs:["Die Forschung zu Plänen untersucht erkennbare Situationen, die mit einer machbaren Handlung verbunden werden. Sie belegt nicht, dass drei, sechs oder neun Wiederholungen ein Unternehmen beeinflussen. Behalte das Zählen, wenn es dir gefällt. Setze die Aufgabe daneben: ein Unternehmen, eine passende Stelle und deine heutige Handlung. Die Liste links und echte Bewerbungen eröffnen einen praktischen Weg zu einer Zusage. Diese einzelne Geschichte beweist nicht, welcher Faktor die Zusage verursacht hat. [manifest-T02, manifest-T14]","Rechts könntest du schreiben: „Ich bereite sinnvolle Bewerbungen vor.“ Ergänze: „Wenn das Portal streikt, speichere ich den Entwurf und kontaktiere die Personalabteilung.“ Prüfe Frist, Zugang und verfügbare Zeit. Bewirb dich oder frage heute nach. Halte genau diese Handlung fest. Schau morgen nach einer Antwort des Unternehmens. Schweigen ist kein Beleg für mangelnden Glauben. Wiederholungen, Vorbereitung, abgeschickte Bewerbungen und Zusagen bekommen getrennte Einträge. Dieses Paket mit zwei Seiten ist eine ODA-Anpassung, keine getestete Intervention. [manifest-T02]"]}],sources:["manifest-P01","manifest-T02","manifest-T14"]},{number:7,technique:"Scripting",title:"Scripting: Der Traumjob steht da. Wo bleibt die Vorbereitung?",goal:"Nutze eine Zukunftsszene, um eine Handlung für dein Ziel auszuwählen und zu versuchen.",hook:"Dein ausgedachter Tag endet perfekt. Was hast du vor dem Frühstück dafür getan?",reason:"Was tust du nach dieser Seite, bevor du die nächste schreibst?",paragraphs:["Beim Scripting schreibst du einen Tagebucheintrag, als würde deine gewünschte Zukunft gerade stattfinden. Wähle eine Szene, beschreibe Einzelheiten und Gefühle und lies den Text noch einmal. Gemischte Befundlage: Verwandte Schreibübungen zum bestmöglichen Selbst verbesserten Wohlbefinden und Optimismus im Durchschnitt. Sie zeigen nicht, dass Einträge in der Gegenwart Ereignisse herbeiführen. Studien zum expressiven Schreiben betreffen echte Erfahrungen, keine Wünsche, die zu Tatsachen werden.","Die ODA-Version: Behalte die Szene und ergänze die Arbeit, die davor nötig wäre. Nenne dein konkretes Ziel, ein aktuelles Hindernis und einen Wenn-dann-Plan. Unterstreiche eine Handlung, die du heute versuchen kannst. Vergleiche morgen deinen Versuch mit dem Plan. Prüfe nicht, ob die ganze Szene eingetreten ist. Diese Kombination ist eine Anpassung."],example:{title:"Lena ergänzt die fehlende Arbeit",text:"Lena beschreibt einen ruhigen Morgen in ihrer neuen Stelle und ergänzt die Vorbereitung aufs Vorstellungsgespräch. Nach dem Abendessen nimmt sie eine Antwort zum Umgang mit schwierigen Kunden auf. Sie hört, dass sie hetzt, und markiert einen Satz zum Kürzen. Die Stelle bleibt ausgedacht. Ihre echte Aufnahme kann sie morgen verbessern."},instructions:["Schreibe die Zukunftsszene auf. Ergänze, welche Arbeit und welche Mittel dafür nötig wären.","Unterstreiche die heutige Handlung. Ergänze: „Wenn dieses Hindernis auftaucht, dann werde ich …“","Versuche dein Minimum und prüfe morgen, was dabei passiert ist."],action:["Eine Antwort fürs Vorstellungsgespräch aufnehmen","Eine Projektbeschreibung entwerfen"],minimum:["Eine Antwort als Aufnahme speichern","Eine brauchbare Projektbeschreibung speichern"],cue:["Nach dem Abräumen des Abendessens","Wenn ich mein Tagebuch schließe"],place:["An meinem Küchentisch","In meinem Portfolio-Dokument"],obstacle:"Mir fällt kein perfekter erster Satz ein",fallback:["Mit einem Entwurf anfangen","Um ein konkretes Beispiel bitten"],observation:["Meine gespeicherte Aufnahme","Mein Entwurf und die offene Lücke"],stopRule:"Lass belastende Szenen weg. Nutze einfache Notizen zur Aufgabe, wenn dir das Schreiben über die Zukunft nicht guttut.",scenario:"Lenas Text beschreibt ein selbstsicheres Vorstellungsgespräch. Das Gespräch ist morgen. Für eine typische Frage zum Kundenservice hat sie noch kein Beispiel vorbereitet.",question:"Welche Ergänzung macht die Seite heute Abend nützlich?",options:[{key:"draft",text:"Ein echtes Erlebnis mit einem Kunden ergänzen, eine Antwort üben und eine erste Aufnahme für die Prüfung morgen speichern.",feedback:"So verbindet sie die Szene mit der morgigen Aufgabe. Eine erste Antwort kann zeigen, was noch fehlt. Sie sichert Lena keine Stelle, liefert aber Vorbereitung, die sie anhören und verbessern kann."},{key:"feelings",text:"Das Gefühl von Selbstsicherheit genauer beschreiben, bevor sie entscheidet, welches Erlebnis mit einem Kunden zur Antwort passen könnte.",feedback:"Gefühle zu erkunden kann der Szene Bedeutung geben. Hier fehlt jedoch eine Antwort mit einer echten Erfahrung. Mehr Gefühlsdetails schließen diese Lücke nicht. Lena sollte ein Beispiel auswählen und die Antwort üben."},{key:"edit",text:"Den ganzen Tagebucheintrag überarbeiten, damit das ausgedachte Vorstellungsgespräch als klare und stimmige Geschichte von Anfang bis Ende funktioniert.",feedback:"Eine stimmige Geschichte kann ein Schreibziel sein. Lenas unmittelbares Ziel ist aber eine vorbereitete Antwort. Die Geschichte zu glätten verbraucht ihren knappen Abend, ohne das nötige Beispiel für das Gespräch zu liefern."}],best:"draft",takeaway:"Schreibe über eine Zukunft, die dir etwas bedeutet. Erledige heute Arbeit dafür.",review:"Welchen Schritt aus deinem Text hast du versucht? Was ist noch offen?",deeper:[{heading:"So läuft Scripting üblicherweise ab",paragraphs:["1. Wähle eine gewünschte Situation, etwa einen Arbeitstag in deiner Wunschstelle. 2. Schreibe einen Tagebucheintrag, als würde dieser Tag gerade stattfinden. 3. Beschreibe alltägliche Einzelheiten: Wo bist du, was tust du und wie fühlt sich die Szene an? 4. Lies den Text und komm darauf zurück, wenn du möchtest. Manche Varianten ergänzen Dankbarkeit oder ein Gefühl von Gewissheit. Das sind Anleitungen aus der Praxis, kein wissenschaftlich bestätigter Weg zu einer Zusage. [manifest-P02]","Kennzeichne ausgedachte Ereignisse als ausgedacht. Du kannst eine gewöhnliche Szene schreiben, ohne jemand anderem ein Versprechen zuzuschreiben, das diese Person nie gegeben hat. Ergänze für die ODA-Übung die nötige Arbeit, verfügbare Mittel und ein Hindernis, das du gerade erlebst. Wähle eine einzige Aufgabe von der Seite. Tippen oder Diktieren kann die Übung zugänglicher machen. Wir behaupten nicht, dass jede Form in der Forschung dieselben Wirkungen hat. Das Ritual bleibt freiwillig. [manifest-P02]"]},{heading:"Zukunftstexte und Texte über Erlebtes unterscheiden sich",paragraphs:["Bei der Forschung zum bestmöglichen Selbst stellen Menschen sich vor, wie ihre Zukunft nach eigener Anstrengung aussehen könnte. Das Team um Carrillo fand im Durchschnitt Vorteile für Wohlbefinden, Optimismus und positive Gefühle. Die Qualität der Studien setzte den Aussagen Grenzen. Daraus lässt sich eine begrenzte Erwartung an reflektierendes Schreiben ableiten. Es belegt nicht, dass Scripting in der Gegenwart die beschriebenen Ereignisse auslöst. Expressives Schreiben hat einen anderen Gegenstand: echte Erfahrungen oder Gefühle. Auch sein kleiner durchschnittlicher Nutzen bestätigt keine Anziehung künftiger Ereignisse. [manifest-T08, manifest-T12]","ODA behält die Erzählung und ergänzt einen praktischen Weg zum Handeln. Wähle ein konkretes Ziel, das du bereits in deinem Kursversuch verfolgst. Nenne, was deinen heutigen Schritt verhindern könnte. Schreibe auf, was du dann tun kannst und dir leisten kannst. Speichere eine Gelegenheit und ein Minimum, versuche es und prüfe morgen das Ergebnis. Eine geübte Interviewantwort ist Vorbereitung, eine abgeschickte Bewerbung ist eine Bewerbung, und eine Antwort zählt erst, wenn sie ankommt. Dieser Ablauf ist eine gestalterische Anpassung. Er entspricht keiner der beiden ursprünglich untersuchten Schreibinterventionen."]}],sources:["manifest-P02","manifest-T08","manifest-T12"]},{number:8,technique:"Vision Board",title:"Vision Board: Schöne Bilder, unfertiges Portfolio?",goal:"Nutze ein Bild auf deinem Board als Erinnerung an eine machbare Handlung.",hook:"Der Schreibtisch auf deinem Vision Board sieht toll aus. Was machst du heute an deinem eigenen?",reason:"Welches Bild zeigt deine Priorität statt fremder Erfolgsvorstellungen?",paragraphs:["Ein Vision Board sammelt Bilder und Wörter für dein gewünschtes Leben. Wähle Bilder, ordne sie an, platziere das Board sichtbar und schau wieder darauf. Gemischte Befundlage: Aktuelle Ziele können Aufmerksamkeit lenken, ebenso auffällige Reize und frühere Erfahrungen. Das beweist weder die Wirksamkeit eines Boards noch, dass Bilder Gelegenheiten anziehen. Das retikuläre Aktivierungssystem betrifft Wachheit und Aktivierung. Es als programmierbaren Wunschfilter zu bezeichnen, geht über die Befunde hinaus.","ODA-Version: Behalte ein Bild, das dir etwas bedeutet. Schreibe sein konkretes Ziel und eine heutige Handlung dazu. Nenne ein Hindernis und einen Wenn-dann-Plan. Das Bild soll dich ans Anfangen erinnern. Prüfe morgen, ob du dadurch dein Minimum versucht hast. Eine Gelegenheit bemerken heißt nicht, sie zu erschaffen."],example:{title:"Nora gibt dem Schreibtisch eine Aufgabe",text:"Noras Board zeigt einen Schreibtisch im Designstudio. Sie schreibt darunter: „Eine Arbeitsprobe fürs Portfolio erstellen.“ Als sie das Bild nach dem Frühstück sieht, öffnet sie ihr unfertiges Projekt und schreibt eine Beschreibung. Der Text ist weniger aufregend als der Traum vom Studio. Sie speichert ihn trotzdem und notiert: Das Projekt braucht Feedback."},instructions:["Wähle ein Bild. Schreibe sein konkretes Ziel und deine heutige nützliche Handlung dazu.","Lass dich vom Bild ans Anfangen erinnern. Plane, was du bei einem wahrscheinlichen Hindernis tust.","Versuche die Handlung. Prüfe morgen, ob du die Erinnerung bemerkt hast."],action:["Eine Projektbeschreibung schreiben","Um Feedback zum Projekt bitten"],minimum:["Eine brauchbare Projektbeschreibung speichern","Eine gezielte Frage für Feedback senden"],cue:["Beim Blick aufs Board nach dem Frühstück","Wenn ich meinen Projektordner öffne"],place:["An meinem Schreibtisch","In meinem Portfolio-Dokument"],obstacle:"Das Bild lädt zum Stöbern statt zum Arbeiten ein",fallback:["Vor dem Stöbern das Projekt öffnen","Eine Texterinnerung neben die Datei setzen"],observation:["Ob ich beim Bild tatsächlich angefangen habe","Meine fertige Beschreibung oder Anfrage"],stopRule:"Nutze vorhandene Bilder oder Wörter. Lass Bilder weg, die dich unter Druck setzen, Geld auszugeben.",scenario:"Nora sieht ihr Board jeden Morgen. Danach schaut sie sich Fotos von Designstudios an. In ihrem Portfolio fehlt die Beschreibung, die ein abgeschlossenes Projekt erklärt.",question:"Welche Änderung hilft ihr am meisten?",options:[{key:"fresh",text:"Das Studiofoto durch ein inspirierenderes Bild ersetzen, damit das Board wieder besser zu ihrem Wunsch passt und sie neu motiviert.",feedback:"Ein neues Bild kann Freude machen. Ihr Eintrag zeigt aber: Nach dem Blick aufs Board stöbert sie weiter. Ihr fehlt kein Wunsch. Sie muss ändern, was sie beim Anblick des Bildes tun soll."},{key:"study",text:"Am nächsten Morgen verschiedene Studioportfolios vergleichen, um besser zu verstehen, welchen Standard sie mit ihrer eigenen Arbeit erreichen möchte.",feedback:"Vergleiche können später nützlich sein. Nora hat bereits ein fertiges Projekt, dem die Beschreibung fehlt. Weiteres Stöbern wiederholt das bisherige Muster, wenn es keine konkrete Frage für genau diese Beschreibung beantwortet."},{key:"label",text:"„Projekt öffnen, Beschreibung schreiben“ unter das Bild setzen und eine Beschreibung speichern, bevor sie sich weitere Studiofotos ansieht.",feedback:"So verbindet sie die vorhandene Erinnerung mit der fehlenden Handlung. Morgen kann Nora prüfen, ob sie die Beschriftung bemerkt und die Beschreibung gespeichert hat. Das Board selbst garantiert ihr keine Stelle im Studio."}],best:"label",takeaway:"Gib dem Bild eine Aufgabe und einen Startmoment. Prüfe die Aufgabe, nicht die Kraft des Bildes.",review:"Hat dein Bild dich zur gespeicherten Handlung geführt oder zu etwas anderem?",deeper:[{heading:"Ein Board gestalten, ohne etwas zu kaufen",paragraphs:["1. Wähle eine gewünschte Richtung oder Situation. 2. Sammle einige Bilder und Wörter, die dafür stehen. 3. Ordne sie auf Papier, auf einer vorhandenen Pinnwand oder auf einer digitalen Seite an. 4. Platziere die Sammlung dort, wo du wieder darauf schauen möchtest. 5. Betrachte sie und stelle dir die gewünschte Situation vor. Diese Schritte beschreiben die Übung aus der Praxis. Sie sind kein Beleg dafür, dass ein Board die Situation entstehen lässt. [manifest-P03]","Bleib in diesem Kurs bei einer Richtung, statt jede mögliche Verbesserung deines Lebens auf das Board zu setzen. Ein vorhandenes Foto, eine Skizze oder ein geschriebenes Wort reicht. Nenne unter einem Bild die tatsächliche Aufgabe: nach einer Weiterbildung fragen, eine Arbeitsprobe fertigstellen oder eine passende Bewerbung abschicken. Wähle einen Ort, an dem du handeln kannst, sobald du das Bild siehst. Materialien und Anordnung sind Geschmackssache. Die Wissenschaft verlangt keine besonderen gekauften Utensilien. Bilder anzuordnen und die Aufgabe zu erledigen bleiben getrennte Tätigkeiten."]},{heading:"Was Aufmerksamkeit erklären kann und was offen bleibt",paragraphs:["Aufmerksamkeitsforschung beschreibt, wie aktuelle Ziele, auffällige Reize und das, was wir früher ausgewählt haben, unsere Wahrnehmung beeinflussen. Gezieltes Suchen nach passenden Gelegenheiten ist dadurch plausibel. Es bestätigt aber nicht jede Methode, die angeblich unsere Aufmerksamkeit verbessert. Das retikuläre Aktivierungssystem ist an Schaltkreisen für Wachheit und Aktivierung beteiligt. Diese Befunde belegen keinen vom Board gesteuerten Filter, der eine Stelle, eine Partnerschaft oder ein Haus liefert. Eine gerade bemerkte Gelegenheit kann schon bestanden haben, bevor du auf sie aufmerksam wurdest. [manifest-T15, manifest-T19]","ODA nutzt das Bild als ausdrückliche Erinnerung, statt ihm einen verborgenen Mechanismus zuzuschreiben. Schreibe das Ziel, die heutige Handlung und eine Antwort auf das Hindernis auf, das sie wahrscheinlich unterbricht. Wenn du nach dem Blick aufs Board wieder nur stöberst, plane, zuerst die Arbeitsdatei zu öffnen. Prüfe morgen: War das Bild zu sehen? Hast du es bemerkt? Was hast du tatsächlich getan? Halte Reaktionen von außen getrennt fest. Dieses Paket aus Bild und Plan wurde nicht als Vision-Board-Intervention getestet."]}],sources:["manifest-P03","manifest-T15","manifest-T19"]},{number:9,technique:"Affirmationen",title:"Affirmationen: Der Erfolgssatz klingt falsch?",goal:"Verbinde einen ermutigenden Satz mit einer sichtbaren Handlung für dein Ziel.",hook:"„Ich bin unglaublich erfolgreich“ klingt falsch? Nimm einen Satz, mit dem du etwas anfangen kannst.",reason:"Hilft der Satz beim Anfangen, oder setzt er dich unter Druck, Gewissheit zu fühlen?",paragraphs:["Affirmationen sind ermutigende Sätze, die du wiederholt sagst oder schreibst. Oft klingt das gewünschte Ergebnis schon erreicht. Wähle einen Satz, wiederhole ihn und stelle dir vor, du glaubst ihn. Gemischte Befundlage: Woods Team fand, dass ein stark positiver Satz die Stimmung einiger Teilnehmender mit geringem Selbstwertgefühl verschlechterte. Selbstaffirmation in der Forschung meint oft Nachdenken über wichtige Werte statt Erfolgssprüche. Befunde zum Gesundheitsverhalten belegen keine Anziehung von Stellenangeboten.","ODA-Version: Behalte einen brauchbaren, ermutigenden Satz. Nenne einen Wert und eine passende Handlung: „Ich bereite ein ehrliches Beispiel vor.“ Wähle ein konkretes Ziel, ein Hindernis und einen Wenn-dann-Plan. Versuche die Handlung heute. Prüfe morgen deinen Versuch. Ändere den Satz oder lass ihn weg, wenn du dich damit schlechter fühlst."],example:{title:"Lea ändert ihren Satz",text:"Lea wiederholt vor einer Besprechung „Ich bin eine herausragende Rednerin“ und fühlt sich verlegener. Sie wechselt zu „Ich bereite einen klaren Punkt vor“. Am Schreibtisch notiert und übt sie einen Vorschlag. Im Meeting sagt sie den Einstiegssatz, verliert aber den Faden. Sie notiert ihren Beitrag und die unvollständige Erklärung."},instructions:["Wähle einen ermutigenden Satz, der einen Wert mit einer konkreten Handlung verbindet.","Nenne ein Hindernis und einen machbaren Wenn-dann-Plan. Du musst dich nicht zum Glauben zwingen.","Versuche die Handlung heute. Prüfe morgen deinen Versuch und wie du den Satz erlebt hast."],action:["Einen vorbereiteten Satz im Meeting sagen","Eine klare Projektfrage stellen"],minimum:["Den ersten Satz meines Vorschlags sagen","Eine konkrete Projektfrage senden"],cue:["Wenn im Meeting Vorschläge gefragt sind","Wenn ich den Projektchat öffne"],place:["In unserem Besprechungsraum","Im Projektchat"],obstacle:"Mein ermutigender Satz fühlt sich falsch an",fallback:["Vorbereiteten Satz ohne Affirmation nutzen","Eine einfache Erinnerung an die Handlung nutzen"],observation:["Mein Beitrag und die Reaktion darauf","Ob der Satz half oder sich schlechter anfühlte"],stopRule:"Ändere belastende Aussagen oder lass sie weg. Du musst dich nicht zu Gewissheit zwingen.",scenario:"Lea fühlt sich durch ihren wiederholten Erfolgssatz schlechter. Sie möchte trotzdem einen hilfreichen Vorschlag in einer Besprechung machen. Eine erste Fassung ihres Satzes liegt schon bereit.",question:"Welche Anpassung wird beiden Tatsachen gerecht?",options:[{key:"persist",text:"Den Erfolgssatz noch einige Male weiter verwenden, bevor sie ihn ändert, und währenddessen ihren vorbereiteten Vorschlag weiter laut üben.",feedback:"Üben kann die Vorbereitung unterstützen. Es gibt aber keine Pflicht, einen Satz fortzusetzen, der ihre Stimmung verschlechtert. Mit dem vorbereiteten Vorschlag kann Lea auch anfangen, ohne sich zu einem Glauben zu zwingen."},{key:"action",text:"Eine einfache Erinnerung an die Handlung nutzen oder die Affirmation weglassen und den vorbereiteten Satz sagen, sobald Vorschläge gefragt sind.",feedback:"Das erhält ihren machbaren Beitrag und nimmt ihr berichtetes Unbehagen ernst. Lea kann danach prüfen, was sie gesagt und wie sich die Erinnerung angefühlt hat. Sie muss nicht sicher sein, eine herausragende Rednerin zu sein."},{key:"wait",text:"Einen stärkeren Satz über ihre persönlichen Stärken formulieren und den Vorschlag verschieben, bis sie sich von diesen Stärken mehr überzeugt fühlt.",feedback:"Über Werte nachzudenken ist etwas anderes, als sich einen großen Erfolgssatz einzureden. Wenn Lea auf Überzeugung wartet, macht sie Selbstsicherheit zur Voraussetzung für eine bereits vorbereitete Handlung. Der Beitrag darf klein und der Satz freiwillig bleiben."}],best:"action",takeaway:"Der Satz darf dich erinnern. Was du tust, liefert die Belege.",review:"Was hast du versucht? Hat der Satz geholfen, gestört oder keinen Unterschied gemacht?",deeper:[{heading:"So werden Affirmationen häufig verwendet",paragraphs:["1. Wähle ein Ergebnis oder eine persönliche Eigenschaft. 2. Formuliere sie positiv, häufig in der Gegenwart. 3. Sage oder schreibe den Satz wiederholt. 4. Stelle dir dabei die gewünschte Situation vor. 5. Komm zu einer gewählten Zeit auf den Satz zurück. Häufigkeit und Wortlaut unterscheiden sich je nach Anleitung aus der Praxis. Die bekannte Vorgehensweise begründet weder eine wissenschaftlich erforderliche Anzahl noch ein Gefühl, das du unbedingt erreichen musst. [manifest-P04]","Du darfst Freude an der Übung haben, ohne ihr größtes Versprechen zu übernehmen. Nutze bei ODA einen Satz, der auf eine Arbeit zeigt, die du tatsächlich versuchen kannst. „Ich bereite einen klaren Punkt vor“ kann neben deinen Besprechungsnotizen stehen. Du kannst auch ganz auf einen Satz verzichten. Eine unangenehme oder unglaubwürdige Aussage ist keine Prüfung, die du bestehen musst. Das Team um Wood untersuchte einen bestimmten positiven Satz und kurzfristige Stimmungseffekte. Daraus folgt nicht, dass jeder freundliche Satz schadet. [manifest-T06]"]},{heading:"Ein Wert ist etwas anderes als ein Erfolgsspruch",paragraphs:["In der Forschung zur Selbstaffirmation denken Menschen oft über wichtige Werte, Eigenschaften oder Beziehungen nach, bevor sie auf möglicherweise bedrohliche Informationen treffen. Das Team um Epton fasste Experimente zu Gesundheitsbotschaften zusammen. Es fand kleine durchschnittliche Effekte auf die Akzeptanz der Botschaften und die Absicht, das Verhalten zu ändern. Auch beim Verhalten zeigte sich in diesem Kontext ein Vorteil. Diese Verfahren unterscheiden sich davon, ein gewünschtes Ergebnis als bereits wahr zu wiederholen. Sie belegen nicht, dass auf „Ich habe die Stelle“ eine Zusage folgt. [manifest-T07]","ODA übernimmt diese Unterscheidung, ohne das ganze Ritual als geprüft auszugeben. Wähle einen Wert wie Ehrlichkeit. Nenne eine Art, ihn bei deinem bestehenden Ziel auszudrücken: ein zutreffendes Beispiel deiner Arbeit vorbereiten. Speichere die Gelegenheit und das Minimum. Schreibe auf, was du bei einem wahrscheinlichen Hindernis tust, etwa wenn du den Faden verlierst. Versuche den Satz heute. Halte morgen den tatsächlichen Beitrag fest und ob du den Satz gebrauchen konntest. Lass die Affirmation weg, wenn sie Druck erzeugt. Behalte die machbare Handlung. [manifest-T06, manifest-T07]"]}],sources:["manifest-P04","manifest-T06","manifest-T07"]},{number:10,technique:"Visualisieren",title:"Visualisieren: Die Zusage im Kopf, die Antwort offen?",goal:"Wähle eine Aufgabe, übe eine Schwierigkeit und versuche es anschließend tatsächlich.",hook:"Du siehst die Zusage vor dir. Übe die Antwort auf die Frage davor.",reason:"Zeigt dir eine weitere Szene eine nützliche Lücke, oder verzögert sie eine schon vorbereitete Handlung?",paragraphs:["Beim Visualisieren stellst du dir ein gewünschtes Ereignis vor, oft mit Sinneseindrücken und Erfolgsgefühl. Komm zur Ruhe, stell dir die Szene vor und nimm gedanklich teil. Wiederhole sie, wenn du magst. Gemischte Befundlage: Gedankliches Durchspielen unterstützte späteres Verhalten im Durchschnitt. Es belegt keine Anziehung von Ereignissen. Eine frühe Prüfungsstudie sprach in einigen Vergleichen für Prozessbilder. Die spätere Metaanalyse fand keine verlässlich bessere Form.","Die ODA-Version: Behalte eine kurze Ergebnisszene. Übe danach deine Aufgabe und ein Hindernis gedanklich. Wähle ein konkretes Ziel und einen Wenn-dann-Plan, versuche heute eine Handlung und prüfe sie morgen. Gedankliches Üben bleibt Vorbereitung. Fehlen Bilder, schreibe die Schritte auf. Du brauchst weder ein lebhaftes Bild noch ein besonderes Gefühl."],example:{title:"Ben übt die schwierige Frage",text:"Ben stellt sich ein abgeschlossenes Vorstellungsgespräch vor. Danach übt er, eine Lücke im Lebenslauf zu erklären. Wenn er stockt, will er mit den Zeitangaben beginnen. Nach dem Mittagessen nimmt er eine Antwort auf. Was er gelernt hat, fehlt. Er ergänzt einen Satz. Die Antwort braucht Übung. Ein Gesprächsergebnis fehlt noch."},instructions:["Stell dir kurz das Ergebnis vor. Übe danach die nächste Aufgabe und eine wahrscheinliche Schwierigkeit.","Schreibe ein konkretes Ziel auf und plane: Wenn diese Schwierigkeit auftaucht, dann tue ich …","Versuche die Handlung heute. Prüfe sie morgen getrennt von deiner gedanklichen Vorbereitung."],action:["Eine Antwort fürs Vorstellungsgespräch aufnehmen","Einen vorbereiteten Vorschlag senden"],minimum:["Eine erste Antwortaufnahme speichern","Einen Satz mit meinem Vorschlag senden"],cue:["Nach dem Mittagessen","Wenn im Meeting Beiträge gefragt sind"],place:["An meinem Schreibtisch fürs Üben","Im Teamchat"],obstacle:"Beim ersten Satz fehlen mir die Worte",fallback:["Mit den Zeitangaben in meinen Notizen beginnen","Den kurzen vorbereiteten Einstieg vorlesen"],observation:["Meine tatsächlich aufgenommene Antwort","Vorbereitung und tatsächlicher Beitrag getrennt"],stopRule:"Hör mit den inneren Bildern auf, wenn sie dich stärker belasten. Nutze einfache Aufgabennotizen und eine Gelegenheit tagsüber.",scenario:"Ben hat sich zweimal ein erfolgreiches Vorstellungsgespräch vorgestellt. Seine gespeicherte Übungsantwort weicht der Lücke im Lebenslauf noch immer aus. Er hat fünf Minuten, bevor er losmuss.",question:"Wie kann das gedankliche Üben diese Lücke aufgreifen?",options:[{key:"rehearse",text:"Den ersten Satz zur Lücke im Lebenslauf gedanklich üben, eine erste Antwort aufnehmen und prüfen, ob die nötigen Zeitangaben darin vorkommen.",feedback:"So greift die Vorbereitung die beobachtete Lücke auf und liefert eine Aufnahme zum Prüfen. Innere Bilder sichern ihm kein Gesprächsergebnis. Hier sollen sie Ben helfen, die Antwort tatsächlich zu versuchen."},{key:"outcome",text:"Die Szene des erfolgreichen Gesprächs mit mehr Einzelheiten wiederholen und danach festhalten, wie selbstsicher er sich durch diese Vorstellung fühlt.",feedback:"Selbstsicherheit kann eine Beobachtung sein. Sie beantwortet aber nicht die offene Frage. Bens Aufnahme zeigt, welche konkrete Erklärung er üben muss. Nutze die verbleibende Zeit, um genau diese Erklärung zu üben und aufzunehmen."},{key:"research",text:"Die verbleibende Zeit nutzen, um verschiedene Methoden zum Visualisieren zu vergleichen und dann eine für die Übung heute Abend auszuwählen.",feedback:"Methoden zu vergleichen kann interessant sein. Die Befunde hier verlangen aber keine bestimmte Form, bevor er anfängt. Ben kennt die fehlende Aufgabe schon. Ein kurzer Versuch liefert dazu passendere Informationen als eine weitere Methodensuche."}],best:"rehearse",takeaway:"Lass die Szene eine Aufgabe zeigen. Üben bereitet vor. Der Versuch prüft.",review:"Was hast du nach dem Üben tatsächlich versucht? Welche Lücke wurde dabei sichtbar?",deeper:[{heading:"Die bekannte Szene vom gewünschten Ergebnis",paragraphs:["1. Wähle ein Ereignis, das du dir wünschst. 2. Mach es dir an einem angenehmen Ort bequem. 3. Stell dir eine kurze Szene vor, die das gewünschte Ergebnis zeigt. 4. Stell dir vor, selbst teilzunehmen, mit Einzelheiten, die dir etwas bedeuten. 5. Kehre zur Szene zurück, wenn du möchtest. Manche Anleitungen verlangen starke Gefühle oder das Gefühl, das Ergebnis schon zu haben. Diese Schritte dokumentieren ein Ritual. Sie belegen nicht, dass die Szene ein Ereignis von außen anzieht. [manifest-P05]","Halte die Ergebnisszene bei ODA so kurz, dass noch Zeit für die Arbeit bleibt. Finde die nächste Aufgabe, die zwischen heute und dieser Szene liegt. Übe eine Schwierigkeit dieser Aufgabe gedanklich. Schreibe danach auf, was du versuchen willst. Wer keine lebhaften Bilder entwickelt, kann stattdessen die Schritte beschreiben. Das macht die Übung zugänglicher, beweist aber nicht, dass jede Form der Vorbereitung gleich wirkt. Eine ausgedachte Antwort eines Unternehmens darf nie als echte Antwort in deinem Eintrag stehen."]},{heading:"Warum keine Form des Visualisierens immer gewinnt",paragraphs:["Die frühe Prüfungsstudie von Pham und Taylor verglich Bilder vom Lernen, Bilder der gewünschten Note, Kombinationen und eine Kontrollgruppe. Einige Vergleiche sprachen für Bilder vom Lernprozess. Der Befund zur Note rechtfertigt jedoch keinen verlässlichen Vorteil von Prozessbildern gegenüber der Kontrollgruppe. Das Team um Cole fasste später unterschiedliche gedankliche Simulationen zusammen. Im Durchschnitt zeigte sich ein Verhaltensvorteil, ohne belegte Unterschiede zwischen den Formen. Mehrere Untergruppen waren klein. Zu versprechen, eine bestimmte Szene wirke immer am besten, würde diese Befunde überdehnen. [manifest-T17, manifest-T04]","ODA fragt, welche Vorbereitung deine eigene Aufgabe braucht. Kennst du das Ziel, weichst aber dem ersten Satz aus? Dann übe das Anfangen und den Umgang mit genau diesem Hindernis. Speichere ein machbares Minimum, einen Startmoment, einen Ort und deine Antwort aufs Hindernis. Versuche die Handlung heute und prüfe sie morgen. Halte hilfreiches gedankliches Üben und tatsächliche Arbeit getrennt fest. Wenn du immer weiter vorbereitest, ohne es zu versuchen, verkürze die Vorbereitung oder wähle eine andere verfügbare Gelegenheit. Diese konkrete Abfolge von Szene und Versuch ist eine ODA-Anpassung, kein durch die Metaanalyse bestätigtes Verfahren."]}],sources:["manifest-P05","manifest-T04","manifest-T17"]},{number:11,technique:"55x5-Methode",title:"55x5: Lass Zeit für deine Bewerbung",goal:"Schreib freiwillig, tu etwas Machbares und schau später darauf zurück.",hook:"55 Zeilen geschrieben, Bewerbung noch leer? Schreib den nächsten sinnvollen Satz dort, wo du damit weiterarbeiten kannst.",reason:"Wie viel Zeit fürs Schreiben bleibt neben deiner eigentlichen Aufgabe?",paragraphs:["Bei der 55x5-Methode schreibst du fünf Tage täglich 55-mal dieselbe Affirmation in der Gegenwart. Wähle ein gewünschtes Ergebnis und erfülle täglich die vorgegebene Anzahl mit demselben Satz. Nicht belegt ist, dass diese Anzahl oder die fünf Tage das Ergebnis anziehen. In einigen Experimenten sank nach idealisierten Zukunftsfantasien die unmittelbare Energie. Das belegt nicht, dass jede Vorstellung oder dieses Schreibritual die Anstrengung beeinträchtigt.","Die ODA-Variante: Schreib weiter, wenn es dir gefällt. Wiederholungen sind freiwillig. Wähle ein konkretes Ziel und täglich eine machbare Handlung. Benenne ein Hindernis und plane mit einem Wenn-dann-Satz, was du bei einem erkennbaren Anlass tust. Handle heute, bevor du noch mehr schreibst. Schau morgen auf die Aufgabe zurück. Forschung stützt konkrete Planung, nicht den besonderen Wiederholungsrhythmus."],example:{title:"Zeit für Simons Bewerbung",text:"Simon schreibt gern „Ich bereite passende Bewerbungen vor“. Die 55 Zeilen füllen seine Pause. Er behält wenige Zeilen und reserviert nach dem Mittagessen fünf Minuten für die Bewerbung. Fehlt eine Angabe, fragt er die Personalabteilung. Heute sendet er die Frage. Er notiert eine Anfrage, keine Bewerbung oder Zusage."},instructions:["Wähle ein Ziel. Halte zuerst Zeit fürs Handeln frei; entscheide dann, wie oft du schreibst.","Wähle einen erkennbaren Anlass und einen Wenn-dann-Plan für ein Hindernis.","Versuche die heutige Aufgabe und schau morgen darauf zurück. Wiederholungen bleiben freiwillig."],action:["Nach einer fehlenden Angabe fragen","Einen Bewerbungsteil fertigstellen"],minimum:["Eine Frage an die Personalabteilung senden","Einen fertigen Bewerbungsteil speichern"],cue:["Wenn das Mittagessen vorbei ist","Nach meiner freiwilligen Schreibzeit"],place:["Im Mailentwurf an die Personalabteilung","An meinem Platz für Bewerbungen"],obstacle:"Die Wiederholungen brauchen meine ganze verfügbare Zeit",fallback:["Wiederholungen auslassen, Minimum erledigen","Vor dem Schreiben Zeit fürs Handeln freihalten"],observation:["Aufgabe und Schreibzeit getrennt festgehalten","Was ich gesendet oder gespeichert habe"],stopRule:"Schreib weniger oder lass das Schreiben aus, wenn es dich belastet oder deine verfügbare Zeit für die Handlung aufbraucht.",scenario:"Simon hat an zwei Tagen jeweils 55 Wiederholungen geschrieben. An keinem der beiden Tage blieb Zeit für seine Bewerbung. Heute hat er wieder dieselbe kurze Pause.",question:"Mit welcher Änderung kann er einen sinnvolleren Ablauf ausprobieren?",options:[{key:"faster",text:"Er schreibt die Wiederholungen schneller, damit das ganze Ritual bleibt und er danach vielleicht mit der Bewerbung anfangen kann.",feedback:"Auch schnelleres Schreiben kann die ganze Pause füllen. Simon hat festgehalten, dass ihm Zeit für die Bewerbung fehlt. Reserviere zuerst ein machbares Zeitfenster für die Aufgabe. Entscheide danach, wie viel freiwilliges Schreiben noch hineinpasst."},{key:"weekend",text:"Er beendet erst alle fünf Schreibtage und nimmt sich am Wochenende länger Zeit für die Bewerbung.",feedback:"Am Wochenende könnte mehr Zeit sein. Damit verschiebt er aber die Aufgabe zugunsten einer nicht belegten Anzahl. Heute gibt es bereits eine kleine Gelegenheit. Nutze sie für einen Versuch, bevor du weitere Wiederholungen hinzufügst."},{key:"reserve",text:"Er reserviert fünf Minuten für einen Bewerbungsteil, kürzt oder streicht die Wiederholungen und prüft morgen den gespeicherten Abschnitt.",feedback:"Das verändert den Umstand, der ihn bisher aufgehalten hat. Er darf weiter gern schreiben, und der Versuch an der Bewerbung wird machbar. Ein gespeicherter Abschnitt ist weiterhin Vorbereitung fürs Abschicken, keine Zusage für eine Stelle."}],best:"reserve",takeaway:"Halte Zeit fürs Handeln frei. „Alle Zeilen geschafft“ heißt noch nicht „Aufgabe erledigt“.",review:"Welche Aufgabe hast du versucht, und wie viel Zeit hat dir das Schreiben dafür gelassen?",deeper:[{heading:"So läuft das bekannte Ritual über fünf Tage",paragraphs:["1. Wähle ein gewünschtes Ergebnis. 2. Schreib einen positiven Satz, als wäre es bereits eingetreten. 3. Schreibe diesen Satz in einer täglichen Sitzung 55-mal ab. 4. Wiederhole die Sitzung fünf Tage lang. 5. Lenke beim Schreiben deine Aufmerksamkeit wieder auf das gewünschte Ergebnis. Die genaue Anzahl stammt aus einer Praxisanleitung. Kontrollierte Forschung hat sie nicht als wirksame Dosis bestätigt. Manche Varianten verlangen zusätzlich bestimmte Gefühle oder ununterbrochene Konzentration. [manifest-P06]","Du kannst bei diesem vertrauten Schreibformat bleiben, wenn es dir gefällt. Schau aber, welche Zeit es beansprucht. Überlege vor dem Anfang, wie viel Zeit die eigentliche Handlung für dein Ziel heute braucht. In der ODA-Variante darfst du kürzer schreiben oder alle Wiederholungen auslassen. Ein ausgelassener Tag bedeutet nicht, dass ein künftiges Ergebnis abgesagt wurde. Eine fertige Seite hältst du als Schreiben fest, einen gespeicherten Bewerbungsteil als Arbeit an der Aufgabe. Keiner dieser Einträge bedeutet, dass ein Arbeitgeber dir eine Stelle angeboten hat."]},{heading:"Beim Planen kommt es nicht auf Wiederholungen an",paragraphs:["Die Meta-Analyse von Gollwitzer und Sheeran stützt Pläne, die eine konkrete Situation mit einer Handlung fürs Ziel verbinden. Untersucht wurden unterschiedliche Aufgaben, keine 55 Wiederholungen und keine fünftägige Manifestationsregel. Kappes und Oettingen fanden nach einigen idealisierten positiven Fantasien eine geringere unmittelbare Energie. Ihre kurzen Experimente mahnen zur Vorsicht, wenn angenehme Vorstellungen eines fertigen Ergebnisses die Vorbereitung ersetzen. Sie beweisen nicht, dass jeder optimistische Gedanke oder jeder wiederholte Satz schadet. [manifest-T02, manifest-T05]","Bei ODA nutzt du die Seite für einen praktischen Plan. Benenne dein Ziel, den kleinsten sinnvollen Teil der Aufgabe und die Gelegenheit, ihn zu erledigen. Füllt das Schreiben meist die ganze Pause, plane die Handlung zuerst ein. Fehlt eine Angabe für einen Bewerbungsteil, schick genau diese Frage ab. Versuche es heute und schau morgen zurück: Kam der geplante Anlass? Was hast du erledigt? Was fehlt noch? Schreiben und Handeln so zu verbinden ist eine Anpassung. Ein Ergebnis nach fünf Tagen wird damit nicht versprochen."]}],sources:["manifest-P06","manifest-T02","manifest-T05"]},{number:12,technique:"Zwei-Becher-Methode",title:"Zwei Becher: Was fehlt dazwischen?",goal:"Nutze die Beschriftungen für eine machbare Handlung samt Plan fürs Hindernis.",hook:"Wasser umgießen geht schnell. Was bringt dich von deiner jetzigen Situation zum Wunsch auf dem zweiten Becher?",reason:"Was macht dein Ziel mit deiner Zeit und deinen Mitteln erreichbar?",paragraphs:["Bei der Zwei-Becher-Methode beschriftest du einen Becher mit deiner jetzigen Situation, einen mit der gewünschten. Fülle den ersten, stell dir die Veränderung vor, gieße um und trinke das Wasser. Nicht belegt ist, dass Wasser Absichten trägt oder einen Dimensionswechsel auslöst. Forschung zu Zielen untersucht konkrete Ziele, Strategien und Rückmeldungen. Sie liefert keine Quanten-Erklärung für das Umgießen.","Die ODA-Variante: Behalte die Becher als Symbole oder zeichne zwei Kreise. Schreib dazwischen ein konkretes Ziel, ein echtes Hindernis und einen Wenn-dann-Plan. WOOP steht für Wunsch, Ergebnis, Hindernis und Plan. Forschung stützt diese Verbindung im Durchschnitt. Versuche heute eine Handlung, die einen Teil davon überbrückt. Prüfe morgen deine Handlung getrennt vom Ergebnis, das von anderen abhängt."],example:{title:"Omar schreibt den nächsten Schritt auf",text:"Omar beschriftet zwei Becher mit „Portfolio unfertig“ und „Bereit zum Bewerben“. Dazwischen liegt sein Zettel: „Nach dem Mittagessen eine Projektbeschreibung speichern.“ Kann er das Projekt nicht erklären, beschreibt er seine wichtigste Entscheidung. Er gießt um und schreibt den Text. Ein weiteres Projekt fehlt noch. Sein Eintrag zeigt genau, was sich verändert hat."},instructions:["Beschrifte die jetzige Situation und dein gewünschtes Ziel. Bleib bei einer machbaren Veränderung.","Schreib dazwischen die heutige Handlung und einen Wenn-dann-Plan für ein Hindernis auf.","Versuche diese Handlung. Schau morgen zurück, was du an der eigentlichen Aufgabe erledigt hast."],action:["Eine kurze Projektbeschreibung schreiben","Eine Voraussetzung für Weiterbildung erfragen"],minimum:["Text zu einer Projektentscheidung speichern","Eine Frage zur Weiterbildung senden"],cue:["Wenn das Mittagessen vorbei ist","Wenn ich die Becher wegräume"],place:["In meinem Portfolio-Dokument","An meinem Küchentisch"],obstacle:"Für das gewünschte Ziel brauche ich mehr Mittel",fallback:["Nach Zugang oder kleinerem Weg fragen","Eine Projektentscheidung einfach beschreiben"],observation:["Was ich auf dem Weg tatsächlich erledigt habe","Was zwischen den beiden Beschriftungen noch fehlt"],stopRule:"Nimm Zeichnungen, wenn dir das lieber ist. Falls du den Trinkschritt wählst, trinke nur unbedenkliches Trinkwasser.",scenario:"Auf Omars Wunschbecher steht „Bereit zum Bewerben“. In seinem Portfolio ist ein Projekt fertig, aber noch ohne Beschreibung. Ein zweites Projekt ist noch nicht abgeschlossen.",question:"Welcher nächste Schritt passt in ein Zeitfenster von fünf Minuten?",options:[{key:"caption",text:"Er schreibt und speichert die Beschreibung zum fertigen Projekt. Dann hält er fest, was noch fehlt, damit das Portfolio bereit ist.",feedback:"Damit wählt er einen machbaren Teil und lässt die verbleibende Lücke sichtbar. Eine Beschreibung macht nicht das ganze Portfolio fertig. Sie liefert aber einen echten Fortschritt, den er beim nächsten Rückblick prüfen kann."},{key:"rename",text:"Er ändert die Wunschbeschriftung zu „Als Designer eingestellt“, damit er beim Ritual sein größeres Ziel vor Augen behält.",feedback:"Das größere Ziel kann ihm viel bedeuten. Eine andere Beschriftung erledigt aber nichts am unfertigen Portfolio. Behalte deinen Wunsch und wähle die kleine Aufgabe, die in die verfügbaren fünf Minuten passt."},{key:"schedule",text:"Er plant erst alle übrigen Portfolio-Aufgaben, bevor er an die Beschreibung geht. So steht der gesamte Weg fest.",feedback:"Eine Aufgabenübersicht kann bei einem späteren Rückblick helfen. In diesem kurzen Zeitfenster weiß er schon, dass die Beschreibung fehlt. Sie fertigzustellen erprobt einen machbaren Schritt, statt die ganze Gelegenheit für weitere Vorbereitung zu verbrauchen."}],best:"caption",takeaway:"Die Beschriftungen zeigen die Lücke. Ein Schritt mit vorhandenen Mitteln überbrückt einen Teil davon.",review:"Was hat deine Handlung verändert, und was fehlt zwischen den beiden Beschriftungen noch?",deeper:[{heading:"So funktioniert das bekannte Ritual mit zwei Bechern",paragraphs:["1. Nimm zwei Becher und beschrifte den ersten mit deiner jetzigen Situation. 2. Schreib auf den zweiten die Situation, die du dir wünschst. 3. Fülle Wasser in den ersten Becher. 4. Stell dir beim Umgießen in den zweiten die gewünschte Veränderung vor. 5. Trink das Wasser und richte deine Aufmerksamkeit wieder auf die gewünschte Situation. Manche Praxisbeschreibungen nennen das einen Dimensionssprung. Diese metaphysische Erklärung ist durch die geprüften Belege nicht bestätigt. [manifest-P07]","Du kannst das symbolische Umgießen beibehalten, ohne die Erklärung als Tatsache zu übernehmen. Vorhandene Becher oder zwei gezeichnete Kreise reichen für die ODA-Übung. Schreib vor dem Umgießen eine Handlung zwischen die Beschriftungen. Stell eine ungewisse Entscheidung eines anderen Menschen nicht als bereits sicher dar. Eine brauchbare Projektbeschreibung für dein Portfolio ist deine Handlung. Eine Einstellung ist ein Ergebnis, an dem ein Arbeitgeber beteiligt ist. Falls du trinkst, verwende ausschließlich unbedenkliches Trinkwasser. Du brauchst weder ein besonderes Gefäß noch etwas zu kaufen."]},{heading:"Mit WOOP prüfen, was zwischen Wunsch und Wirklichkeit liegt",paragraphs:["WOOP ordnet einen Wunsch, sein gewünschtes Ergebnis, ein aktuelles Hindernis und einen Plan. Die Meta-Analyse zu mentalem Kontrastieren mit Wenn-dann-Plänen fand im Durchschnitt einen mäßigen Nutzen fürs Erreichen von Zielen. Die Ergebnisse streuten, und es gab Hinweise auf Publikationsverzerrung. Becher oder Wasser wurden nicht untersucht. Auch die Zielsetzungstheorie berücksichtigt Verbindlichkeit, Rückmeldung, Fähigkeiten und die Komplexität einer Aufgabe. Eine bedeutsame Beschriftung braucht einen gangbaren Weg. Ein schwieriges Ziel allein reicht ohne Zugang oder Strategie nicht aus. [manifest-T01, manifest-T11]","ODA macht den nächsten Schritt sichtbar. Wähle für dein bestehendes Ziel eine konkrete Aufgabe. Benenne ein Hindernis, auf das du reagieren kannst. Prüfe auch äußere Hürden wie fehlende Ausrüstung oder fehlendes Geld. „Wenn ich das Werkzeug nicht nutzen kann, frage ich nach einer verfügbaren Alternative“ macht die Bitte um Unterstützung zur Handlung. Halte dein Minimum und den Anlass fest. Versuche es heute und schau morgen zurück. Erfasse eine gesendete Bitte getrennt von erhaltener Hilfe. Die symbolischen Becher zusammen mit diesem praktischen Ablauf sind eine Anpassung, keine gemeinsam geprüfte Behandlung."]}],sources:["manifest-P07","manifest-T01","manifest-T11"]},{number:13,technique:"Kissenmethode",title:"Kissenmethode: Lass den Zettel morgen etwas anstoßen",goal:"Behalte den Zettel fürs Bett und plane damit eine Handlung tagsüber.",hook:"Dein Wunsch darf unter dem Kissen bleiben. Gib dem Zettel eine konkrete Erinnerung für morgen.",reason:"Würde dir mehr Schlaf bleiben, wenn du tagsüber planst?",paragraphs:["Bei der Kissenmethode legst du einen aufgeschriebenen Wunsch unter dein Kissen. Eine verbreitete Anleitung: Schreib ihn auf, als wäre er schon erfüllt, falte das Papier und leg es darunter. Wiederhole vor dem Schlafen den Satz oder stell dir das Ergebnis vor. Dass dieses Papier ein äußeres Ergebnis herbeiführt, wird durch die geprüften Belege nicht gestützt. [manifest-P08, manifest-T19]","Die ODA-Variante: Behalte den Zettel. Ergänze ein konkretes Ziel, ein wahrscheinliches Hindernis und einen Wenn-dann-Plan für eine Handlung. Pläne mit einem bestimmten Anlass und einer Handlung werden durch Forschung gestützt, eine besondere Anziehungskraft zur Schlafenszeit nicht. Tu heute etwas Sinnvolles und schau morgen zurück. Hält dich weiteres Planen wach, verschiebe es auf den Tag. [manifest-T02, manifest-T19]"],example:{title:"Majas Nachricht am Morgen",text:"Am Küchentisch schreibt Maja ihren Jobwunsch auf und schickt eine passende Bewerbung ab. Auf ihrem Kissenzettel steht zusätzlich: Wenn das Frühstücksgeschirr abgeräumt ist, prüfe eine neue passende Stelle. Am nächsten Morgen tut sie das und beginnt eine weitere Bewerbung. Angaben fehlen noch. Sie notiert die eingereichte Bewerbung getrennt vom unfertigen Entwurf. Kein Arbeitgeber hat geantwortet."},instructions:["Behalte den Zettel. Ergänze Ziel und Hindernis, bevor du dich zum Schlafen hinlegst.","Schreib einen Wenn-dann-Plan mit einem Anlass auf und tu heute etwas Sinnvolles.","Schau morgen auf deine versuchte Handlung zurück, getrennt vom Ritual unter dem Kissen."],action:["Eine passende Bewerbung abschicken","Einen Kontakt nach einer Stelle fragen"],minimum:["Eine passende Bewerbung einreichen","Eine konkrete Frage senden"],cue:["Wenn das Frühstücksgeschirr abgeräumt ist","Nach der heutigen Mittagspause"],place:["An meinem Küchentisch","An meinem üblichen Arbeitsplatz"],obstacle:"Das Planen vor dem Schlafen hält mich wach",fallback:["In der morgigen Mittagspause planen","Stattdessen einen Zettel für tagsüber nutzen"],observation:["Bewerbung abgeschickt; Antwort noch offen","Frage gesendet; Antwort getrennt festgehalten"],stopRule:"Hör auf, wenn das Ritual deinen Schlaf verzögert. Plane tagsüber weiter. Wiederholungen vor dem Schlafen sind nicht nötig.",scenario:"Auf Majas Zettel steht eine Frage zu einer passenden Stelle für morgen früh. Das Umschreiben hält sie abends wach, obwohl der Anlass für morgen schon feststeht.",question:"Was sollte sie heute Abend tun?",options:[{key:"a",text:"Den Zettel noch einmal neu schreiben und morgen entscheiden, ob sich die Frage zur Stelle weiterhin richtig anfühlt.",feedback:"Erneutes Umschreiben kostet Schlaf und ergänzt keine nötige Angabe. Ihr Anlass steht schon fest. Behalte die geplante Frage bei und verschiebe weitere Änderungen auf den Tag."},{key:"b",text:"Den Zettel liegen lassen, sich Schlaf gönnen und morgen beim geplanten Anlass nach der Stelle fragen.",feedback:"Damit schützt sie ihren Schlaf und hält an der sinnvollen Handlung fest. Morgen kann sie festhalten, ob sie die Frage gesendet hat. Eine Antwort des Arbeitgebers erfasst sie getrennt von ihrer Handlung."},{key:"c",text:"Die Nachfrage am Morgen durch längeres Visualisieren am Tag ersetzen und sich dabei die Antwort des Arbeitgebers vorstellen.",feedback:"Für längeres Planen eignet sich der Tag besser. Hier ersetzt sie damit aber eine verfügbare sinnvolle Handlung. Sich eine Antwort vorzustellen sendet keine Nachricht und legt nicht fest, wie der Arbeitgeber entscheiden wird."}],best:"b",takeaway:"Halte den Kissenzettel kurz und wähle einen passenden Moment tagsüber für die Handlung.",review:"Welche Handlung hast du danach versucht? Hat das Planen vor dem Schlafen deinen Schlaf gestört?",deeper:[{heading:"Die bekannte Anleitung für den Zettel unter dem Kissen",paragraphs:["1. Wähle ein gewünschtes Ergebnis und schreib einen Satz in der Gegenwart. Zum Beispiel eine vorgestellte Zusage, die du schon erhalten hast. Das folgt einer Praxisanleitung. Der Satz hält einen Wunsch fest, keine bestätigte Nachricht. Du kannst seinen Wortlaut für dich behalten. [manifest-P08]","2. Falte das Papier und leg es unter dein Kissen. Die Anleitung enthält weitere Einzelheiten zum Schreiben und Falten. Sie beschreiben aber die Variante dieser Autorin. Es sind keine belegten Voraussetzungen für ein äußeres Ergebnis. Ein gewöhnlicher Zettel, den du schon hast, reicht aus. [manifest-P08]","3. Lies oder wiederhole den Satz im Kopf, während du dich ins Bett legst. Stell dir das erfüllte Ergebnis vor, wenn dir dieser Teil gefällt. Danach darfst du einschlafen. Lebhafte Bilder, Wiederholungen oder ein bestimmtes Gefühl dürfen keine Voraussetzung dafür sein, dass du aufhören darfst. [manifest-P08]","4. Schau den Zettel an einem anderen Abend wieder an, wenn du möchtest. Die Anleitung beschreibt ein bekanntes Ritual, keine kontrollierten Wirksamkeitsbelege. Ein Überblick zu den Schaltkreisen für Wachheit zeigt nicht, dass Wünsche vor dem Schlafen kritisches Denken umgehen oder äußere Ereignisse auslösen. [manifest-P08, manifest-T19]"]},{heading:"Ein Zettel, der dich im Wachzustand weiterbringt",paragraphs:["Ergänze eine kleine praktische Anweisung, bevor du ins Bett gehst. Schreib dein konkretes Ziel, das erwartete Hindernis und die Handlung auf, die du selbst ausführen kannst. Bei der Jobsuche etwa: „Wenn das Frühstück abgeräumt ist, reiche ich eine passende Bewerbung ein. Wenn das Formular unklar ist, stelle ich der Personalabteilung eine konkrete Frage.“ Halte ungewisse Ergebnisse wie eine Zusage getrennt von deiner Handlung. [manifest-T02]","Die Meta-Analyse von Gollwitzer und Sheeran fand bei konkreten Wenn-dann-Plänen im Durchschnitt einen Nutzen fürs Erreichen von Zielen in unterschiedlichen Situationen. Sie untersuchte kein Papier unter Kissen und zeigte nicht, dass Planung jede Anstrengung erspart. Der Überblick zur Wachheit beschreibt das Zusammenspiel von Schaltkreisen. Er beschreibt keinen Weg über das Unterbewusstsein, der Wünsche erfüllt. Das sind unterschiedliche Aussagen. [manifest-T02, manifest-T19]","Bei ODA versuchst du es heute und schaust morgen zurück. Das ist ein praktischer Ablauf, kein geprüftes Paket für die Schlafenszeit. Halte fest, was du gesendet, gefragt oder erledigt hast. Erfasse Antworten getrennt davon. Hält dich das Bearbeiten des Zettels wach, lass ihn liegen und wähle eine Gelegenheit am Tag. Du musst das Ritual nicht beenden, um etwas Sinnvolles zu tun. [manifest-T02, manifest-P08]"]}],sources:["manifest-P08","manifest-T02","manifest-T19"]},{number:14,technique:"Flüstermethode",title:"Flüstermethode: Übe deine eigene Bitte",goal:"Mach aus der Vorstellung eine respektvolle Bitte, die du selbst stellen kannst.",hook:"Wartest du auf eine Nachricht? Beim Flüsterritual kannst du deinen eigenen nächsten Schritt wählen.",reason:"Gibt es eine passende Bitte, die ich stellen kann?",paragraphs:["Die Flüstermethode ist eine vorgestellte Bitte an einen anderen Menschen. Eine verbreitete Anleitung: Entspann dich, stell dir vor, wie du zu ihm gehst, flüstere dreimal deinen Wunsch und verlasse dann die Szene. Die geprüften Belege stützen nicht, dass du jemanden aus der Ferne zum Antworten bringen kannst. Seine Zustimmung und seine Grenzen zählen weiterhin. [manifest-P09]","Die ODA-Variante: Behalte das private Flüstern, wähle ein konkretes Ziel und benenne das Hindernis. Übe eine respektvolle Bitte, bei der auch ein Nein möglich ist. Schreib einen Wenn-dann-Plan für eine angemessene Handlung heute. Schau morgen auf deine Handlung zurück. Forschung stützt solche Wenn-dann-Pläne. Sich seiner Antwort sicher zu sein belegt nicht, dass er zustimmen wird. [manifest-T02, manifest-T13]"],example:{title:"Fragen, ohne Druck zu machen",text:"In der Mittagspause stellt sich Ben eine geflüsterte Bitte ums Projekttreffen vor. Daraus macht er eine Nachricht: „Hast du am Donnerstag zehn Minuten für ein Gespräch?“ Die Kollegin antwortet: Donnerstag ist voll. Ben hält die Nachricht und das Nein fest. Dann fragt er, ob nächste Woche passt. Sein Ritual verpflichtet sie nicht zur Zustimmung."},instructions:["Flüstere die respektvolle Bitte für dich. Lass der Person die Möglichkeit, Nein zu sagen.","Benenne Ziel, Hindernis und Wenn-dann-Plan. Stelle heute eine angemessene Bitte.","Schau morgen zurück: Was hast du gefragt und wie hast du die Antwort respektiert?"],action:["Um ein kurzes Projekttreffen bitten","Einmal passend nach Verfügbarkeit fragen"],minimum:["Eine klare Bitte um ein Treffen senden","Eine Frage zum Thema stellen"],cue:["Nach der heutigen Mittagspause","Wenn unser vereinbarter Austausch beginnt"],place:["An meinem Arbeitsplatz","An unserem üblichen Treffpunkt"],obstacle:"Ich feile immer wieder an einer einfachen Bitte",fallback:["Die Bitte in einem einfachen Satz stellen","Beim vereinbarten Austausch fragen"],observation:["Bitte gestellt; Antwort getrennt festgehalten","Grenze respektiert; nächsten Schritt gewählt"],stopRule:"Kontaktiere niemanden, der Kontakt abgelehnt hat. Deine private Vorstellung kann die Grenzen eines anderen Menschen nicht außer Kraft setzen.",scenario:"Ben möchte ein Treffen. Seine Kollegin hat gesagt, dass diese Woche voll ist. Sie hat ihn aber eingeladen, nach nächster Woche zu fragen. Seine Flüsterübung gibt ihm ein gutes Gefühl.",question:"Welcher nächste Schritt passt zu dem, was er weiß?",options:[{key:"a",text:"Einmal nach ihrer Verfügbarkeit nächste Woche fragen und die Antwort annehmen, ohne wiederholt Nachrichten zu schicken.",feedback:"Sie hat ihm diese Möglichkeit angeboten. Eine klare Frage respektiert sie. Er kann seine Bitte und ihre Antwort getrennt festhalten. Sein gutes Gefühl gibt ihm keinen Anspruch auf ihre Zeit."},{key:"b",text:"Warten, bis sie einen Termin vorschlägt, weil sich das vorgestellte Gespräch inzwischen abgeschlossen anfühlt.",feedback:"Er darf sich fürs Warten entscheiden. Im vorgestellten Gespräch hat er aber nicht wirklich nach nächster Woche gefragt. Ihre Einladung gibt ihm eine passende Gelegenheit für eine echte Bitte, falls ihm das Treffen weiterhin wichtig ist."},{key:"c",text:"Herzlicher erklären, wie viel ihm ein Treffen noch in dieser Woche bedeuten würde.",feedback:"Auch eine herzlichere Nachricht bittet sie, die bereits ausgeschlossene Woche noch einmal zu überdenken. Nutze die Möglichkeit, die sie angeboten hat. Stärkere Gefühle sind kein Grund, sie weiter zu drängen."}],best:"a",takeaway:"Übe deine Bitte. Über die Antwort entscheidet dein Gegenüber.",review:"Welche Bitte hast du tatsächlich gestellt, und wie bist du mit der Antwort oder Grenze umgegangen?",deeper:[{heading:"Das beliebte Gespräch in deiner Vorstellung",paragraphs:["1. Wähle die Person und die gewünschte Antwort. In der Praxisbeschreibung findet die Übung in deiner Vorstellung statt. Eine Antwort zu wählen beschreibt, was du dir wünschst. Es zeigt nicht, was dieser Mensch möchte, und bedeutet keine Erlaubnis, ihn zu kontaktieren. [manifest-P09]","2. Entspann dich und stell dir die Person an einem Ort vor. Stell dir vor, wie du auf sie zugehst und ihr die Bitte dreimal ins Ohr flüsterst. Die Anzahl gehört zu dieser Anleitung. Sie ist keine wissenschaftlich bestätigte Dosis, um jemanden zu beeinflussen. Du kannst die Übung mit offenen Augen oder als Beschreibung in Worten anpassen. [manifest-P09]","3. Verlasse die vorgestellte Szene. Manche Varianten ergänzen einen vorgestellten Kuss auf die Stirn. Das ist eine weitere Einzelheit der Szene, kein Beleg für Einfluss aus der Ferne. Bei ODA bleibt die Übung privat. Wähle eine Bitte, die du respektvoll stellen könntest. Vorgestellte Nähe ist keine Zustimmung des anderen Menschen. [manifest-P09]","4. Entscheide, ob eine tatsächliche Bitte angemessen ist. Die Praxisgeschichte beschreibt das Ritual. Sie kann aber weder Telepathie noch Kontrolle belegen. Ein Mensch darf ablehnen, schweigen oder seine Meinung ändern. Wiederholtes Flüstern verpflichtet ihn nicht, dir eine Antwort zu geben. [manifest-P09]"]},{heading:"Plane deinen eigenen Teil des Gesprächs",paragraphs:["Halte das Ziel konkret: Nach einem möglichen Termin zu fragen ist etwas anderes, als jemanden dazu bringen zu wollen, dich zu bewundern. Benenne ein Hindernis, auf das du reagieren kannst. Vielleicht verschiebst du eine kurze Nachricht, weil du sie immer wieder überarbeitest. Wähle dann einen Anlass: „Wenn meine Mittagspause vorbei ist, sende ich eine klare Frage zu einem Termin.“ Ist Kontakt unerwünscht, kann deine Handlung darin bestehen, diese Grenze zu respektieren. [manifest-T02, manifest-P09]","Die Forschung zu Wenn-dann-Plänen stützt das Verknüpfen einer erkennbaren Situation mit einer gewählten Handlung. Sie belegt keine Kontrolle über den Empfänger. In drei Online-Befragungsgruppen fanden Dixon und Kollegen einen Zusammenhang zwischen Manifestationsglauben, Selbstvertrauen und einigen berichteten finanziellen Risiken. Diese Zusammenhänge zeigen keine Ursache und Wirkung. Die Studie prüfte auch kein Flüstern. Sich sicher zu fühlen misst nicht, ob ein anderer Mensch zustimmt. [manifest-T02, manifest-T13]","ODAs private Probe und der Rückblick am nächsten Tag sind Anpassungen. Stelle heute eine angemessene Bitte oder halte eine vereinbarte Gelegenheit fest. Schreib morgen auf, was du tatsächlich gefragt hast, welche Antwort kam und ob du sie respektiert hast. Schweigen lässt die Antwort offen. Wähle einen anderen angemessenen Schritt oder hör auf. Zähle das vorgestellte Gespräch nicht als das tatsächlich geführte Gespräch. [manifest-T02, manifest-P09]"]}],sources:["manifest-P09","manifest-T02","manifest-T13"]},{number:15,technique:"Dankbarkeitstagebuch",title:"Dankbarkeit: Du darfst die Absage blöd finden",goal:"Notiere, was du wirklich schätzt. Handle sinnvoll, ohne eine Schwierigkeit zu verdrängen.",hook:"Trotz Hilfe kommt eine Absage? Du darfst die Hilfe schätzen und enttäuscht sein.",reason:"Was schätzt du, ohne Probleme zu verstecken?",paragraphs:["Im Dankbarkeitstagebuch notierst du, was du schätzt, ergänzt oft Gründe und liest den Eintrag wieder. Manche Manifestationsvarianten danken dem Leben für ein künftiges Ereignis, als wäre es passiert. Gemischte Befunde: Dankbarkeitsübungen zeigen gegenüber manchen Vergleichsgruppen kleine durchschnittliche Vorteile fürs Wohlbefinden. Gegenüber psychologisch aktiven Alternativen haben sie kaum Vorteile. Veränderungen bei Symptomen sind mäßig. Dankbarkeit reicht als Behandlung nicht aus und belegt keine Anziehung künftiger Ereignisse.","Die ODA-Variante: Behalte das Tagebuch und beschreibe etwas Wirkliches. Benenne neben deiner Wertschätzung dein konkretes Ziel und eine Schwierigkeit. Ergänze einen Wenn-dann-Plan und eine Handlung für heute. Danke etwa einer hilfreichen Person oder bitte um gezielte Rückmeldung. Schau morgen auf deine Handlung und mögliche Antworten zurück. Deine Enttäuschung darf im dankbaren Eintrag stehen bleiben."],example:{title:"Aylin hält beides fest",text:"Aylin schätzt, dass eine Freundin ihre Bewerbung geprüft hat, und notiert das. Sie notiert auch die Absage-Mail. Nach dem Frühstück fragt sie, welcher Einstiegssatz noch Arbeit braucht. Klappt kein Anruf, sieht ihr Plan eine kurze Nachricht vor. Die Freundin kann heute nicht antworten. Aylin notiert Frage und Enttäuschung, ohne Rückmeldung zu erfinden."},instructions:["Schreib auf, was du wirklich schätzt und warum. Lass eine Schwierigkeit dabei sichtbar.","Benenne die sinnvolle Handlung für heute und einen Wenn-dann-Plan für ein wahrscheinliches Hindernis.","Versuche die Handlung. Schau morgen darauf und auf eine mögliche Antwort zurück."],action:["Gezielt um Rückmeldung bitten","Für eine konkrete Hilfe danken"],minimum:["Eine Frage zur Bewerbung senden","Eine Nachricht mit konkretem Dank senden"],cue:["Wenn das Frühstück vorbei ist","Wenn mein Dankbarkeitseintrag fertig ist"],place:["In unserem Nachrichtenverlauf","An meinem Küchentisch"],obstacle:"Wer mir hilft, hat keine Zeit für einen Anruf",fallback:["Eine kurze Frage zur Rückmeldung senden","Eine andere verfügbare Person fragen"],observation:["Anfrage gesendet; tatsächliche Antwort festgehalten","Wertschätzung und Schwierigkeit ehrlich aufgeschrieben"],stopRule:"Erzwinge keine Dankbarkeit. Bei anhaltender Belastung brauchst du Unterstützung, die über ein Tagebuch hinausgeht.",scenario:"Aylin schätzt die Unterstützung ihrer Freundin und ist trotzdem traurig über eine Bewerbungsabsage. Die Freundin hat angeboten, eine konkrete Frage per Nachricht zu beantworten.",question:"Welcher Eintrag und welche Handlung passen zu dieser Situation?",options:[{key:"positive",text:"Sie notiert heute nur die hilfreichen Momente. Mit der Absage beschäftigt sie sich erst, wenn sie mehr Dankbarkeit fühlt.",feedback:"Wertschätzung darf im Eintrag bleiben. Sie verlangt aber nicht, ein konkretes Problem aufzuschieben. Die angebotene Rückmeldung ermöglicht Aylin eine nützliche Frage. Gleichzeitig darf sie anerkennen, dass die Absage weh tut."},{key:"both",text:"Sie hält Unterstützung und Enttäuschung fest. Dann fragt sie, welcher Einstiegssatz die nächste Bewerbung klarer machen würde.",feedback:"So bezieht sich ihre Dankbarkeit auf ein tatsächliches Ereignis, und sie nutzt verfügbare Unterstützung. Die Nachricht ist eine Anfrage, keine erhaltene Rückmeldung. Morgen kann Aylin eine mögliche Antwort notieren und entscheiden, was sie überarbeitet."},{key:"future",text:"Sie schreibt einen Dank für die nächste Zusage, als sei sie schon da. Bevor sie um Rückmeldung bittet, liest sie den Eintrag erneut.",feedback:"Diese auf die Zukunft gerichtete Variante ist ein Praxisritual, nicht die Dankbarkeitsübung aus den zitierten Übersichtsarbeiten. Sie kann keine Zusage bestätigen. Etwas tatsächlich zu schätzen und eine gezielte Frage zu stellen hält den Eintrag bei den Fakten."}],best:"both",takeaway:"Schätze, was tatsächlich da ist. Lass die Schwierigkeit und die nächste sinnvolle Handlung sichtbar.",review:"Was hast du geschätzt, welche Handlung hast du versucht, und hat jemand darauf geantwortet?",deeper:[{heading:"So sieht ein vertrautes Dankbarkeitstagebuch aus",paragraphs:["1. Öffne ein Notizbuch oder das Werkzeug, mit dem du sonst schreibst. 2. Benenne etwas, das du schätzt. 3. Beschreibe, warum es dir etwas bedeutet. 4. Ergänze einen weiteren Punkt, wenn du möchtest. 5. Lies den Eintrag zu einem gewählten Zeitpunkt wieder. Ein Erfahrungsbericht beschreibt dieses Format mit Gründen und erneutem Lesen. Manifestationsvarianten danken manchmal zusätzlich für ein erhofftes künftiges Ereignis. Das ist eine andere Aussage, als bereits erhaltene Hilfe zu schätzen. [manifest-P10]","Bei ODA reicht ein gewöhnliches Detail: eine brauchbare Antwort, ein gemeinsam genutztes Werkzeug oder ein Moment Ruhe. Du brauchst nicht für jedes Problem etwas Positives. Ist heute eine Absage, ein fehlender Zugang oder eine Enttäuschung wichtig, halte das neben deiner Wertschätzung fest. Wähle eine sinnvolle Handlung, die zu deinem bestehenden Ziel passt. Der Eintrag dient dem Nachdenken. Jemandem zu danken oder eine Anfrage zu senden ist eine eigene Handlung. Weder das Schreiben noch eine Anfrage garantieren, dass eine Antwort kommt."]},{heading:"Kleine durchschnittliche Vorteile mit Grenzen beim Vergleich",paragraphs:["Davis und Kollegen fanden bei Dankbarkeitsübungen gegenüber manchen Vergleichsgruppen kleine durchschnittliche Vorteile fürs Wohlbefinden. Gegenüber psychologisch aktiven Alternativen war Dankbarkeit fürs Wohlbefinden nicht überlegen. Die Befunde zu Angst waren nicht eindeutig. Cregg und Cheavens fanden mäßige durchschnittliche Veränderungen bei gemeinsam ausgewerteten Depressions- und Angstsymptomen. Gegenüber Wartelisten waren die Effekte größer als gegenüber aktiven Vergleichsgruppen. Ihre gesonderte Auswertung zur Angst blieb uneindeutig. Diese Ergebnisse zeigen weder eine optimale Tagebuchdosis noch garantierte Linderung. Sie belegen Dankbarkeit nicht als ausreichende Behandlung. Auch wurde nicht geprüft, ob künftige Ereignisse eintreten, weil jemand dem Universum gedankt hat. [manifest-T09, manifest-T10]","ODA ergänzt einen praktischen Plan, ohne ihn als die untersuchte Übung auszugeben. Halte dein Ziel konkret, benenne das aktuelle Hindernis und wähle einen Wenn-dann-Plan. Hat eine hilfreiche Person keine Zeit für einen Anruf, sende stattdessen eine gezielte Frage. Versuche es heute und schau morgen zurück. Halte die Anfrage getrennt von einer Antwort fest. Auch Enttäuschung darf in deinem Eintrag stehen bleiben. Fühlt sich Dankbarkeit erzwungen an, kannst du sie auslassen und trotzdem die sinnvolle Handlung tun oder Unterstützung suchen."]}],sources:["manifest-P10","manifest-T09","manifest-T10"]},{number:16,technique:"So tun, als ob / Verkörperung",title:"So tun, als ob: üben, ohne Geld vorzustrecken",goal:"Fülle deine gewünschte Rolle mit einem bezahlbaren Verhalten.",hook:"Du willst professionell auftreten. Fang mit einer Arbeitsprobe an, bevor du die neue Garderobe kaufst.",reason:"Welches Verhalten passt zu deinem Ziel, ohne Geld auszugeben, das du anderswo brauchst?",paragraphs:["Beim „So tun, als ob“, auch Verkörperung genannt, verhältst du dich wie jemand, der dein gewünschtes Ergebnis schon erreicht hat. Wähle diese Rolle, stell dir ihren Alltag vor und übernimm ein Verhalten oder Symbol. Gemischte Befunde: Konkrete Ziele und Rückmeldungen können Leistung fördern. Dass gespielter Erfolg Ergebnisse anzieht, ist nicht belegt. Befragungen fanden Zusammenhänge zwischen Manifestationsglauben und einigen finanziellen Risiken, ohne eine Ursache zu belegen.","Die Rollenprobe bleibt. Wähle ein Verhalten, das du selbst steuern und dir leisten kannst. Benenne Ziel, Hindernis und Wenn-dann-Plan. Professionell handeln kann heißen: eine brauchbare Arbeitsprobe vorbereiten oder klar nachfragen. Tu heute eine Sache und prüfe morgen deinen Versuch. Statussymbole musst du nicht kaufen. Ob jemand zustimmt, entscheidet diese Person."],example:{title:"Fabian probiert die Rolle aus",text:"Fabian will als freier Datenanalyst arbeiten. Statt eines teuren Bürostuhls verbessert er eine Tabelle als Arbeitsprobe. Nach dem Mittagessen prüft er eine Berechnung und erklärt sie. Falls der Softwarezugang fehlt, nutzt er ein verfügbares kostenloses Programm. Die Arbeitsprobe ist verständlicher; einen Kunden hat er noch nicht."},instructions:["Benenne die gewünschte Rolle und ein konkretes Verhalten, das dazu passt und bezahlbar bleibt.","Plane mit Wenn-dann, was du bei einem Hindernis tust. Versprich keine Entscheidung anderer Menschen.","Probiere dieses Verhalten heute aus. Prüfe morgen, was du getan und ausgegeben hast."],action:["Eine Arbeitsprobe verbessern","Eine konkrete Kundenfrage stellen"],minimum:["Eine erklärte Beispielberechnung speichern","Eine Frage zum Projekt verschicken"],cue:["Nach dem Mittagessen","Wenn ich die Beispieldatei öffne"],place:["An meinem Schreibtisch","In meiner Beispieltabelle"],obstacle:"Ich habe keinen Zugang zum vorgesehenen Programm",fallback:["Ein verfügbares kostenloses Programm nutzen","Die Erklärung in eine Textdatei schreiben"],observation:["Erstellte Arbeit und tatsächliche Ausgaben","Gespeicherte Änderung in der Arbeitsprobe"],stopRule:"Gib nur aus, was du dir leisten kannst. Behandle unsichere Einnahmen oder die Zustimmung anderer nicht als zugesagt.",scenario:"Fabian sucht freie Aufträge, hat aber noch keinen bestätigten Kunden. Ein teures Programm würde Geld verbrauchen, das er für das Nötigste braucht. Ein verfügbares kostenloses Programm reicht für seine Arbeitsprobe.",question:"Mit welcher Handlung füllt er die Rolle heute sinnvoll aus?",options:[{key:"sample",text:"Mit dem verfügbaren Programm eine Arbeitsprobe verbessern, die Änderung festhalten und das Geld für notwendige Ausgaben schützen.",feedback:"So wird aus der gewünschten Rolle ein bezahlbares Verhalten mit einem überprüfbaren Ergebnis. Ein Kunde ist damit noch nicht sicher. Fabian verbessert aber etwas, das er zeigen kann. Geld für das Nötigste muss kein unsicheres Statussymbol finanzieren."},{key:"purchase",text:"Das teure Programm jetzt kaufen, damit seine Arbeitsumgebung zu der professionellen Rolle passt, in die er hineinwachsen möchte.",feedback:"Ein Programm kann sinnvoll sein, wenn die Aufgabe es braucht und der Preis passt. Hier erledigt ein kostenloses Programm die Aufgabe. Der Kauf gefährdet notwendige Ausgaben. Die Probe für eine neue Rolle macht künftige Einnahmen nicht sicher."},{key:"wait",text:"Erst auf einen bestätigten Kunden warten und dann eine Arbeitsprobe erstellen, damit keine Mühe in ein unsicheres Ergebnis fließt.",feedback:"Sein Geld zu schützen ist sinnvoll. Eine kleine Arbeitsprobe lässt sich aber mit vorhandenen Mitteln erstellen. Wer erst Gewissheit abwartet, verhindert auch diesen bezahlbaren Versuch. Begrenze den Aufwand auf ein machbares Maß und prüfe, was der Arbeitsprobe noch fehlt."}],best:"sample",takeaway:"Übe, was zu deinen Mitteln passt. Halte Rolle, Ausgaben und äußere Ergebnisse auseinander.",review:"Welches Verhalten hast du ausprobiert, was hat es gekostet und welches Ergebnis kennst du tatsächlich?",deeper:[{heading:"Die bekannte Probe für eine neue Rolle",paragraphs:["1. Wähle die Situation oder Rolle, die du dir wünschst. 2. Stell dir vor, wie jemand in dieser Rolle einen gewöhnlichen Tag verbringt. 3. Wähle dazu passende Verhaltensweisen, Gegenstände oder Gewohnheiten. 4. Handle so, als wäre die gewünschte Veränderung bereits eingetreten. 5. Nimm wahr, wie sich diese Probe anfühlt, und wiederhole sie bei Bedarf. Ein Erfahrungsbericht beschreibt, wie eine Person Kleidung und Gepäck vorbereitet, als wäre eine Stelle bereits zugesagt. Das spätere Angebot ist eine Anekdote, kein kontrollierter Vergleich. [manifest-P11]","Bei ODA übst du ein Verhalten mit vertretbaren Kosten. Eine Arbeitsprobe vorbereiten, mit einer Tagesordnung zum Gespräch kommen oder eine klare Frage stellen kann zu deinem bestehenden Ziel passen. Teure Dinge sind keine Voraussetzung dafür, die Rolle zu üben. Handle nicht so, als hätte eine andere Person schon zugestimmt oder ein Arbeitgeber dich bereits eingestellt, wenn das nicht bestätigt ist. Eine mögliche Zukunft zeigt eine Richtung. Sie verschafft dir noch keine verfügbaren Mittel."]},{heading:"Ziele brauchen Rückmeldung und verfügbare Mittel",paragraphs:["Die Theorie zur Zielsetzung beschreibt, wie konkrete, anspruchsvolle Ziele die Leistung fördern können. Dabei zählen die Bindung an das Ziel, Rückmeldungen, Fähigkeiten und die Schwierigkeit der Aufgabe. Sie belegt nicht, dass das Annehmen einer Rolle allein das gewünschte Ergebnis hervorbringt. Dixon und Kollegen fanden Zusammenhänge zwischen Manifestationsglauben und einigen selbst berichteten finanziellen Risiken sowie berichteter Insolvenz. Daraus lässt sich keine Ursache ableiten. Selbstvertrauen oder das Gefühl, erfolgreich zu sein, ist etwas anderes als Geld, das schon eingegangen ist. [manifest-T11, manifest-T13]","ODA wählt zuerst eine Handlung und dann ein Symbol. Benenne das konkrete Ergebnis, auf das du heute hinarbeitest, und die verfügbare Zeit oder Ausstattung. Überlege, was du bei einem wahrscheinlichen Hindernis tust, etwa fehlendem Zugang zur Software. Dein Minimum muss bezahlbar bleiben. Probiere es heute aus und prüfe morgen den Verlauf. Halte getrennt fest, welche Arbeit entstanden ist, was sie gekostet hat und welche Antwort von außen kam. Setzt ein Kauf oder Versprechen voraus, dass der Erfolg schon da ist, überdenke den Weg. Diese Verbindung von Rolle und Handlung ist ODAs Anpassung. Die genannten Studien prüften sie nicht als Verkörperungsübung."]}],sources:["manifest-P11","manifest-T11","manifest-T13"]},{number:17,technique:"Brief von deinem zukünftigen Ich",title:"Zukunftsbrief: Schreib auch über den schwierigen Dienstag",goal:"Dein Zukunftsbrief nennt eine machbare Handlung für diese Woche.",hook:"Dein zukünftiges Ich lebt gelassener. Wie ist es mit einem schwierigen Dienstag klargekommen?",reason:"Welche Zukunft ist dir einen kleinen Schritt wert, den du dir diese Woche leisten kannst?",paragraphs:["Im Zukunftsbrief schreibt dein vorgestelltes späteres Ich an dein heutiges. Wähle einen Zeitpunkt, beschreibe Leben und Veränderungen, mach dir Mut und lies erneut. Gemischte Befunde: Verwandte Forschung zum „bestmöglichen Selbst“ stützt durchschnittliche Vorteile für Wohlbefinden und Optimismus. Sie belegt weder Nachrichten aus der Zukunft noch garantierte Zielerreichung. Dabei wird das Hinarbeiten auf dieses Leben ebenfalls vorgestellt.","Die Stimme des Briefes bleibt. Schreib auch über Mühe, Unterstützung und einen gewöhnlichen schwierigen Tag. Benenne dein konkretes Ziel, das aktuelle Hindernis und deinen Wenn-dann-Plan. Wähle eine Handlung für heute und speichere eine machbare Gelegenheit. Konkrete Planung wird durch Forschung gestützt. Brief samt Plan ist ODAs Anpassung. Prüfe morgen deinen Versuch, statt zu bewerten, ob die Vorhersage eingetroffen ist."],example:{title:"Janas gewöhnlicher Tag",text:"Janas Zukunftsbrief beschreibt eine ruhigere Arbeitswoche und das Nachfragen nach Prioritäten bei kollidierenden Aufgaben. Heute öffnet sie ihr Arbeitspostfach und schickt eine klärende Frage. Ist ihre Chefin nicht erreichbar, nutzt sie den vereinbarten Teamchat. Die Antwort kommt nicht sofort. Jana notiert die verschickte Frage und die noch ungeklärte Arbeitsbelastung."},instructions:["Schreib als dein zukünftiges Ich. Nenne auch die Mühe, nötige Hilfe und ein alltägliches Hindernis.","Wähle eine Handlung für heute und einen konkreten Anlass. Ergänze einen machbaren Wenn-dann-Plan.","Versuche dein Minimum und prüfe morgen, was tatsächlich passiert ist."],action:["Nach einer Arbeitspriorität fragen","Eine machbare Übungszeit reservieren"],minimum:["Eine klärende Frage verschicken","Eine verfügbare Übungszeit bestätigen"],cue:["Wenn ich mein Arbeitspostfach öffne","Nach dem Abräumen des Abendessens"],place:["Im vereinbarten Teamchat","An meinem Küchentisch"],obstacle:"Die benötigte Person ist nicht erreichbar",fallback:["Den vereinbarten Teamchat nutzen","Eine andere verfügbare Übungszeit wählen"],observation:["Verschickte Frage und tatsächliche Antwort","Die tatsächlich bestätigte Übungszeit"],stopRule:"Wähle eine nähere oder weniger anspruchsvolle Zukunft, wenn der Brief Druck erzeugt. Du darfst pausieren.",scenario:"Janas Zukunftsbrief verspricht eine ausgeglichene Arbeitswoche. Heute kollidieren zwei dringende Aufgaben. Ihre Chefin hat sie eingeladen, klärende Fragen im Teamchat zu stellen.",question:"Welche Ergänzung macht den Brief jetzt hilfreich?",options:[{key:"calendar",text:"Erst einen vollständigen Kalender für die ideale Woche beschreiben. Danach fragen, welche der beiden dringenden Aufgaben heute Vorrang hat.",feedback:"Ein Kalender kann spätere Entscheidungen erleichtern. Allein löst er den Konflikt zwischen diesen Prioritäten aber nicht. Jana hat bereits einen vereinbarten Weg, um nachzufragen. Nutze diese Gelegenheit und lass sichtbar, welche Frage noch auf eine Antwort wartet."},{key:"certainty",text:"Mehr Zuspruch zum Vertrauen in die Zukunft ergänzen und dann warten, bis sich die Arbeitsbelastung weniger überwältigend anfühlt.",feedback:"Zuspruch kann guttun. Auf ein anderes Gefühl zu warten lässt aber beide dringenden Aufgaben weiter miteinander konkurrieren. Eine kurze klärende Frage ist bereits machbar. Der Brief sollte Jana bei diesem Schritt helfen, ohne die Antwort vorwegzunehmen."},{key:"request",text:"Beschreiben, wie sie an schwierigen Tagen nach Prioritäten fragt. Dann eine klärende Frage über den vereinbarten Teamchat schicken.",feedback:"So enthält das Zukunftsbild ein Verhalten, das zum aktuellen Hindernis passt. Die Frage zu verschicken ist Janas Handlung. Die Antwort bleibt unbekannt, bis sie eintrifft. Morgen kann Jana ihren Versuch prüfen und den nächsten Schritt wählen."}],best:"request",takeaway:"Lass dein Zukunfts-Ich heutige Aufgaben nennen und die Hilfe, die du dafür brauchen könntest.",review:"Was aus deinem Brief hast du versucht? Welche Hilfe oder welches Ergebnis bleibt offen?",deeper:[{heading:"So ist der bekannte Zukunftsbrief aufgebaut",paragraphs:["1. Wähle einen späteren Zeitpunkt in deinem Leben. 2. Stell dir vor, du wärst dort bereits angekommen. 3. Richte einen Brief an dein heutiges Ich. 4. Beschreibe, was sich verändert hat und wie sich der Alltag anfühlt. 5. Mach dir Mut oder gib dir einen Rat. Lies den Brief anschließend erneut. Eine Anleitung aus der Praxis beschreibt diese Stimme aus der Zukunft und ihren verständnisvollen Ton. Datum und Anrede gehören zum Briefformat. Sie sind keine wissenschaftlich notwendigen Zutaten. [manifest-P12]","Schreib bei ODA über eine Zukunft, die du dir wünschst. Behaupte nicht, dass der Brief eine Nachricht oder Vorhersage ist. Nenne eine alltägliche Schwierigkeit, die nötige Mühe und die Unterstützung, die du vielleicht brauchst. Für eine ruhigere Arbeitswoche kann ein Gespräch über Prioritäten nötig sein, statt noch größerer Gewissheit. Verbinde deine Richtung mit dem Versuch aus deinem Kurs. Unterstreiche eine machbare Handlung für die Person, die morgen mit denselben tatsächlichen Mitteln aufwacht. Du darfst über die nahe Zukunft schreiben, wenn eine ferne Zukunft dich belastet."]},{heading:"Zuversicht braucht einen Weg zurück zu heute",paragraphs:["Die Metaanalyse zum „bestmöglichen Selbst“ fand gegenüber Kontrollgruppen durchschnittliche Vorteile für Wohlbefinden, Optimismus und positive Gefühle. Häufig nahmen junge Studierende teil. Keine Studie erfüllte sämtliche Qualitätskriterien. Die vorgestellte Zukunft setzt voraus, dass man auf sie hingearbeitet hat. Die Befunde zeigen nicht, dass Briefe Ereignisse außerhalb deiner Kontrolle vorhersagen oder herbeiführen. Die Forschung zu Wenn-dann-Plänen stützt unabhängig davon, einen konkreten Anlass mit einer machbaren Handlung zu verbinden. Keine der beiden Quellen prüfte genau diese Kombination mit einem Zukunftsbrief. [manifest-T08, manifest-T02]","ODA nutzt den Brief, um eine Handlung zu wählen. Benenne ein konkretes Ziel und das Hindernis, das die heutige Aufgabe am unmittelbarsten betrifft. Schreib: „Wenn das passiert, werde ich …“, gefolgt von einer machbaren Handlung. Speichere den Anlass, den Ort und dein Minimum. Probiere es heute oder bei der späteren gewählten Gelegenheit aus. Prüfe morgen, was tatsächlich passiert ist: eine Frage, eine erledigte Aufgabe, eine Verzögerung oder eine Pause. Hat jemand noch nicht geantwortet, bleibt die Antwort unbekannt. Passe den nächsten Schritt an, ohne die vorgestellte Zukunft schon als Beleg zu behandeln."]}],sources:["manifest-P12","manifest-T08","manifest-T02"]},{number:18,technique:"17-Sekunden-Fokus",title:"17-Sekunden-Fokus: Nimm den Timer als Startsignal",goal:"Nutze eine freiwillige kurze Pause zum Handeln, ohne wissenschaftlichen Anspruch an die Dauer.",hook:"Noch keine siebzehn Sekunden und schon abgeschweift? Du kannst trotzdem handeln.",reason:"Hilft mir der Timer beim Anfangen oder hält er mich auf?",paragraphs:["Bei der 17-Sekunden-Methode hältst du einen gewünschten Gedanken siebzehn Sekunden lang fest, ohne ihm zu widersprechen. Manche Varianten wiederholen vier Abschnitte, insgesamt achtundsechzig Sekunden. Die geprüften Quellen belegen weder diese besondere Dauer noch eine Schwelle, ab der Wünsche angezogen werden. Primingforschung untersucht die Wirkung vorheriger Reize. Sie bestätigt weder diese Zahlen noch bewusst durchgeführte Wunschrituale. [manifest-P13, manifest-T16]","Bei ODA bleiben siebzehn Sekunden eine freiwillige Pause. Benenne danach dein konkretes Ziel und Hindernis. Schreib einen Wenn-dann-Plan für eine Handlung heute und prüfe morgen deinen Versuch. Konkrete Planung wird durch Forschung gestützt. Wenn ein Gedanke abschweift, musst du vor dem Handeln nicht neu anfangen. Der Timer ist dein Startsignal, keine Voraussetzung für Ergebnisse. [manifest-T02, manifest-P13]"],example:{title:"Die unterbrochene Pause",text:"Vor dem Mittagessen denkt Aylin an ihr Portfolioziel. Ihr Timer steht auf siebzehn Sekunden. Eine Lieferung unterbricht ihren Gedanken. Sie startet den Timer nicht erneut, sondern folgt ihrem Plan: Nach dem Essen schickt sie einem passenden Kunden eine Arbeitsprobe. Der Kunde wünscht einen anderen Stil. Aylin notiert Nachricht und Rückmeldung, statt die Fokusübung neu zu starten."},instructions:["Wähle dein Ziel. Wenn du möchtest, mach eine Pause von siebzehn Sekunden.","Benenne ein Hindernis und deinen Wenn-dann-Plan. Tu heute eine Sache, die dir weiterhilft.","Prüfe morgen deinen Versuch. Schau auch auf Rückmeldungen, die du erhalten hast."],action:["Eine passende Arbeitsprobe verschicken","Um Rückmeldung zu einem Entwurf bitten"],minimum:["Eine geeignete Arbeitsprobe senden","Eine konkrete Frage zum Entwurf stellen"],cue:["Nach dem heutigen Mittagessen","Wenn der freiwillige Timer endet"],place:["An meinem üblichen Arbeitsplatz","Am Schreibtisch in der Bibliothek"],obstacle:"Ich starte bei jedem Abschweifen neu",fallback:["Ohne Timer direkt senden","Eine schriftliche Starthilfe nutzen"],observation:["Arbeitsprobe gesendet; Antwort getrennt festgehalten","Frage gestellt; Rückmeldung noch unbekannt"],stopRule:"Lass den Timer weg, wenn Neustarts die Handlung verzögern oder dich belasten. Unerwünschte Gedanken brauchen keine rituelle Korrektur.",scenario:"Aylins vorbereitete Arbeitsprobe passt zur Anfrage eines Kunden. Eine Benachrichtigung hat ihren Fokustimer unterbrochen. Vor einer Besprechung bleiben ihr fünf Minuten, um die Probe zu schicken.",question:"Wie nutzt sie diese Gelegenheit am besten?",options:[{key:"a",text:"Den Fokus einmal ohne Benachrichtigungen wiederholen. Danach senden, falls vor der Besprechung noch ausreichend Zeit dafür bleibt.",feedback:"Benachrichtigungen auszuschalten kann eine gewünschte Pause erleichtern. Die anstehende Aufgabe ist aber schon klar. Macht Aylin einen weiteren ungestörten Abschnitt zur Voraussetzung, könnte sie die Gelegenheit verlieren, die sie gerade zum Senden hat."},{key:"b",text:"Sowohl die Fokusübung als auch die Nachricht mit der Arbeitsprobe auf morgen verschieben, wenn sie länger ungestört arbeiten kann.",feedback:"Ein späterer Termin kann zu einer Aufgabe passen, die mehr Zeit braucht. Hier ist die Arbeitsprobe schon fertig und fünf Minuten sind verfügbar. Ein unterbrochenes Ritual verlangt nicht, dass Aylin auch die Nachricht verschiebt."},{key:"c",text:"Die fertige Arbeitsprobe jetzt schicken und die Nachricht getrennt von der unterbrochenen Fokuspause festhalten.",feedback:"Damit nutzt sie die Gelegenheit und hält ehrlich fest, was passiert ist. Die Arbeitsprobe wurde gesendet. Die Pause wurde unterbrochen. Aus keinem dieser beiden Fakten lässt sich ablesen, wie der Kunde entscheiden wird."}],best:"c",takeaway:"Nutze den Timer als Startsignal. Mach eine ungestörte Pause nicht zur Voraussetzung fürs Handeln.",review:"Welche hilfreiche Handlung hast du versucht? Hat dir der Timer beim Anfangen geholfen oder dich aufgehalten?",deeper:[{heading:"Was die Anleitung mit siebzehn Sekunden verlangt",paragraphs:["1. Wähle ein gewünschtes Erlebnis oder einen positiven Gedanken. Die Lehre, die Abraham durch Esther und Jerry Hicks zugeschrieben wird, verlangt, bei diesem Gedanken zu bleiben, ohne einen entgegengesetzten Gedanken zuzulassen. Das beschreibt ein Ritual, kein wissenschaftlich geprüftes Verfahren. [manifest-P13]","2. Halte den Gedanken siebzehn Sekunden lang fest. Manche Varianten verlängern die Übung auf vier aufeinanderfolgende Abschnitte, insgesamt achtundsechzig Sekunden. Wenn du die bekannte Form beibehalten möchtest, kannst du einen Timer nutzen. Die geprüften Quellen belegen aber für keine der beiden Zeitspannen eine besondere Schwelle, ab der Wünsche angezogen werden. [manifest-P13, manifest-T16]","3. Nimm wahr, ob deine Aufmerksamkeit abgeschweift ist. Mach daraus kein Urteil über deine Zukunft. Bei ODA musst du nicht neu anfangen, bevor du handeln darfst. Die Behauptungen der Lehrenden, Gedanken würden die Realität verändern oder vielen Arbeitsstunden entsprechen, sind keine Ergebnisse der hier geprüften Forschung. [manifest-P13]","4. Beende die Pause und wähle deine nächste Handlung. Experimentelle Primingforschung untersucht Reize unter bestimmten Bedingungen. Das ist etwas anderes als dieser bewusst zeitlich festgelegte Wunsch. Die gewählte Dauer kann Teil deines Rituals bleiben, ohne dadurch wissenschaftlich bestätigt zu sein. [manifest-T16, manifest-P13]"]},{heading:"Das Ende des Timers als Start nutzen",paragraphs:["Wähle eine Handlung, bevor der Timer beginnt. Für dein Portfolio könnte das heißen, heute eine passende Arbeitsprobe zu verschicken. Benenne das Hindernis: so oft neu anfangen, bis sich der Fokus perfekt anfühlt. Schreib dann: „Wenn der Timer endet, schicke ich die vorbereitete Arbeitsprobe, auch wenn ich zwischendurch abgeschweift bin.“ Falls ein Timer Druck erzeugt, wähle stattdessen einen anderen sichtbaren Anlass zum Starten. [manifest-T02]","Die Metaanalyse von Gollwitzer und Sheeran stützt konkrete Wenn-dann-Pläne im Durchschnitt über verschiedene Aufgaben hinweg. Der Primingüberblick von Dai und Kollegen fand insgesamt einen durchschnittlichen Effekt. In der begrenzten Teilgruppe vorab registrierter Studien waren die Effekte kleiner und statistisch nicht eindeutig. Diese Unsicherheit widerlegt nicht die gesamte Primingforschung. Keine der beiden Übersichten bestätigt siebzehn Sekunden, achtundsechzig Sekunden oder eine Regel, nach der unerwünschte Gedanken Ergebnisse verhindern. [manifest-T02, manifest-T16]","Die Folge aus Pause und Handlung ist ODAs Anpassung, keiner der beiden Forschungsabläufe. Halte morgen getrennt fest, welche Handlung du versucht hast, welche Rückmeldung von außen kam und wie gut du dich konzentrieren konntest. War die Pause ein brauchbarer Anlass zum Starten? Oder haben wiederholte Versuche die verfügbare Gelegenheit verbraucht? Behalte den Timer bei, verkürze die Pause oder lass ihn weg, je nachdem, was dieser praktische Rückblick zeigt. [manifest-T02, manifest-P13]"]}],sources:["manifest-P13","manifest-T02","manifest-T16"]},{number:19,technique:"Wunschbox",title:"Wunschbox: Gib einem Wunsch einen Termin zum Handeln",goal:"Behalte deine Wunschbox und tu etwas Machbares für ein konkretes Ziel.",hook:"Deine Box ist voller Wünsche. Bei welcher Karte tust du heute etwas?",reason:"Welcher Wunsch passt heute zu meiner Zeit und meinen verfügbaren Mitteln?",paragraphs:["Bei der Wunschbox bewahrst du aufgeschriebene Wünsche, Bilder oder bedeutungsvolle Gegenstände in einem Behälter auf. Eine verbreitete Anleitung: Wähle eine Box, ergänze Absichten und gewünschte Gefühle und sieh den Inhalt erneut an. Stell dir dabei die Erfüllung vor. Die geprüften Quellen stützen nicht, dass der Behälter Wünsche herbeiführt. Eine vorhandene Box genügt. [manifest-P14]","Bei ODA behältst du die Karten. Ergänze auf einer ausgewählten Karte ein konkretes Ziel, ein Hindernis, einen Wenn-dann-Plan und eine Handlung für heute. Prüfe morgen, was du tatsächlich versucht hast. Forschung stützt das Gegenüberstellen von Ziel und Hindernissen samt Plan. Auch das Beobachten von Fortschritten wird im Durchschnitt gestützt. Diese Anpassung mit einer Box wurde aber nicht als Gesamtübung geprüft. [manifest-T01, manifest-T03]"],example:{title:"Eine Karte kommt aus der Box",text:"Am Küchentisch legt Lukas eine Karte zum Wochenendkurs in einen alten Schuhkarton. Er notiert seine knappe Zeit als Hindernis und fragt den Veranstalter telefonisch nach Teilnahmealternativen. Eine flexible Teilnahme ist ausgeschlossen. Morgen hält Lukas den Anruf fest und wählt einen anderen Kurs, statt noch mehr Wünsche in die Box zu legen."},instructions:["Nimm einen vorhandenen Behälter und wähle eine Karte mit einem konkreten Ziel.","Ergänze ein Hindernis und deinen Wenn-dann-Plan. Versuche heute eine machbare Handlung.","Nimm diese Karte morgen wieder heraus und halte fest, was du tatsächlich versucht hast."],action:["Nach Teilnahmealternativen beim Kurs fragen","Eine passende Kursinformation erfragen"],minimum:["Eine konkrete Kursfrage schicken","Eine hilfreiche Anfrage stellen"],cue:["Nach dem heutigen Frühstück","Wenn die telefonische Sprechzeit beginnt"],place:["An meinem Küchentisch","In meiner ruhigen Arbeitsecke"],obstacle:"Die Kurszeiten passen vielleicht nicht",fallback:["Nach einer anderen Teilnahmeform fragen","Eine geeignete Alternative kontaktieren"],observation:["Anfrage verschickt; Antwort zu Kurszeiten festgehalten","Alternative kontaktiert; Antwort noch unbekannt"],stopRule:"Nutze Material, das du schon hast. Übersteigt eine Option deine Möglichkeiten, ändere die Handlung oder pausiere.",scenario:"Auf Lukas’ Kurskarte steht ein Terminkonflikt. Der Veranstalter kann heute Fragen beantworten. Außerdem möchte Lukas mehrere neue Bilder in seine Box legen.",question:"Welcher nächste Schritt klärt am besten, ob der Kurs passt?",options:[{key:"a",text:"Den Veranstalter nach Teilnahmealternativen fragen und die Antwort anschließend auf der Kurskarte festhalten.",feedback:"So prüft Lukas das benannte Hindernis und hält ein tatsächliches Ergebnis fest. Die Antwort kann diesen Kurs ausschließen. Auch das hilft ihm dabei, einen machbaren nächsten Schritt zu wählen."},{key:"b",text:"Zuerst die neuen Bilder ergänzen, damit die Box das ganze gewünschte Erlebnis möglichst vollständig widerspiegelt.",feedback:"Die Bilder dürfen Teil seines gewählten Rituals bleiben. Die Frage nach den Kurszeiten beantworten sie aber nicht. Heute kann Lukas die Gelegenheit nutzen und herausfinden, ob eine Teilnahme machbar wäre."},{key:"c",text:"Sofort einen anderen Kurs wählen, weil der Terminkonflikt die Teilnahme an diesem Kurs unsicher macht.",feedback:"Vielleicht passt ein anderer Kurs besser. Der Veranstalter kann die offene Frage aber jetzt klären. Eine konkrete Anfrage gibt Lukas hilfreiche Informationen, bevor er entscheidet, ob er sein Ziel ändern möchte."}],best:"a",takeaway:"Behalte die Wunschkarte, ergänze eine machbare Handlung und halte fest, was tatsächlich passiert ist.",review:"Welche Handlung hast du für die Karte versucht? Was hast du dabei über das Hindernis erfahren?",deeper:[{heading:"So entsteht die bekannte Wunschbox",paragraphs:["1. Wähle eine Box oder einen Behälter. Die Anleitung aus der Praxis nutzt die Box als Platz für Absichten. Bei ODA nimmst du etwas, das schon verfügbar ist, etwa einen alten Schuhkarton oder einen Umschlag. Einen besonderen Gegenstand zu kaufen gehört nicht zur Aufgabe. [manifest-P14]","2. Schreib Wünsche auf Karten oder wähle Bilder, die sie darstellen. In der Anleitung ergänzt du auch, warum du jedes Ergebnis möchtest und wie es sich anfühlen würde, es zu erhalten. Diese persönlichen Details dürfen privat bleiben. Eine schlichte Bezeichnung reicht aus, um die Form zu bewahren. [manifest-P14]","3. Leg die Karten oder Bilder hinein. Sieh dir den Inhalt erneut an und stell dir vor, wie die Wünsche eintreffen, falls dir dieser Teil gefällt. Diese Schritte beschreiben die Methode einer Praktikerin aus eigener Erfahrung. Sie belegen nicht, dass der Behälter ein äußeres Ereignis erzeugt. [manifest-P14]","4. Wähle eine Karte, die du mit einer echten Gelegenheit verbindest. Die Erklärung über Energiefelder aus der Anleitung ist ein Glaube, kein gesicherter Forschungsbefund. Du kannst den symbolischen Behälter behalten und zugleich ändern, was du heute mit einer Karte tust. [manifest-P14]"]},{heading:"Schreib das Hindernis auf die Rückseite",paragraphs:["Lass den Wunsch oder das Bild auf der Vorderseite. Schreib auf die Rückseite das konkrete Ziel, ein wahrscheinliches Hindernis und deinen Wenn-dann-Plan. Bei einem Kurs: „Wenn die telefonische Sprechzeit beginnt, frage ich nach Teilnahmealternativen. Wenn die Kurszeiten nicht passen, frage ich bei einer geeigneten Alternative nach.“ Wähle eine machbare Handlung für heute. Eine Karte zu basteln zählt noch nicht als Anfrage beim Veranstalter. [manifest-T01]","Mentales Kontrastieren mit Wenn-dann-Plänen verbindet ein gewünschtes Ergebnis, ein tatsächliches Hindernis und einen Handlungsplan. Die Metaanalyse fand eine mäßige durchschnittliche Unterstützung für die Zielerreichung. Die Ergebnisse unterschieden sich, und es gab Hinweise auf mögliche Publikationsverzerrung. Harkin und Kollegen fanden durchschnittliche Vorteile, wenn Menschen zum Beobachten ihres Fortschritts angeregt wurden. Keine der Übersichten prüfte eine Manifestationsbox oder zeigte, dass morgen der beste Zeitpunkt für den Rückblick ist. [manifest-T01, manifest-T03]","Mit dem Rückblick am nächsten Tag gibt ODA dieser Karte einen praktischen Prüftermin. Halte fest, was du tatsächlich gefragt und erfahren hast. Unterscheide eine verschickte Anfrage von einer hilfreichen Antwort oder einer Anmeldung. Ändere das Ziel, wenn Geld, Zugang oder Zeit es unmöglich machen. In der Box darf eine überarbeitete Karte liegen, ein pausiertes Ziel oder ein ehrlich festgehaltener Versuch, der nicht zum gewünschten Ergebnis geführt hat. [manifest-T01, manifest-T03]"]}],sources:["manifest-P14","manifest-T01","manifest-T03"]},{number:20,technique:"SATS: Zustand wie kurz vor dem Einschlafen",title:"SATS: Lass die Szene enden und schlaf",goal:"Übe mit sanften inneren Bildern einen praktischen Schritt, ohne den Schlaf hinauszuzögern.",hook:"Wiederholst du die perfekte Szene im Bett? Du darfst aufhören und morgen trotzdem einen hilfreichen Schritt machen.",reason:"Lässt mir diese Szene noch genug Raum zum Schlafen?",paragraphs:["SATS, „state akin to sleep“, bezeichnet einen schlafähnlichen Zustand. Stell dir entspannt und schläfrig eine kurze Erfüllungsszene vor. Praktizierende wählen eine Erfolgsszene, nehmen gedanklich teil und wiederholen sie, als wäre sie real. Manche schlafen ein. Gemischte Befunde für verwandte Vorstellungsübungen. Dass Schläfrigkeit Wünsche herbeiführt, ist nicht belegt. Mentale Simulation unterstützt Verhalten im Durchschnitt, belegt aber keinen besonderen Vorteil vor dem Einschlafen. [manifest-P15, manifest-T04, manifest-T19]","Bei ODA bleiben sanfte innere Bilder. Benenne dein konkretes Ziel und Hindernis, schreibe einen Wenn-dann-Plan und übe den ersten praktischen Schritt gedanklich. Tu heute eine Sache. Prüfe morgen den Verlauf. Die Szene darf unvollkommen bleiben. Hör auf, wenn die Wiederholung dich wach hält. Schlaf ist keine Glaubensprüfung. [manifest-P15, manifest-T19]"],example:{title:"Eine Szene mit einer Grenze",text:"Nina schickt am Schreibtisch eine Frage zur Weiterbildung. Vor dem Schlafengehen stellt sie sich kurz die Teilnahme vor. Sie probt die Gebührenfrage für die morgige Mittagspause. Dabei wird sie wacher und hört auf. Morgen fragt sie nach. Die Weiterbildung ist zu teuer. Sie notiert die Antwort und sucht eine kostenlose Alternative."},instructions:["Notiere dein Ziel, ein Hindernis und deinen Wenn-dann-Plan, bevor du zur Ruhe kommst.","Übe den ersten Schritt kurz im Kopf. Tu heute eine Sache, die dir weiterhilft.","Gib dem Schlaf Vorrang. Prüfe morgen, welche Handlung du tatsächlich versucht hast."],action:["Nach den Gebühren einer Weiterbildung fragen","Eine hilfreiche Information zum Zugang erfragen"],minimum:["Eine konkrete Gebührenfrage schicken","Eine Frage zum Zugang stellen"],cue:["Nach der heutigen Mittagspause","Wenn das Kursbüro öffnet"],place:["An meinem üblichen Arbeitsplatz","An meinem Küchentisch"],obstacle:"Die inneren Bilder halten mich wach",fallback:["Tagsüber mit Worten durchspielen","Ohne innere Bilder direkt fragen"],observation:["Frage gestellt; Antwort getrennt festgehalten","Schlaf gestört; Vorstellungsübung beendet"],stopRule:"Hör auf, wenn die inneren Bilder dich wacher machen oder belasten. Übe tagsüber oder lass die Bilder weg. Schütze deinen Schlaf.",scenario:"Nina hat einen klaren Plan, tagsüber nach den Gebühren zu fragen. Die wiederholte SATS-Szene hält sie wach. Trotzdem fühlt sich die Szene noch nicht ganz real an.",question:"Wofür sollte sie sich jetzt entscheiden?",options:[{key:"a",text:"Die Szene vereinfachen und weiter wiederholen, bis sie sich überzeugend genug anfühlt, um die Übung zu beenden.",feedback:"Eine einfachere Szene kann zum Üben am Tag passen. Überzeugung ist aber keine notwendige Bedingung, um aufzuhören. Die Wiederholung hält Nina wach. Wenn sie weitermacht, stellt sie das Ritual vor ihren Schlaf."},{key:"b",text:"Die Szene beenden, sich Zeit zum Einschlafen lassen und beim geplanten Anlass tagsüber nach den Gebühren fragen.",feedback:"Ihr konkreter Anlass zum Fragen steht bereits fest. Aufzuhören schützt ihren Schlaf, ohne das Ziel aufzugeben. Morgen kann sie festhalten, welche Frage sie gestellt und welche Informationen zu den Gebühren sie erhalten hat."},{key:"c",text:"Die Gebührenfrage durch eine längere SATS-Übung tagsüber ersetzen, die sich leichter steuern lässt.",feedback:"Tagsüber passen freiwillige innere Bilder vielleicht besser. Eine längere Szene beantwortet aber weiterhin keine Gebührenfrage. Bleib bei der echten Anfrage und nutze das Durchspielen höchstens als Vorbereitung darauf."}],best:"b",takeaway:"Eine kurze Szene darf enden, bevor sie perfekt wirkt. Halte den tatsächlichen Versuch für sich fest.",review:"Welche Handlung hast du versucht? Haben dir die inneren Bilder genug Raum zum Schlafen gelassen?",deeper:[{heading:"Die Szene in der SATS-Lehre",paragraphs:["1. Wähle ein Ergebnis und eine kurze Szene, die voraussetzt, dass es schon eingetreten ist. Neville Goddards Vorträge beschreiben, selbst an dieser Erfüllungsszene teilzunehmen, statt sich von außen zu beobachten. Das ist die Methode des Lehrers. Sie ist kein nachgewiesener Weg, Ereignisse außerhalb deiner Kontrolle zu verändern. [manifest-P15]","2. Setz oder leg dich bequem hin. Schließe die Augen, wenn du möchtest, und entspanne dich, bis du schläfrig wirst. Die Quelle behandelt diesen Zustand als Teil der Übung. Bei ODA darfst du die Augen offen lassen oder mit Worten arbeiten. Du musst Schläfrigkeit nicht erzwingen. [manifest-P15]","3. Wiederhole die kurze Szene und stell sie dir als real vor. Manche Varianten lassen den Schlaf in diesem Gefühl kommen. Andere bleiben sanft aufmerksam. Du darfst aufhören, bevor die Szene überzeugend wirkt. Halte dich nicht wach, um einen vorgestellten Maßstab zu erfüllen. [manifest-P15]","4. Trenne metaphysische Behauptungen von der Anleitung. Eine Übersicht zur Aktivierung des Nervensystems beschreibt, wie Schaltkreise für Schlaf und Wachheit zusammenwirken. Sie belegt nicht, dass Schläfrigkeit Wünsche wahr macht. Goddards Lehre, es sei keine Handlung nötig, ist kein Ergebnis der Forschung zu mentaler Simulation. [manifest-P15, manifest-T19, manifest-T04]"]},{heading:"Einen Schritt üben und den Schlaf schützen",paragraphs:["Wähle ein konkretes Ziel und benenne das Hindernis, bevor du zur Ruhe kommst. Bei einer Weiterbildung könnte dein Ziel sein, zu prüfen, ob du dir die Gebühren leisten kannst. Spiele kurz durch, wie du die tatsächliche Frage stellst. Nimm auch auf, was du tust, wenn die Antwort die Teilnahme ausschließt. Das ist die praktische Anpassung von ODA. Sie muss weder Goddards vorgeschriebenes Gefühl noch seine Szene nachbilden. [manifest-P15, manifest-T04]","Die Zusammenfassung von Cole und Kollegen fand einen durchschnittlichen Vorteil für Verhalten durch mentale Simulation. Sie umfasste unterschiedliche Studien, überwiegend mit Studierenden. Eine verlässliche Rangfolge zwischen den Arten der Simulation oder ein besonderer Vorteil vor dem Einschlafen wurde nicht belegt. Auch die Übersicht zur Aktivierung des Nervensystems zeigt nicht, dass Schläfrigkeit das Denken umgeht oder Ergebnisse von außen herbeiführt. Allgemeine Befunde zu inneren Bildern bestätigen nicht jede Behauptung über SATS. [manifest-T04, manifest-T19]","Wähle einen Anlass am Tag für die echte Frage. Stelle heute eine hilfreiche Anfrage, wenn das passend ist. Halte morgen die Anfrage und die Antwort getrennt von der Vorstellungsübung fest. Macht dich die Szene wacher, hör auf. Übe tagsüber oder verzichte auf innere Bilder. Die nächste Handlung kann weiter geplant bleiben, auch wenn du die Szene unvollendet lässt. Dieser gesamte Ablauf wurde nicht als SATS-Intervention geprüft. [manifest-P15, manifest-T04, manifest-T19]"]}],sources:["manifest-P15","manifest-T04","manifest-T19"]}],r=d.sort((e,n)=>e.number-n.number).map(h),u=[...s,{id:"M01",title:"Wang, Wang & Gai · 2021 · Mentales Kontrastieren mit Wenn-dann-Plänen",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"24 unabhängige Effekte aus 21 Artikeln, 15.907 Teilnehmende: ein kleiner durchschnittlicher Vorteil beim Erreichen von Zielen, g = 0,336 [0,229; 0,443]. Nach Korrektur möglicher Publikationsverzerrung lag die Schätzung bei 0,242 [0,143; 0,342].",limitation:"Die Ergebnisse unterschieden sich deutlich; es gab Hinweise auf Publikationsverzerrung. Dieser Kurs und seine kurzen Übungen wurden nicht untersucht. Ergebnisse sind nicht garantiert."},{id:"M02",title:"Gollwitzer & Sheeran · 2006 · Wenn-dann-Pläne und das Erreichen von Zielen",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"94 unabhängige Tests mit 8.461 Teilnehmenden: konkrete Wenn-dann-Pläne halfen im Durchschnitt beim Erreichen von Zielen, d = 0,65 [0,60; 0,70].",limitation:"Ältere, uneinheitliche Studien, nicht durchgängig vorab registriert. Ein Plan macht Anstrengung, Erinnern, praktische Grenzen und Unsicherheit nicht überflüssig."},{id:"M03",title:"Harkin et al. · 2016 · Fortschritte auf dem Weg zum Ziel festhalten",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"138 Experimente mit insgesamt 19.951 Teilnehmenden. Die Analyse zur Zielerreichung umfasste 18.398 Personen: d = 0,40 [0,32; 0,48]. Eine Zusatzanalyse zu Verzerrungen durch kleine Studien ergab 0,19 [0,10; 0,28].",limitation:"Ziele und Methoden waren unterschiedlich. Zusammenhänge mit Studienmerkmalen verpflichten nicht zum öffentlichen Teilen. Dieses genaue Protokoll, die Rückblicktermine und der ODA-Kurs wurden nicht validiert."},{id:"M04",title:"Cole et al. · 2021 · Handlungen gedanklich durchspielen und Verhalten ändern",url:"https://link.springer.com/article/10.3758/s13423-021-01880-6",type:"research",finding:"94 Studien, 123 Effekte, 5.685 Teilnehmende: insgesamt g = 0,49 [0,37; 0,62] für gedankliches Durchspielen. Der Gesamttest zum Vergleich der einzelnen Formen war statistisch nicht signifikant.",limitation:"Meist Studierende und unterschiedliche Übungen. Für reine Ablaufvorstellungen lagen fünf Effekte mit unklarer Schätzung vor. Keine verlässliche Rangfolge der Formen; diese kurze Übung wurde nicht validiert."},{id:"M07",title:"Dixon, Hornsey & Hartley · 2025, online 2023 · Glaube an Manifestation",url:"https://journals.sagepub.com/doi/full/10.1177/01461672231181162",type:"research",finding:"Drei US-Onlinebefragungen mit 1.023 Teilnehmenden: Manifestationsglaube hing mit einigen selbst berichteten finanziellen Risiken und Insolvenzen zusammen, aber nicht mit selbst berichtetem Einkommen oder Bildungsstand.",limitation:"Zusammenhänge belegen keine Ursache und prüfen nicht jede Manifestationstechnik objektiv. Selbst berichtete finanzielle Ergebnisse sagen die Zukunft einer einzelnen Person nicht voraus."},{id:"M10",title:"Gollwitzer & Brandstätter · 1997 · Eine konkrete Gelegenheit zum Anfangen planen",url:"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/gollwitzer_brandstatter_1997_-_implementation_intentions_effective_goal_pursuit.pdf",type:"research",finding:"In Studie 2 sollten 86 Studierende einen Bericht schreiben. Von 36 eindeutig zuordenbaren Rücksendenden schrieben 12/17 mit Plan und 6/19 in der Kontrollgruppe innerhalb von zwei Tagen.",limitation:"71 % gegenüber 32 % betrifft die Rücksendenden, nicht alle aufgenommenen Personen. Planung erhöhte die Mitarbeit insgesamt nicht. Eng begrenzte Studienaufgabe; der ODA-Kurs wurde nicht validiert."},{id:"M11",title:"Oettingen et al. · 2015 · Planung und Termine im Kalender",url:"https://doi.org/10.1002/ejsp.2090",type:"research",finding:"Studie 1 wertete 84 Studierende aus. Der vorab geplante Vergleich fiel bei eingeplanten Stunden zugunsten von mentalem Kontrastieren plus Wenn-dann-Plänen aus, p = 0,03; Gesamttest p = 0,057.",limitation:"Gemessen wurde geplante Zeit, keine erledigte Arbeit oder Produktivität. Unvollständige Antworten wurden ausgeschlossen. Die kurze Kursfassung und ihre Einteilung praktischer Bedingungen wurden nicht untersucht."},{id:"M14",title:"NIMH · Hilfe bei psychischen Erkrankungen",url:"https://www.nimh.nih.gov/health/find-help",type:"guidance",finding:"Die offizielle Orientierung zeigt Wege zu fachlicher Unterstützung und Krisenhilfe bei Belastung, Beeinträchtigung oder unmittelbarer Gefahr.",limitation:"Eine Orientierung, keine Wirksamkeitsstudie. ODA diagnostiziert oder behandelt keine psychischen Erkrankungen. Außerhalb der USA nutze die örtlichen Behandlungsangebote und Notdienste."},{id:"manifest-positive-fantasies",title:"Kappes & Oettingen · 2011 · Idealisierte positive Zukunftsfantasien",url:"https://bpb-us-e1.wpmucdn.com/wp.nyu.edu/dist/c/6235/files/2019/02/kappes-et-al-2011-positive-fantasies-about-idealized-futures-sap-energu.pdf",type:"research",finding:"Vier Experimente, überwiegend mit Studierenden, fanden nach manchen idealisierten positiven Fantasien unmittelbar weniger Energie. Studie 3 verglich positive mit neutralen oder ungelenkten Fantasien, nicht mit hinterfragenden Fantasien.",limitation:"Kleine, kurze Experimente. Optimismus und Vorstellungskraft sind nicht grundsätzlich schädlich. Weder eine wiederkehrende Fantasieschleife noch ein Gehirnsignal für bereits erreichte Ziele wurde gemessen."},{id:"manifest-belief-study",title:"Dixon, Hornsey & Hartley · 2025, online 2023 · Glaube an Manifestation",url:"https://journals.sagepub.com/doi/full/10.1177/01461672231181162",type:"research",finding:"Drei US-Onlinebefragungen mit insgesamt 1.023 Teilnehmenden fanden Zusammenhänge von Manifestationsglaube mit Zuversicht und einigen selbst berichteten finanziellen Risiken, darunter Insolvenzen. Kein Zusammenhang mit selbst berichtetem Einkommen oder Bildungsstand.",limitation:"Zusammenhänge belegen keine Ursache und prüfen nicht jede Technik objektiv. Selbst berichtete Ergebnisse sind keine Vorhersage für eine einzelne Person."},{id:"manifest-murphy",title:"Joseph Murphy · Die Macht Ihres Unterbewusstseins · Herkunft laut Verlag",url:"https://www.penguinrandomhouse.com/books/296695/the-power-of-your-subconscious-mind-by-joseph-murphy-phd-dd/",type:"technique",finding:"Der Verlag beschreibt Murphys bekanntes Selbsthilfebuch und seine Lehren über Vorstellungskraft und Glauben.",limitation:"Verlagsbeschreibung, keine kontrollierte Studie. Die genauen Passagen zum Abendritual wurden nicht überprüft. Hier gibt es keine Belege für das Anziehen von Reichtum, Heilung oder besonders wirksames Lernen vor dem Schlafen."}],i=[{schemaVersion:2,revision:2,id:"manifest-1",courseId:"manifest",locale:"de",title:"Dein Traum wartet? Mach heute etwas Brauchbares",goal:"Erarbeite einen brauchbaren Teil für ein Ziel, das du selbst wählst.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"Wieder eine Woche vom anderen Leben geträumt? Mach aus einem Wunsch heute etwas, das du nutzen kannst.",reason:{id:"manifest-1-reason",label:"Wessen Ziel ist das, und wofür lohnt sich deine Zeit?",kind:"text",maxLength:160,optional:!0,suggestions:["Mein Ziel; abends scrollen kann warten","Familie geht vor; Feinschliff kann warten","Das Ziel anderer; Zeit dafür überdenken","Ich weiß nicht, wessen Ziel das ist"]},why:{id:"manifest-1-purpose",label:"Was würde dir dieser Schritt in deiner Woche ermöglichen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Ein besserer Job ist ein Ergebnis. Einen Satz im Lebenslauf zu verbessern ist eine Handlung. Ob jemand dich anruft, entscheiden weiterhin andere. Mach etwas, das sich lohnt. Miss deinen Einsatz nicht an der erhofften Antwort.","In einem Experiment mit Studierenden half ein festgelegter Start mit Zeit und Ort, einen Bericht rechtzeitig zu schreiben. Das galt für jene, die ihn zurückschickten. Die Mitarbeit insgesamt nahm nicht zu. Ein Plan kann beim Anfangen helfen, garantiert aber kein Ergebnis. Erarbeite heute einen brauchbaren Satz, eine Antwort oder eine Bitte. Bleib im Kurs bei diesem Ziel und komm mit dem zurück, was passiert ist."],example:{title:"Daniel fängt an",text:"Nach dem Abendessen setzt Daniel sich für zehn Minuten an den Küchentisch. Er sucht einen Logistikjob. Im Lebenslauf beschreibt er neu, wie er acht Lagerschichten geplant hat. Der Satz klingt noch holprig. Trotzdem speichert er ihn und notiert die Änderung. Ein Arbeitgeber hat ihn noch nicht gesehen. Morgen kann Daniel einen echten Entwurf verbessern."}},move:{invitation:"Wähle deine Handlung. Die Vorschläge zeigen Daniels Lebenslauf.",instructions:["Benenne vor dem Speichern das Dokument, die Frage oder den Gegenstand, den du veränderst.","Erledige dein Minimum. Halte es getrennt von einer Antwort anderer fest."],prompts:[],suggestions:{action:["Einen Lebenslaufsatz zur Schichtplanung neu schreiben","Nach einer fehlenden Angabe im Lebenslauf fragen","Eine Arbeitsprobe zur Besetzung von Schichten erstellen"],minimum:["Einen Lebenslaufsatz zur Schichtplanung speichern","Die Frage zur fehlenden Lebenslaufangabe abschicken","Eine Arbeitsprobe zur Besetzung von Schichten speichern"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1},{label:"In zwei Tagen",daysFromToday:2}],cue:["Wenn das Abendessen abgeräumt ist","Wenn die Mittagspause zu Ende ist","Nach meinem Getränk am Morgen"],place:["An meinem Küchentisch","Am Schreibtisch in der Bibliothek","Im Dokument mit meinem Lebenslauf"],minutes:[10,2,5],fallback:["Eine Schichtänderung in einfachen Worten beschreiben","Eine andere freie Gelegenheit auswählen und benennen","In der Bibliothek nach Computerzugang fragen"],observation:["Den Lebenslaufsatz, den ich gespeichert habe","Ob ich die Lebenslauffrage abgeschickt habe","Was mich an meinem Minimum gehindert hat"]},suggested:{action:"Einen Lebenslaufsatz zur Schichtplanung neu schreiben",minimum:"Einen Lebenslaufsatz zur Schichtplanung speichern",minutes:10,cueHint:"Wenn das Abendessen abgeräumt ist",placeHint:"An meinem Küchentisch",obstacleHint:"Ich habe weniger Zeit als geplant",fallbackHint:"Eine Schichtänderung in einfachen Worten beschreiben",observationHint:"Den Lebenslaufsatz, den ich gespeichert habe"},accessibleAlternative:"Tippe, diktiere oder nutze deine gewohnten Hilfsmittel. Bitte bei Bedarf um praktische Hilfe.",stopRule:"Pausiere Schritte, die unsicher oder nicht bezahlbar sind. Suche stattdessen praktische Unterstützung."},result:{question:"Hast du dein gewähltes Minimum erledigt?",observationPrompt:"Was hast du tatsächlich getan oder erarbeitet?"},judgment:{primary:{id:"manifest-1-decision",scenario:"Daniel hat eine passende Stelle gefunden und zehn Minuten vor dem Abendessen. Sein Lebenslauf beschreibt die gefragte Erfahrung mit der Schichtplanung noch nicht.",question:"Was wäre der sinnvollste erste Versuch?",options:[{id:"manifest-1-research-more",text:"Weitere Stellen vergleichen, um zu prüfen, ob dieser Job wirklich zu seinem gewünschten Leben passt.",feedback:"Stellen zu vergleichen kann ein Ziel klären. Diese Stelle passt bereits. Was fehlt, ist eine brauchbare Beschreibung von Daniels Erfahrung. Verbessere diesen Satz in der verfügbaren Zeit."},{id:"manifest-1-improve-line",text:"Einen Lebenslaufsatz für diese Stelle überarbeiten, den Entwurf speichern und notieren, was noch Arbeit braucht.",feedback:"So entsteht in zehn Minuten etwas, das Daniel nutzen kann. Der Entwurf braucht vielleicht Rückmeldung, und der Arbeitgeber antwortet womöglich nicht. Beides macht die geleistete Arbeit nicht ungeschehen."},{id:"manifest-1-clarify-future",text:"Seinen idealen Arbeitstag genau beschreiben und erst danach entscheiden, was er in den Lebenslauf schreibt.",feedback:"Der gewünschte Arbeitstag kann später bei Entscheidungen helfen. Daniel hat schon eine passende Stelle gewählt. Mehr Beschreibung verschiebt die konkrete Lücke. Schreibe den Lebenslaufsatz und prüfe dann, was noch fehlt."}],bestOptionId:"manifest-1-improve-line"}},carry:{takeaway:"Mach aus dem Wunsch eine Handlung. Halte sie getrennt von der erhofften Antwort fest.",followUp:{questionId:"manifest-1-return",question:"Was kannst du nach deinem Versuch jetzt tatsächlich nutzen?",observationPrompt:"Was ist bei deiner geplanten Gelegenheit passiert?",adjustmentPrompt:"Welche einzelne Änderung passt zu deiner nächsten Gelegenheit?"}},goDeeper:{sections:[{heading:"Wobei ein Plan zum Anfangen helfen kann",paragraphs:["In ihrer Studie 2 von 1997 ließen Gollwitzer und Brandstätter 86 Münchner Studierende einen Bericht über Weihnachten schreiben. Die Planungsgruppe wählte eine genaue Zeit und einen Ort, stellte sich diese Gelegenheit vor, nahm sich vor, dort anzufangen, und hielt die Entscheidungen fest. Von 36 eindeutig zuordenbaren Rücksendenden schrieben 12 von 17 mit Plan und sechs von 19 in der Kontrollgruppe innerhalb der geforderten zwei Tage. Diese Anteile betreffen die Rücksendenden, nicht alle aufgenommenen Personen. Planung erhöhte die Mitarbeit insgesamt nicht. [M10]","Diese Lektion übernimmt die konkrete Gelegenheit und verbindet sie mit brauchbarer Arbeit. Diese Übertragung auf andere Aufgaben wurde in der Weihnachtsbericht-Studie nicht geprüft. Ein Datum allein sagt dir noch nicht, woher die Zeit kommen soll. Wähle ein Ereignis, das du erkennst, und einen Ort, den du erreichen kannst. Fehlen nötige Mittel, kann es der passende Schritt sein, danach zu fragen. Halte diese Bitte als Bitte fest, auch wenn die Hilfe noch nicht da ist."]},{heading:"Dein Wunsch steuert keine anderen Menschen",paragraphs:["Wang und Kollegen fassten 2021 in einer Übersichtsarbeit 24 unabhängige Effekte aus 21 Artikeln mit 15.907 Teilnehmenden zusammen. Ein gewünschtes Ergebnis mit einem Hindernis und einer Wenn-dann-Reaktion zu verbinden, brachte im Durchschnitt einen kleinen Vorteil bei der Zielerreichung: g = 0,336, mit einem 95%-Konfidenzintervall von 0,229 bis 0,443. Die Ergebnisse unterschieden sich deutlich. Eine Korrektur möglicher Publikationsverzerrung senkte die Schätzung. Das stützt Planung innerhalb ihrer Grenzen, aber kein Erfolgsversprechen für diesen Kurs. [M01]","Dixon und Kollegen untersuchten Manifestationsglauben in drei US-Onlinebefragungen mit insgesamt 1.023 Teilnehmenden. Er hing mit einigen selbst berichteten finanziellen Risiken und Insolvenzen zusammen, nicht mit selbst berichtetem Einkommen oder Bildungsstand. Diese Zusammenhänge belegen nicht, dass der Glaube Insolvenzen verursacht hat. Sie prüfen auch nicht jede Manifestationsübung objektiv. [M07] Nutze deinen Wunsch, um eine Aufgabe zu wählen und Grenzen zu prüfen. Schließe daraus nicht, dass Gedanken eine Gelegenheit angezogen oder Not verursacht haben. Du hast dir ein Ergebnis auch nicht durch Gedanken verdient. Geld, Sorgearbeit, Zugang und die Entscheidungen anderer bleiben relevant."]}],sourceIds:["M10","M01","M07"]}},{schemaVersion:2,revision:2,id:"manifest-2",courseId:"manifest",locale:"de",title:"Wieder nur geübt? Bring den Satz aufs Papier",goal:"Übe eine schwierige Stelle im Kopf. Erarbeite dann den nächsten brauchbaren Teil deiner bisherigen Aufgabe.",minutes:{learning:6,suggestedAction:5,review:2,rehearsal:1},direction:{hook:"Das fertige Wunschleben kannst du dir leicht vorstellen. Was passiert, wenn die Seite vor dir leer ist?",reason:{id:"manifest-2-reason",label:"Hilft eine weitere Probe, oder ersetzt sie den tatsächlichen Versuch?",kind:"text",maxLength:160,optional:!0,suggestions:["Sie zeigt mir eine fehlende Anweisung","Sie verzögert das Schreiben eines fertigen Satzes","Ich habe noch keine Probe festgehalten"]},why:{id:"manifest-2-purpose",label:"Was würde dir dieser Schritt in deiner Woche ermöglichen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Hol deine Aufgabe und vorhandene Notizen hervor. Im Kopf zu üben bedeutet, eine bestimmte Handlung gedanklich auszuführen, etwa den ersten Satz zu sagen. Schritte aufzulisten ist eine andere Art der Vorbereitung. Beides ist noch kein tatsächlicher Versuch.","Eine Übersichtsarbeit fand im Durchschnitt Vorteile für das Verhalten durch gedankliches Durchspielen. Eine beste Form war nicht belegt. Das beweist nicht, dass diese kurze Probe wirkt. Nutze sie, um deine schwierige Stelle und eine mögliche Reaktion zu erkennen. Beschreibe die Handlung in Worten, wenn keine Bilder kommen. Schreibe danach den nächsten brauchbaren Satz für dieselbe Aufgabe."],example:{title:"Daniel vor der leeren Zeile",text:"Nach dem Abendessen öffnet Daniel seinen Lebenslauf wieder. Dreißig Sekunden lang übt er im Kopf, eine schwierige Schichtänderung zu beschreiben. Er erwartet, ins Stocken zu geraten, und probt: „Acht Schichten umgeplant, als …“ Dann tippt er einen brauchbaren Satz. Er streicht zwei Wörter und notiert eine Rückfrage. Wie viele Details nötig sind, hatte seine Probe nicht gezeigt."},rehearsal:{label:"Freiwillige Vorbereitung",steps:["Beschreibe den nächsten Schritt und eine Stelle, an der du wahrscheinlich hängen bleibst.","Übe deine erste Reaktion einmal im Kopf. Das ist Vorbereitung."]}},move:{invitation:"Bleib bei deiner Aufgabe. Passe die Lebenslaufbeispiele an.",instructions:["Behalte Handlung, Minimum, Startsignal und Ort bei. Geh die schwierige Stelle an.","Ohne Plan: Benenne vor dem Speichern deine Handlung und eine verfügbare Gelegenheit.","Übe einmal, dann handle. Nur im Kopf zu üben bleibt Vorbereitung."],prompts:[],suggestions:{action:["Kurz üben, dann einen Satz zur Schichtplanung schreiben","Im Kopf üben, dann nach einer Lebenslaufangabe fragen","Mit schriftlichen Schritten ein Datum im Lebenslauf berichtigen"],minimum:["Nach der Probe einen Lebenslaufsatz speichern","Die Frage zur fehlenden Lebenslaufangabe abschicken","Ein berichtigtes Datum im Lebenslauf speichern"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1},{label:"In zwei Tagen",daysFromToday:2}],cue:["Wenn das Abendessen abgeräumt ist","Wenn die Mittagspause zu Ende ist","Wenn ich das Dokument mit meinem Lebenslauf öffne"],place:["An meinem Küchentisch","Am Schreibtisch in der Bibliothek","Im Dokument mit meinem Lebenslauf"],minutes:[5,2,10],fallback:["Die Probe beenden; eine echte Schichtänderung aufschreiben","Ohne Bilder arbeiten; den ersten schriftlichen Schritt nutzen","Nachfragen, welche Angabe im Lebenslauf fehlt"],observation:["Was die Probe bei der Handlung übersehen hat","Den Lebenslaufsatz, den ich tatsächlich erarbeitet habe","Ob ich nur im Kopf geübt habe"]},suggested:{action:"Kurz üben, dann einen Satz zur Schichtplanung schreiben",minimum:"Nach der Probe einen Lebenslaufsatz speichern",minutes:5,cueHint:"Wenn das Abendessen abgeräumt ist",placeHint:"An meinem Küchentisch",obstacleHint:"Ich feile an der Probe, statt anzufangen",fallbackHint:"Die Probe beenden; eine echte Schichtänderung aufschreiben",observationHint:"Was die Probe bei der Handlung übersehen hat"},accessibleAlternative:"Tippe, diktiere oder nutze deine gewohnten Hilfsmittel. Bitte bei Bedarf um praktische Hilfe.",stopRule:"Wenn dich Planen im Bett wach hält, hör auf und nutze eine Gelegenheit tagsüber."},result:{question:"Hast du dein gewähltes Minimum erledigt?",observationPrompt:"Was hast du tatsächlich getan oder erarbeitet?"},judgment:{primary:{id:"manifest-2-decision",scenario:"Daniel kann seinen ersten Lebenslaufsatz schon formulieren. Das Dokument ist bereit. Trotzdem möchte er die ganze Bewerbung noch einmal im Kopf durchgehen.",question:"Welcher nächste Schritt hilft bei diesem Versuch?",options:[{id:"manifest-2-full-rehearsal",text:"Die ganze Bewerbung noch einmal im Kopf durchgehen, um den besten Einstieg zu wählen, bevor er etwas schreibt.",feedback:"Eine vollständige Probe kann spätere Arbeit vorbereiten. Daniel hat aber schon einen brauchbaren Einstieg und das Dokument vor sich. Noch ein Durchlauf verschiebt den verfügbaren Versuch. Tippe den Satz und prüfe ihn."},{id:"manifest-2-new-goal-scene",text:"Sich den ersten Arbeitstag im neuen Job vorstellen, um neue Motivation zu finden, und später zur Bewerbung zurückkehren.",feedback:"Der vorgestellte Job kann zeigen, warum er dir wichtig ist. Er prüft Daniels vorbereiteten Einstieg aber nicht. Nutze den Satz jetzt im Dokument. Schau danach, was schwieriger war als erwartet."},{id:"manifest-2-perform-opening",text:"Den ersten Satz einmal im Kopf üben, in den Entwurf tippen und die tatsächliche Schwierigkeit mit der Erwartung vergleichen.",feedback:"So unterstützt die Vorbereitung eine echte Handlung. Daniel hat einen getippten Satz, den er prüfen kann. Qualität und Unbehagen bleiben offene Fragen. Beides entscheidet nicht darüber, ob der Versuch zählt."}],bestOptionId:"manifest-2-perform-opening"}},carry:{takeaway:"Lass auf hilfreiche Vorbereitung eine echte Handlung folgen. Halte beides getrennt fest.",followUp:{questionId:"manifest-2-return",question:"Was war beim tatsächlichen Schritt anders als bei der Probe?",observationPrompt:"Was ist bei deiner geplanten Gelegenheit passiert?",adjustmentPrompt:"Welche einzelne Änderung passt zu deiner nächsten Gelegenheit?"}},goDeeper:{sections:[{heading:"Keine klare Rangfolge der Vorstellungsformen",paragraphs:["Cole und Kollegen fassten 2021 in einer Übersichtsarbeit 94 Studien, 123 Effekte und 5.685 Teilnehmende zusammen. Gedankliches Durchspielen zeigte insgesamt einen Verhaltenseffekt von g = 0,49, mit einem 95%-Konfidenzintervall von 0,37 bis 0,62. Meist waren die Teilnehmenden Studierende. Inhalt, Umfang und gemessene Ergebnisse der Übungen unterschieden sich. Der Durchschnitt sagt daher nicht voraus, was deine kurze Übung bewirkt. [M04]","Die Übersichtsarbeit unterschied zwischen dem Durchdenken von Ablaufschritten und dem gedanklichen Ausführen einer Aufgabe. Die Schätzung für reine Ablaufvorstellungen beruhte auf fünf Effekten; ihr Konfidenzintervall umfasste auch den Wert für keinen Effekt. Der Gesamtvergleich der Formen war statistisch nicht signifikant. Höhere Durchschnittswerte einzelner Gruppen belegen deshalb keinen verlässlichen Sieger. Eine Grafik ist kein Auftrag, intensiver zu visualisieren. Diese Lektion nutzt die Probe, um ein praktisches Detail sichtbar zu machen. Danach versuchst du die Aufgabe. Eine Beschreibung in Worten bietet einen zugänglichen Weg. Das bedeutet nicht, dass ihre Gleichwertigkeit mit Bildern wissenschaftlich belegt wäre."]},{heading:"Bereite eine Gelegenheit vor und nutze sie dann",paragraphs:["Im ursprünglichen Experiment zur Berichtsplanung stellten sich die Teilnehmenden eine konkrete Zeit und einen Ort zum Anfangen vor. Der Vergleich zur rechtzeitigen Bearbeitung betraf eindeutig zuordenbare Rücksendende und eine eng begrenzte Studienaufgabe. Daraus folgt weder ein allgemeines Vorstellungsskript noch ein Vorteil von Proben im Bett. [M10] Hier ist Vorbereitung dann sinnvoll, wenn sie dir beim nächsten Teil deiner bisherigen Aufgabe hilft.","Vielleicht bemerkst du ein fehlendes Passwort, eine unklare Anweisung oder einen Satz, den du noch nicht erklären kannst. Ein Passwort zurückzusetzen ist Vorbereitung. Benötigte Angaben abzusenden ist Arbeit an der Aufgabe. Zeig diesen Unterschied in deinen Notizen. Hör mit Planung vor dem Schlafen auf, wenn sie dich wach hält, und plane stattdessen tagsüber. Das ist eine praktische Anpassung für diesen Kurs. Die kurze Probe ist freiwillig. Sie ist weder ein validiertes Ritual noch eine Voraussetzung zum Anfangen. Du brauchst kein lebhaftes Bild und kein bestimmtes Gefühl."]}],sourceIds:["M04","M10"]}},{schemaVersion:2,revision:2,id:"manifest-3",courseId:"manifest",locale:"de",title:"Das Hindernis ist echt. Ändere die Bedingungen",goal:"Nutze deinen letzten Versuch, um eine machbare Reaktion auf ein Hindernis zu wählen und auszuprobieren.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"Kinderbetreuung, fehlender Zugang oder Erschöpfung stehen im Weg? Mehr Glaube schafft keine freien Stunden im Tag.",reason:{id:"manifest-3-reason",label:"Wo brauchst du Hilfe, und was kannst du jetzt ändern?",kind:"text",maxLength:160,optional:!0,suggestions:["Laptop teilen; Nutzung gemeinsam absprechen","Ich kann die Lebenslaufarbeit verkleinern","Sorgearbeit lässt heute keine Gelegenheit frei","Mir ist noch kein Hindernis begegnet"]},why:{id:"manifest-3-purpose",label:"Was würde dir dieser Schritt in deiner Woche ermöglichen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Nutze dein Ziel und vorhandene Notizen. Ohne Versuch: Benenne ein wahrscheinliches Hindernis. „Abends ist der gemeinsame Computer belegt“ hilft, eine Reaktion zu finden. „Mir fehlt Disziplin“ beschreibt die Bedingung nicht.","Studien, die ein gewünschtes Ergebnis mit einem echten Hindernis und einer Wenn-dann-Reaktion verbanden, fanden im Durchschnitt kleine Vorteile. Sie belegten nicht, dass Unbehagen die Wirkung erklärt. Geld, Sorgearbeit, Zeit und Zugang sind Bedingungen, keine Glaubensfehler. Probiere eine Änderung: eine kleinere Aufgabe, eine freie Gelegenheit oder eine konkrete Bitte um Hilfe. Eine Bitte zählt als Fragen, nicht als erhaltene Hilfe."],example:{title:"Daniel sucht eine andere Gelegenheit",text:"Daniel wollte nach dem Abendessen seinen Lebenslauf bearbeiten. Seine Tochter brauchte aber den gemeinsamen Laptop für Hausaufgaben. Er notiert den Konflikt. Er fragt, ob er ihn morgen zehn Minuten vor dem Abendessen nutzen kann. Sie einigen sich. Dann verbessert er einen Satz und hört auf. Die Bewerbung ist noch nicht fertig."}},move:{invitation:"Brauchst du Zugang? Wähle „Diesen Schritt anpassen“, dann „Unterstützung“. Benenne deine Kontaktperson. Die Vorschläge zeigen Daniels Bitte um Laptopzeit.",instructions:["Behalte Handlung, Minimum, Startsignal und Ort bei, wenn der Zugang bereits abgesprochen ist.","Ohne Zugang: Benenne Person, Hilfsmittel und Gelegenheit in deiner Bitte um Unterstützung.","Halte die Bitte getrennt von erhaltener Hilfe und erledigter Arbeit fest."],prompts:[],suggestions:{action:["Tochter um Laptopzeit vor dem Abendessen bitten","In der Bibliothek nach freier Computerzeit fragen"],minimum:["Tochter um zehn Minuten am Laptop bitten","Die Frage nach Computerzugang in der Bibliothek abschicken"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1},{label:"In zwei Tagen",daysFromToday:2}],cue:["Wenn wir die Hausaufgaben zu Hause besprechen","Nach dem Mittagessen heute","Wenn das Abendessen abgeräumt ist"],place:["An meinem Küchentisch","Im Kontaktformular der Bibliothek","Am Schreibtisch in der Bibliothek"],minutes:[5,2,10],fallback:["In der Bibliothek nach Computerzugang fragen","Jemanden zu Hause um die Laptopzeit bitten","Pausieren, bis eine machbare Gelegenheit abgesprochen ist"],observation:["Die Bitte um Zugang und eine mögliche Antwort","Ob wir die Laptopzeit tatsächlich abgesprochen haben","Ob ich den gewählten Lebenslaufsatz überarbeitet habe"]},suggested:{action:"Tochter um Laptopzeit vor dem Abendessen bitten",minimum:"Tochter um zehn Minuten am Laptop bitten",minutes:5,cueHint:"Wenn wir die Hausaufgaben zu Hause besprechen",placeHint:"An meinem Küchentisch",obstacleHint:"Meine Tochter kann mir keine Laptopzeit anbieten",fallbackHint:"In der Bibliothek nach Computerzugang fragen",observationHint:"Die Bitte um Zugang und eine mögliche Antwort",kind:"support"},accessibleAlternative:"Tippe, sprich oder nutze Hilfe. Wähle „Diesen Schritt anpassen“ für die Aufgabe, sobald der Zugang abgesprochen ist.",stopRule:"Wenn die Übung dich überfordert oder die Umgebung unsicher ist, pausiere und suche passende Unterstützung."},result:{question:"Hast du dein gewähltes Minimum erledigt?",observationPrompt:"Was hast du tatsächlich getan oder erarbeitet?"},judgment:{primary:{id:"manifest-3-decision",scenario:"Daniels abendliche Lebenslaufarbeit kollidiert mit Hausaufgaben am gemeinsamen Laptop. Zehn Minuten vor dem Abendessen wären frei, wenn beide sich darauf einigen.",question:"Welche Reaktion passt zu diesem Hindernis?",options:[{id:"manifest-3-arrange-opening",text:"Die freien zehn Minuten gemeinsam absprechen und dann einen Satz im selben Entwurf verbessern.",feedback:"Das ändert die Bedingung, die die Aufgabe blockiert hat, und behält ein sinnvolles Minimum bei. Eine Absprache ist noch nötig. Halte die Bitte getrennt fest, solange die Gelegenheit nicht bestätigt ist."},{id:"manifest-3-keep-evening",text:"Beim Abendtermin bleiben und länger im Kopf üben, damit er bereit ist, sobald der Laptop frei wird.",feedback:"Eine Probe kann den Wortlaut vorbereiten. Der Konflikt um den Zugang bleibt aber bestehen. Daniel hat eine mögliche andere Gelegenheit. Sprich sie erst ab, bevor du eine weitere Vorbereitung einbaust."},{id:"manifest-3-wait-week",text:"Warten, bis die Hausaufgaben nächste Woche weniger Zeit brauchen, und dann wie ursprünglich geplant länger am Lebenslauf arbeiten.",feedback:"Warten kann passen, wenn keine machbare Gelegenheit besteht. Hier lässt sich womöglich jetzt eine kleinere vereinbaren. Probiere das aus, statt die gesamte Arbeit automatisch auf später zu verschieben."}],bestOptionId:"manifest-3-arrange-opening"}},carry:{takeaway:"Benenne die blockierende Bedingung. Ändere die Aufgabe oder bitte um die Hilfe, die sie braucht.",followUp:{questionId:"manifest-3-return",question:"Hast du um Zugang gebeten oder an der Aufgabe gearbeitet? Welche Absprache steht noch aus?",observationPrompt:"Was ist bei deiner geplanten Gelegenheit passiert?",adjustmentPrompt:"Welche einzelne Änderung passt zu deiner nächsten Gelegenheit?"}},goDeeper:{sections:[{heading:"Ein Hindernis liefert Informationen und muss nicht wehtun",paragraphs:["Die Übersichtsarbeit von 2021 zu mentalem Kontrastieren mit Planung fand über 24 unabhängige Effekte hinweg einen kleinen durchschnittlichen Vorteil bei der Zielerreichung. Deutliche Unterschiede und Hinweise auf Publikationsverzerrung begrenzen die Sicherheit. Unbehagen wurde nicht als wirksamer Bestandteil isoliert. Eine Schwierigkeit zu benennen kann unangenehm sein. Die Aufgabe besteht aber nicht darin, Belastung absichtlich zu verstärken. [M01]","In dem geprüften Verfahren von Oettingen und Kollegen aus 2015 beschrieben Studierende ein gewünschtes Ergebnis und ihr wichtigstes Hindernis ausführlich. Sie wählten eine Reaktion, verbanden Hindernis und Handlung in einem Plan und ergänzten die übliche Zeit und den Ort. In Studie 1 fiel der vorab geplante Vergleich bei im Kalender eingeplanten Stunden zugunsten der Methode aus. Gemessen wurde eingeplante Zeit, keine erledigte Arbeit. Der Gesamttest über die Bedingungen war nicht eindeutig. [M11] ODA ergänzt eine Prüfung praktischer Machbarkeit und einen tatsächlichen Versuch. Weder diese kürzere Übung noch ihre Trennung von äußeren Bedingungen und persönlichen Reaktionen wurde in dem Experiment eigens validiert."]},{heading:"Wann Unterstützung die passende Reaktion ist",paragraphs:["Trenne dein gewünschtes Ergebnis von den Bedingungen, die du dafür brauchst. Fehlt ein Hilfsmittel, brauchst du Zugang. Ist die Situation unsicher, brauchst du Schutz. Kollidiert die Aufgabe mit Sorgearbeit, brauchst du vielleicht eine andere Gelegenheit. Das ist eine Kursentscheidung, die sich an der Planungsforschung orientiert. Sie ist keine feste Einteilung, die jedes Hindernis genau einer Schublade zuweist. Eine Bitte um Unterstützung wird konkret, wenn du die benötigte Hilfe und die passende Gelegenheit benennst. [M01, M11]","Wenn jemand noch nicht geantwortet hat, halte die Bitte und die fehlende Antwort fest. Trage keine erhaltene Hilfe oder erledigte Arbeit ein. Du kannst einen anderen machbaren Schritt wählen, das Ziel ändern oder pausieren. Suche bei anhaltender Belastung oder erheblicher Beeinträchtigung fachliche Unterstützung, statt die Übung zu verstärken. Die NIMH-Orientierung zeigt Wege zu Behandlung und Krisenhilfe. Sie belegt nicht, dass ODA eine Erkrankung behandelt. [M14] Beschreibe im nächsten Eintrag die gewählte Handlung, auch Schutz oder Unterstützung. Mach aus dem ursprünglichen Hindernis keinen Mangel an Glauben."]}],sourceIds:["M01","M11","M14"]}},{schemaVersion:2,revision:2,id:"manifest-4",courseId:"manifest",locale:"de",title:"Warte nicht länger auf die richtige Stimmung",goal:"Nutze ein erkennbares Startsignal und eine kleine Reaktion auf die beobachtete schwierige Stelle.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"„Wenn ich mich bereit fühle“ verschiebt sich. Wähle einen Moment, den du bemerkst.",reason:{id:"manifest-4-reason",label:"Was hat Aufschieben dich gekostet, als das Startsignal zuletzt kam?",kind:"text",maxLength:160,optional:!0,suggestions:["Beispiele verglichen; nicht zum Schreiben gekommen","Auf Bereitschaft gewartet; Entwurf blieb unverändert","Sorgearbeit war nötig; keine sichere Gelegenheit","Noch kein Startsignal; Wortwahl könnte mich aufhalten"],help:"Noch kein Versuch? Benenne ein mögliches Zögern."},why:{id:"manifest-4-purpose",label:"Was würde dir dieser Schritt in deiner Woche ermöglichen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Ein Startsignal und eine Reaktion auf ein Hindernis erfüllen verschiedene Aufgaben. „Wenn die Teller abgeräumt sind, schreibe ich einen Lebenslaufsatz“ schafft eine Gelegenheit. „Wenn ich hängen bleibe, beschreibe ich eine Schichtänderung“ hilft dir während dieser Gelegenheit weiter.","Studien mit unterschiedlichen Zielen fanden, dass konkrete Wenn-dann-Pläne im Durchschnitt beim Dranbleiben halfen. Erinnern, Anstrengung und praktische Hindernisse verschwinden dadurch nicht vollständig. Behalte deine Aufgabe bei. Reagiere auf ein Hindernis aus deinen Notizen, falls es eines gibt. Wähle ein erkennbares Signal und eine Reaktion, die du dort umsetzen kannst. Bleibt das Signal aus, halte die fehlende Gelegenheit fest und suche eine andere."],example:{title:"Daniel nutzt das Startsignal",text:"Daniel legt einen Zettel neben den gemeinsamen Laptop: „Wenn die Teller abgeräumt sind, verbessere einen Satz. Wenn du hängen bleibst, beschreibe eine Schichtänderung.“ Am Donnerstag kommt das Signal. Er bemerkt den Zettel und schreibt einen brauchbaren Satz. Den Abschnitt schafft er vor den nächsten Familienaufgaben nicht. Seine Notizen halten beide Tatsachen fest."}},move:{invitation:"Behalte deine Aufgabe und Gelegenheit bei. Die Vorschläge zeigen Daniels Lebenslaufbeispiel.",instructions:["Behalte Handlung, Minimum, Startsignal und Ort bei, sofern keines davon geändert werden muss.","Benenne vor dem Speichern die kleinere Reaktion auf deine tatsächliche schwierige Stelle."],prompts:[],suggestions:{action:["Nach dem Abendessen einen Satz zur Schichtplanung schreiben","Nach dem Mittagessen die Lebenslauffrage abschicken","Nach dem Tee ein Datum im Lebenslauf berichtigen"],minimum:["Einen Lebenslaufsatz zur Schichtplanung speichern","Die Frage zur fehlenden Lebenslaufangabe abschicken","Ein berichtigtes Datum im Lebenslauf speichern"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1},{label:"In zwei Tagen",daysFromToday:2}],cue:["Wenn die Teller abgeräumt sind","Wenn die Mittagspause zu Ende ist","Wenn ich meinen Tee abstelle"],place:["An meinem Küchentisch","Im Dokument mit meinem Lebenslauf","Am Schreibtisch in der Bibliothek"],minutes:[5,2,10],fallback:["Eine Schichtänderung in einem Satz beschreiben","Eine andere freie Gelegenheit auswählen und benennen","In der Bibliothek nach Computerzugang fragen"],observation:["Ob das Startsignal kam und ich es bemerkte","Ob ich die Schichtänderung beschrieben habe","Die Lebenslaufänderung, die ich tatsächlich gespeichert habe"]},suggested:{action:"Nach dem Abendessen einen Satz zur Schichtplanung schreiben",minimum:"Einen Lebenslaufsatz zur Schichtplanung speichern",minutes:5,cueHint:"Wenn die Teller abgeräumt sind",placeHint:"An meinem Küchentisch",obstacleHint:"Ich bemerke das Startsignal, stocke aber beim Formulieren",fallbackHint:"Eine Schichtänderung in einem Satz beschreiben",observationHint:"Ob das Startsignal kam und ich es bemerkte"},accessibleAlternative:"Tippe, diktiere oder nutze deine gewohnten Hilfsmittel. Bitte bei Bedarf um praktische Hilfe.",stopRule:"Betreuungspflichten und Sicherheit gehen vor. Nutze eine andere Gelegenheit, wenn dieses Signal nicht mehr passt."},result:{question:"Hast du dein gewähltes Minimum erledigt?",observationPrompt:"Was hast du tatsächlich getan oder erarbeitet?"},judgment:{primary:{id:"manifest-4-decision",scenario:"Daniel hat nach dem Abräumen fünf Minuten. Sein Entwurf und ein zutreffendes Beispiel einer Schichtänderung liegen bereit. Er stockt aber beim Formulieren.",question:"Welcher Plan hilft beim Anfangen und beim Stocken?",options:[{id:"manifest-4-mood-cue",text:"Wenn er nach dem Abendessen klarer denken kann, fünf Minuten am Lebenslaufabschnitt mit seinen besten Beispielen arbeiten.",feedback:"Ein klarerer Kopf wäre schön, ist aber ein wechselndes Startsignal. Nutze das erkennbare Ereignis nach dem Abendessen und eine Reaktion, die in die verfügbaren fünf Minuten passt."},{id:"manifest-4-full-section",text:"Nach dem Abräumen drei Beispiele für Schichtplanung vergleichen und erst dann das beste für den Lebenslaufsatz auswählen.",feedback:"Vergleichen kann bei der Auswahl helfen. Daniel hat aber bereits ein zutreffendes Beispiel. Die Suche würde seine fünf Minuten verbrauchen. Beschreibe zuerst diese Schichtänderung. Prüfe den Wortlaut, sobald ein echter Satz da ist."},{id:"manifest-4-cue-and-response",text:"Nach dem Abräumen einen Satz verbessern. Wenn er beim Formulieren stockt, eine tatsächliche Schichtänderung in einfachen Worten beschreiben.",feedback:"So haben der Start und die schwierige Stelle je eine passende Reaktion. Daniel kann es mit seinem fertigen Entwurf versuchen. Der Plan hilft bei einer Handlung, verspricht aber weder müheloses Erinnern noch einen fertigen Abschnitt."}],bestOptionId:"manifest-4-cue-and-response"}},carry:{takeaway:"Schaff eine Gelegenheit zum Anfangen und eine Antwort aufs Stocken. Prüfe dann, was wirklich passiert ist.",followUp:{questionId:"manifest-4-return",question:"Hast du das Startsignal bemerkt, und konntest du deine geplante Reaktion nutzen?",observationPrompt:"Was ist bei deiner geplanten Gelegenheit passiert?",adjustmentPrompt:"Welche einzelne Änderung passt zu deiner nächsten Gelegenheit?"}},goDeeper:{sections:[{heading:"Wobei konkrete Planung helfen kann",paragraphs:["Gollwitzer und Sheerans Kapitel von 2006 fasste 94 unabhängige Tests mit 8.461 Teilnehmenden zusammen. Wenn-dann-Pläne zeigten im Durchschnitt einen Effekt auf die Zielerreichung von d = 0,65, mit einem 95%-Konfidenzintervall von 0,60 bis 0,70. Aufgaben und Verfahren waren unterschiedlich. Diese älteren Studien waren nicht durchgängig vorab registriert. Sie belegen nicht, dass jeder selbst geschriebene Satz wirkt. [M02]","Im Experiment zur Gelegenheitsplanung wählten Studierende eine konkrete Zeit und einen Ort, um mit einem Bericht anzufangen. Der Vergleich zur rechtzeitigen Bearbeitung betraf eindeutig zuordenbare Rücksendende, nicht alle Personen mit dieser Aufgabe. [M10] Daraus folgt weniger als „Ein Plan ersetzt Willenskraft“. Leg vorher fest, wie du reagieren willst. Prüfe dann, ob die Situation eintrat, du sie bemerkt hast und die Reaktion passte. Behalte äußere Erinnerungen, wenn du sie brauchst. Ein Zettel neben einem Hilfsmittel ist eine ODA-Option. Dass du damit das Signal sicher bemerkst, ist wissenschaftlich nicht belegt."]},{heading:"Zwei Aufgaben, ein fortlaufender Versuch",paragraphs:["Deine geplante Gelegenheit beantwortet, wann du die Aufgabe angehst. Deine Reaktion auf ein Hindernis beantwortet, was du bei einer beobachteten Schwierigkeit tust. Das geprüfte Verfahren zum mentalen Kontrastieren verband ein Hindernis mit einer Reaktion und ergänzte die übliche Zeit und den Ort. Es belegte nicht, dass jeder zwei getrennte Regeln braucht. [M11] Dieser Kurs unterscheidet ihre Aufgaben, damit du besser erkennen kannst, wo dein bisheriger Versuch stockt.","Angenommen, die geplante Gelegenheit entsteht gar nicht. Dann kannst du nicht sagen, dass deine Reaktion auf das Hindernis gescheitert ist. Kommt die Gelegenheit und du verpasst sie, ändere Signal oder Erinnerung. Bemerkst du sie, aber die Reaktion ist zu groß, verkleinere den nächsten sinnvollen Aufgabenteil. Das sind Möglichkeiten zum Ausprobieren. Ein privates Protokoll beweist sie nicht. Lass frühere Einträge mit ihrem ursprünglichen Minimum verbunden. Ein anderer nächster Plan macht einen unvollständigen alten Versuch nicht nachträglich fertig. Prüfe deine tatsächliche Handlung. Unterstützung, Erholung, Pausieren und ein anderes Ziel bleiben mögliche Entscheidungen."]}],sourceIds:["M02","M10","M11"]}},{schemaVersion:2,revision:2,id:"manifest-5",courseId:"manifest",locale:"de",title:"Noch kein Ergebnis? Schau auf deine tatsächlichen Versuche",goal:"Nutze deine bisherigen Einträge, um einen machbaren nächsten Schritt und den Rückblick für nächste Woche zu wählen.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"Bevor du den Traum aufgibst: Hast du den Weg ausprobiert oder bisher immer nur geplant?",reason:{id:"manifest-5-reason",label:"Was würde dich überzeugen, diesen Weg beizubehalten, zu ändern oder aufzugeben?",kind:"text",maxLength:160,optional:!0,suggestions:["Brauchbarer Entwurf; Bewerbung abschicken","Wiederholte Terminkonflikte; andere Gelegenheit wählen","Konkrete Rückmeldung; den unklaren Satz überarbeiten","Noch kein Versuch; ersten Test auswählen"]},why:{id:"manifest-5-purpose",label:"Was würde dir dieser Schritt in deiner Woche ermöglichen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Lies die Einträge zu demselben Ziel. Trenne, was du geplant, im Kopf geübt, tatsächlich getan und von anderen erhalten hast. Ein gespeicherter Entwurf belegt Arbeit am Entwurf. Er belegt weder eine abgeschickte Bewerbung noch das Interesse eines Arbeitgebers.","Eine Übersichtsarbeit über 138 Experimente fand im Durchschnitt Vorteile, wenn Fortschritte häufiger beobachtet wurden. Dieses genaue Protokoll und ein idealer Rhythmus für Rückblicke wurden nicht geprüft. Wähle anhand deiner Tatsachen: einen machbaren Schritt wiederholen, ein Problem ändern, Rückmeldung suchen oder ein ungeeignetes Ziel aufgeben. Gibt es keinen Versuch, benenne diese Lücke und erarbeite deinen ersten brauchbaren Teil."],example:{title:"Daniel plant die nächste Woche",text:"Daniel liest drei datierte Änderungen und eine ungenutzte Gelegenheit am Laptop. Sein Lebenslauf ist klarer, aber er hat noch keine Bewerbung abgeschickt. Er wählt eine passende Stelle, prüft ihre Anforderungen und schickt am Freitag die vorbereitete Fassung ab. Er notiert den Versand und plant einen Rückblick nächste Woche. Noch keine Antwort."}},move:{invitation:"Behalte, was passt. Benenne die nächste Handlung. Beispiel: eine fertige Bewerbung abschicken.",instructions:["Beim Wiederholen: Behalte Minimum und Termin bei. Ändere nur den beobachteten Engpass.","Ohne Eintrag: Benenne vor dem Speichern eine erste Handlung und das passende Minimum.","Nach Informationen zu fragen zählt als Fragen, nicht als Erledigen der blockierten Aufgabe."],prompts:[],suggestions:{action:["Die fertige Bewerbung für die gewählte Stelle abschicken","Kontaktperson nach einer unklaren Anforderung fragen","Einen Lebenslaufsatz anhand einer Rückmeldung überarbeiten"],minimum:["Die fertige Bewerbung einmal abschicken","Die Frage zur Bewerbungsanforderung abschicken","Den überarbeiteten Lebenslaufsatz speichern"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1},{label:"In zwei Tagen",daysFromToday:2}],cue:["Wenn die Mittagspause zu Ende ist","Wenn das Abendessen abgeräumt ist","Wenn ich die Bewerbungsseite der Stelle öffne"],place:["An meinem Küchentisch","Am Schreibtisch in der Bibliothek","Im Bewerbungsformular für diese Stelle"],minutes:[10,2,5],fallback:["Die Kontaktperson nach der unklaren Anforderung fragen","Um Rückmeldung zum unklaren Satz bitten","Pausieren, bis die nötige Information vorliegt"],observation:["Den Versand und eine Bestätigung, falls vorhanden","Die Informationsfrage und eine noch ausstehende Antwort","Was weiterhin außerhalb meiner Kontrolle liegt"]},suggested:{action:"Die fertige Bewerbung für die gewählte Stelle abschicken",minimum:"Die fertige Bewerbung einmal abschicken",minutes:10,cueHint:"Wenn die Mittagspause zu Ende ist",placeHint:"An meinem Küchentisch",obstacleHint:"Eine nötige Angabe für die Bewerbung ist unklar",fallbackHint:"Die Kontaktperson nach der unklaren Anforderung fragen",observationHint:"Den Versand und eine Bestätigung, falls vorhanden"},accessibleAlternative:"Tippe, diktiere oder nutze deine gewohnten Hilfsmittel. Bitte bei Bedarf um praktische Hilfe.",stopRule:"Gib nicht mehr Geld aus und verzichte nicht auf nötige Versorgung, um ein unsicheres Ergebnis zu erzwingen."},result:{question:"Hast du dein gewähltes Minimum erledigt?",observationPrompt:"Was hast du tatsächlich getan oder erarbeitet?"},judgment:{primary:{id:"manifest-5-decision",scenario:"Daniel hat seinen Lebenslauf überarbeitet, aber sich noch nicht beworben. Die Bewerbungsfrist für eine passende Stelle endet heute Abend. Sein Entwurf erfüllt die Anforderungen. Morgen könnte jemand die Fassungen vergleichen.",question:"Wozu sollte sein Rückblick ihn führen?",options:[{id:"manifest-5-next-application",text:"Die fertige Bewerbung abschicken, den Versand festhalten und später zurückblicken, während die Antwort noch offen ist.",feedback:"Die Einträge zeigen einen konkreten nächsten Schritt, der bereitliegt und den Daniel selbst umsetzen kann. Die Handlung ist das Abschicken. Die Entscheidung des Arbeitgebers bleibt unbekannt, bis eine tatsächliche Rückmeldung kommt."},{id:"manifest-5-double-editing",text:"Vor dem Abschicken jemanden um einen Vergleich zweier Lebenslauffassungen bitten, damit schwache Formulierungen möglichst auffallen.",feedback:"Ein Vergleich könnte Qualitätsprobleme zeigen, kommt aber nach der heutigen Frist. Daniel hat die Anforderungen geprüft und kennt keine verbleibende Lücke. Schick diese passende Fassung ab. Nutze spätere Rückmeldung für eine konkrete Änderung."},{id:"manifest-5-change-direction",text:"Die Gelegenheit für mehrere weniger gezielte Bewerbungen nutzen. So die Reichweite erhöhen und erst später die Lebenslauffassung auswählen.",feedback:"Mehr Reichweite kann Chancen eröffnen. Hier ist eine passende Bewerbung schon fertig. Sie abzuschicken prüft diese konkrete Passung. Mehr Bewerbungen können später folgen, ohne diesen vorbereiteten, gezielten Versand zu ersetzen."}],bestOptionId:"manifest-5-next-application"}},carry:{takeaway:"Lass deine Einträge den nächsten Schritt verändern. Einsatz, Vorbereitung und äußere Ergebnisse sagen Unterschiedliches aus.",followUp:{questionId:"manifest-5-return",question:"Was ist mit deiner Aufgabe oder Informationsfrage passiert, und was steht weiterhin aus?",observationPrompt:"Was ist bei deiner geplanten Gelegenheit passiert?",adjustmentPrompt:"Welche einzelne Änderung passt zu deiner nächsten Gelegenheit?"}},goDeeper:{sections:[{heading:"Fortschritte festhalten hilft bei einer Entscheidung",paragraphs:["Harkin und Kollegen untersuchten 2016 in ihrer Übersichtsarbeit 138 Experimente mit zufälliger Zuteilung und insgesamt 19.951 Teilnehmenden. Die Analyse zur Zielerreichung umfasste 18.398 Personen. Sie ergab d = 0,40, mit einem 95%-Konfidenzintervall von 0,32 bis 0,48. Eine Zusatzanalyse zu Verzerrungen durch kleine Studien lieferte eine niedrigere Schätzung. Interventionen, Ziele und Aufzeichnungsweisen unterschieden sich. Die Übersichtsarbeit prüfte weder ODAs Zusammenfassung noch die Karte für den nächsten Tag. [M03]","Über die Studien hinweg gingen schriftlich oder öffentlich berichtete Fortschritte mit größeren Effekten einher. Diese Vergleiche von Studienmerkmalen belegen weder, dass öffentliches Teilen nötig ist, noch dass ein bestimmtes App-Format den Nutzen verursacht. Behalte persönliche Angaben für dich, wenn das zu deiner Situation passt. Vergleiche anhand deiner Einträge, was der Plan verlangte und was du tatsächlich berichtet hast. Ohne Eintrag bleibt das Geschehen unbekannt. Erledigte Vorbereitung, eine unbeantwortete Bitte oder ein gestoppter Versuch behalten jeweils ihre eigene Bezeichnung. So lässt sich deine nächste Entscheidung prüfen, ohne dass du eine positive Geschichte liefern musst."]},{heading:"Plane die nächste Woche, ohne die vorige umzuschreiben",paragraphs:["Ein kurzes privates Protokoll kann ein Muster nahelegen. Es beweist aber nicht, warum ein äußeres Ergebnis eingetreten ist. Bewerbungen, Bestellungen und Antworten anderer können von Qualität, Zeitpunkt, Mitteln oder Umständen abhängen, die dein Protokoll nicht erfasst. Forschung zum Beobachten von Fortschritten stützt die Nutzung von Informationen. Sie legt keine allgemeingültige Anzahl von Versuchen fest, bevor du ein Ziel ändern solltest. [M03] Lass diese Unsicherheit beim Rückblick sichtbar.","Wähle eine machbare nächste Gelegenheit und einen Rückblicktermin für die kommende Woche. Behalte dein brauchbares Minimum und das, was dir Zugang zur Aufgabe verschafft hat. Ändere den Teil, den deine Einträge tatsächlich infrage stellen. Ist kein Versuch erfasst, berichte bekannte Tatsachen oder behandle die nächste kleine Handlung als deinen ersten Versuch. Erfinde keine geleistete Arbeit. Planungsstudien fanden im Durchschnitt Vorteile, aber die Ergebnisse unterschieden sich. Sie garantieren keinen Erfolg. [M01] Pausieren, Rückmeldung erbitten, praktische Unterstützung suchen oder eine andere Richtung wählen kann eine bewusste Entscheidung aus dem Rückblick sein. Behalte den früheren Eintrag, damit der Grund sichtbar bleibt."]}],sourceIds:["M03","M01"]}}],l={lang:"de",id:"manifest",title:"Dein Traum wartet? Fang konkret an",subtitle:"Fünf Grundlagenlektionen, danach 15 beliebte Techniken: ehrlich eingeordnete Forschung und jeweils eine Handlung für heute.",description:"Mach aus einem selbst gewählten Wunsch brauchbare Arbeit. Führe deinen Versuch in der Technikbibliothek weiter: lerne die Rituale kennen, prüfe die Forschung und probiere einen machbaren Schritt aus.",scope:"Manifestieren bedeutet hier: Absicht, Vorbereitung und Handlung. Der Kurs behauptet nicht, dass Gedanken Ereignisse durch Quanteneffekte steuern, das Universum deine Wünsche liefert oder jeder Wunsch sicher wahr wird. Er bietet keine finanzielle, medizinische oder psychologische Beratung.",outcome:"Ein bedeutsames Ziel mit einem brauchbaren Minimum, ehrlichen Einträgen zu Versuchen und einem machbaren Plan für nächste Woche.",lessonLibrary:{id:"manifest-technique-library",title:"Technikbibliothek",description:"15 bekannte Rituale: ihre Schritte, was die Forschung stützt und eine ODA-Version mit Handeln und Rückblick.",lessonIds:r.map(e=>e.id),sourceIds:s.map(e=>e.id)},photo:{id:"1676782778930-11b311ec5134",alt:"Ein Feldweg führt über einen grünen Hügel zu fernen Bergen"},lessons:[{id:"manifest-1",v2:i[0],photo:{id:"1768055104910-8c8d213835fb",alt:"Eine Hand schreibt eine Aufgabenliste in ein Notizbuch"},schemaVersion:2,title:"Dein Traum wartet? Mach heute etwas Brauchbares",minutes:6,goal:"Erarbeite einen brauchbaren Teil für ein Ziel, das du selbst wählst.",reading:["Ein besserer Job ist ein Ergebnis. Einen Satz im Lebenslauf zu verbessern ist eine Handlung. Ob jemand dich anruft, entscheiden weiterhin andere. Mach etwas, das sich lohnt. Miss deinen Einsatz nicht an der erhofften Antwort.","In einem Experiment mit Studierenden half ein festgelegter Start mit Zeit und Ort, einen Bericht rechtzeitig zu schreiben. Das galt für jene, die ihn zurückschickten. Die Mitarbeit insgesamt nahm nicht zu. Ein Plan kann beim Anfangen helfen, garantiert aber kein Ergebnis. Erarbeite heute einen brauchbaren Satz, eine Antwort oder eine Bitte. Bleib im Kurs bei diesem Ziel und komm mit dem zurück, was passiert ist."],practice:["Formuliere einen Wunsch, der dir wichtig ist, in einem Satz. Schreiben bleibt freiwillig.","Wähle eine Handlung, die du selbst steuern kannst und die dich diesem Wunsch näherbringt.","Lege fest, wann der kleine Schritt erledigt ist, etwa nach „drei Sätzen eines Entwurfs“."],reflection:"Wie sieht dein Wunsch heute als konkrete Handlung aus?",question:"Welche dieser Handlungen kannst du direkt selbst wählen?",options:["Der Arbeitgeber entscheidet sich auf jeden Fall für mich.","Morgen drei Sätze in meinem Lebenslauf überarbeiten.","Es geht überhaupt nichts schief."],correct:1,feedback:"Die Entscheidungen anderer kannst du nicht garantieren. Deine eigene Vorbereitung kannst du konkret machen.",takeaway:"Mach aus dem Wunsch eine Handlung. Halte sie getrennt von der erhofften Antwort fest.",sources:["M10","M01","M07"],deeper:[{heading:"Wobei ein Plan zum Anfangen helfen kann",paragraphs:["In ihrer Studie 2 von 1997 ließen Gollwitzer und Brandstätter 86 Münchner Studierende einen Bericht über Weihnachten schreiben. Die Planungsgruppe wählte eine genaue Zeit und einen Ort, stellte sich diese Gelegenheit vor, nahm sich vor, dort anzufangen, und hielt die Entscheidungen fest. Von 36 eindeutig zuordenbaren Rücksendenden schrieben 12 von 17 mit Plan und sechs von 19 in der Kontrollgruppe innerhalb der geforderten zwei Tage. Diese Anteile betreffen die Rücksendenden, nicht alle aufgenommenen Personen. Planung erhöhte die Mitarbeit insgesamt nicht. [M10]","Diese Lektion übernimmt die konkrete Gelegenheit und verbindet sie mit brauchbarer Arbeit. Diese Übertragung auf andere Aufgaben wurde in der Weihnachtsbericht-Studie nicht geprüft. Ein Datum allein sagt dir noch nicht, woher die Zeit kommen soll. Wähle ein Ereignis, das du erkennst, und einen Ort, den du erreichen kannst. Fehlen nötige Mittel, kann es der passende Schritt sein, danach zu fragen. Halte diese Bitte als Bitte fest, auch wenn die Hilfe noch nicht da ist."]},{heading:"Dein Wunsch steuert keine anderen Menschen",paragraphs:["Wang und Kollegen fassten 2021 in einer Übersichtsarbeit 24 unabhängige Effekte aus 21 Artikeln mit 15.907 Teilnehmenden zusammen. Ein gewünschtes Ergebnis mit einem Hindernis und einer Wenn-dann-Reaktion zu verbinden, brachte im Durchschnitt einen kleinen Vorteil bei der Zielerreichung: g = 0,336, mit einem 95%-Konfidenzintervall von 0,229 bis 0,443. Die Ergebnisse unterschieden sich deutlich. Eine Korrektur möglicher Publikationsverzerrung senkte die Schätzung. Das stützt Planung innerhalb ihrer Grenzen, aber kein Erfolgsversprechen für diesen Kurs. [M01]","Dixon und Kollegen untersuchten Manifestationsglauben in drei US-Onlinebefragungen mit insgesamt 1.023 Teilnehmenden. Er hing mit einigen selbst berichteten finanziellen Risiken und Insolvenzen zusammen, nicht mit selbst berichtetem Einkommen oder Bildungsstand. Diese Zusammenhänge belegen nicht, dass der Glaube Insolvenzen verursacht hat. Sie prüfen auch nicht jede Manifestationsübung objektiv. [M07] Nutze deinen Wunsch, um eine Aufgabe zu wählen und Grenzen zu prüfen. Schließe daraus nicht, dass Gedanken eine Gelegenheit angezogen oder Not verursacht haben. Du hast dir ein Ergebnis auch nicht durch Gedanken verdient. Geld, Sorgearbeit, Zugang und die Entscheidungen anderer bleiben relevant."]}],example:{title:"Daniel fängt an",text:"Nach dem Abendessen setzt Daniel sich für zehn Minuten an den Küchentisch. Er sucht einen Logistikjob. Im Lebenslauf beschreibt er neu, wie er acht Lagerschichten geplant hat. Der Satz klingt noch holprig. Trotzdem speichert er ihn und notiert die Änderung. Ein Arbeitgeber hat ihn noch nicht gesehen. Morgen kann Daniel einen echten Entwurf verbessern."}},{id:"manifest-2",v2:i[1],photo:{id:"1517363898874-737b62a7db91",alt:"Eine Person sitzt ruhig am Fenster im warmen Licht"},schemaVersion:2,title:"Wieder nur geübt? Bring den Satz aufs Papier",minutes:6,goal:"Übe eine schwierige Stelle im Kopf. Erarbeite dann den nächsten brauchbaren Teil deiner bisherigen Aufgabe.",reading:["Hol deine Aufgabe und vorhandene Notizen hervor. Im Kopf zu üben bedeutet, eine bestimmte Handlung gedanklich auszuführen, etwa den ersten Satz zu sagen. Schritte aufzulisten ist eine andere Art der Vorbereitung. Beides ist noch kein tatsächlicher Versuch.","Eine Übersichtsarbeit fand im Durchschnitt Vorteile für das Verhalten durch gedankliches Durchspielen. Eine beste Form war nicht belegt. Das beweist nicht, dass diese kurze Probe wirkt. Nutze sie, um deine schwierige Stelle und eine mögliche Reaktion zu erkennen. Beschreibe die Handlung in Worten, wenn keine Bilder kommen. Schreibe danach den nächsten brauchbaren Satz für dieselbe Aufgabe."],practice:["Benenne eine Veränderung, die dein Ziel in deinem Leben bewirken soll.","Ordne deine ersten beiden Schritte als Bilder oder in Worten.","Erledige nach der Probe tatsächlich einen Schritt der Vorbereitung."],reflection:"Welche fehlende Vorbereitung ist dir beim Üben aufgefallen?",question:"Was bedeutet es in diesem Kurs, im Kopf zu üben?",options:["Eine Übung, die mich auf eine tatsächliche Handlung vorbereitet.","Mit Gedanken äußere Ereignisse sicher steuern.","Gar nichts mehr ausprobieren müssen."],correct:0,feedback:"Im Kopf zu üben ist Vorbereitung. Die genannten Studien validieren diese kurze Übung nicht und zeigen nicht, dass sie äußere Ergebnisse steuert. Nutze Vorbereitung für eine tatsächliche Handlung.",takeaway:"Lass auf hilfreiche Vorbereitung eine echte Handlung folgen. Halte beides getrennt fest.",sources:["M04","M10"],deeper:[{heading:"Keine klare Rangfolge der Vorstellungsformen",paragraphs:["Cole und Kollegen fassten 2021 in einer Übersichtsarbeit 94 Studien, 123 Effekte und 5.685 Teilnehmende zusammen. Gedankliches Durchspielen zeigte insgesamt einen Verhaltenseffekt von g = 0,49, mit einem 95%-Konfidenzintervall von 0,37 bis 0,62. Meist waren die Teilnehmenden Studierende. Inhalt, Umfang und gemessene Ergebnisse der Übungen unterschieden sich. Der Durchschnitt sagt daher nicht voraus, was deine kurze Übung bewirkt. [M04]","Die Übersichtsarbeit unterschied zwischen dem Durchdenken von Ablaufschritten und dem gedanklichen Ausführen einer Aufgabe. Die Schätzung für reine Ablaufvorstellungen beruhte auf fünf Effekten; ihr Konfidenzintervall umfasste auch den Wert für keinen Effekt. Der Gesamtvergleich der Formen war statistisch nicht signifikant. Höhere Durchschnittswerte einzelner Gruppen belegen deshalb keinen verlässlichen Sieger. Eine Grafik ist kein Auftrag, intensiver zu visualisieren. Diese Lektion nutzt die Probe, um ein praktisches Detail sichtbar zu machen. Danach versuchst du die Aufgabe. Eine Beschreibung in Worten bietet einen zugänglichen Weg. Das bedeutet nicht, dass ihre Gleichwertigkeit mit Bildern wissenschaftlich belegt wäre."]},{heading:"Bereite eine Gelegenheit vor und nutze sie dann",paragraphs:["Im ursprünglichen Experiment zur Berichtsplanung stellten sich die Teilnehmenden eine konkrete Zeit und einen Ort zum Anfangen vor. Der Vergleich zur rechtzeitigen Bearbeitung betraf eindeutig zuordenbare Rücksendende und eine eng begrenzte Studienaufgabe. Daraus folgt weder ein allgemeines Vorstellungsskript noch ein Vorteil von Proben im Bett. [M10] Hier ist Vorbereitung dann sinnvoll, wenn sie dir beim nächsten Teil deiner bisherigen Aufgabe hilft.","Vielleicht bemerkst du ein fehlendes Passwort, eine unklare Anweisung oder einen Satz, den du noch nicht erklären kannst. Ein Passwort zurückzusetzen ist Vorbereitung. Benötigte Angaben abzusenden ist Arbeit an der Aufgabe. Zeig diesen Unterschied in deinen Notizen. Hör mit Planung vor dem Schlafen auf, wenn sie dich wach hält, und plane stattdessen tagsüber. Das ist eine praktische Anpassung für diesen Kurs. Die kurze Probe ist freiwillig. Sie ist weder ein validiertes Ritual noch eine Voraussetzung zum Anfangen. Du brauchst kein lebhaftes Bild und kein bestimmtes Gefühl."]}],example:{title:"Daniel vor der leeren Zeile",text:"Nach dem Abendessen öffnet Daniel seinen Lebenslauf wieder. Dreißig Sekunden lang übt er im Kopf, eine schwierige Schichtänderung zu beschreiben. Er erwartet, ins Stocken zu geraten, und probt: „Acht Schichten umgeplant, als …“ Dann tippt er einen brauchbaren Satz. Er streicht zwei Wörter und notiert eine Rückfrage. Wie viele Details nötig sind, hatte seine Probe nicht gezeigt."}},{id:"manifest-3",v2:i[2],photo:{id:"1767134063671-322e6faf9206",alt:"Ein umgestürzter Baum liegt quer über einem grünen Waldweg"},schemaVersion:2,title:"Das Hindernis ist echt. Ändere die Bedingungen",minutes:6,goal:"Nutze deinen letzten Versuch, um eine machbare Reaktion auf ein Hindernis zu wählen und auszuprobieren.",reading:["Nutze dein Ziel und vorhandene Notizen. Ohne Versuch: Benenne ein wahrscheinliches Hindernis. „Abends ist der gemeinsame Computer belegt“ hilft, eine Reaktion zu finden. „Mir fehlt Disziplin“ beschreibt die Bedingung nicht.","Studien, die ein gewünschtes Ergebnis mit einem echten Hindernis und einer Wenn-dann-Reaktion verbanden, fanden im Durchschnitt kleine Vorteile. Sie belegten nicht, dass Unbehagen die Wirkung erklärt. Geld, Sorgearbeit, Zeit und Zugang sind Bedingungen, keine Glaubensfehler. Probiere eine Änderung: eine kleinere Aufgabe, eine freie Gelegenheit oder eine konkrete Bitte um Hilfe. Eine Bitte zählt als Fragen, nicht als erhaltene Hilfe."],practice:["Benenne das nächste Hindernis, das deinem Ziel im Weg steht.","Trenne den beeinflussbaren Teil des Hindernisses von dem, für den du Unterstützung oder Zeit brauchst.","Geht es gerade nicht, verkleinere das Ziel oder verschiebe es auf eine passende Gelegenheit."],reflection:"Was hat sich in deinem Plan geändert, seit du das Hindernis realistischer betrachtest?",question:"Wenn äußere Bedingungen im Weg stehen …",options:["Sollte ich annehmen, dass ich nicht genug geglaubt habe.","Sollte ich diese Bedingungen ignorieren.","Kann ich Unterstützung, Zeitpunkt oder Größe des Ziels überdenken."],correct:2,feedback:"Ein realistischer Plan berücksichtigt äußere Bedingungen. Deine Gedanken entscheiden nicht allein über Ergebnisse.",takeaway:"Benenne die blockierende Bedingung. Ändere die Aufgabe oder bitte um die Hilfe, die sie braucht.",sources:["M01","M11","M14"],deeper:[{heading:"Ein Hindernis liefert Informationen und muss nicht wehtun",paragraphs:["Die Übersichtsarbeit von 2021 zu mentalem Kontrastieren mit Planung fand über 24 unabhängige Effekte hinweg einen kleinen durchschnittlichen Vorteil bei der Zielerreichung. Deutliche Unterschiede und Hinweise auf Publikationsverzerrung begrenzen die Sicherheit. Unbehagen wurde nicht als wirksamer Bestandteil isoliert. Eine Schwierigkeit zu benennen kann unangenehm sein. Die Aufgabe besteht aber nicht darin, Belastung absichtlich zu verstärken. [M01]","In dem geprüften Verfahren von Oettingen und Kollegen aus 2015 beschrieben Studierende ein gewünschtes Ergebnis und ihr wichtigstes Hindernis ausführlich. Sie wählten eine Reaktion, verbanden Hindernis und Handlung in einem Plan und ergänzten die übliche Zeit und den Ort. In Studie 1 fiel der vorab geplante Vergleich bei im Kalender eingeplanten Stunden zugunsten der Methode aus. Gemessen wurde eingeplante Zeit, keine erledigte Arbeit. Der Gesamttest über die Bedingungen war nicht eindeutig. [M11] ODA ergänzt eine Prüfung praktischer Machbarkeit und einen tatsächlichen Versuch. Weder diese kürzere Übung noch ihre Trennung von äußeren Bedingungen und persönlichen Reaktionen wurde in dem Experiment eigens validiert."]},{heading:"Wann Unterstützung die passende Reaktion ist",paragraphs:["Trenne dein gewünschtes Ergebnis von den Bedingungen, die du dafür brauchst. Fehlt ein Hilfsmittel, brauchst du Zugang. Ist die Situation unsicher, brauchst du Schutz. Kollidiert die Aufgabe mit Sorgearbeit, brauchst du vielleicht eine andere Gelegenheit. Das ist eine Kursentscheidung, die sich an der Planungsforschung orientiert. Sie ist keine feste Einteilung, die jedes Hindernis genau einer Schublade zuweist. Eine Bitte um Unterstützung wird konkret, wenn du die benötigte Hilfe und die passende Gelegenheit benennst. [M01, M11]","Wenn jemand noch nicht geantwortet hat, halte die Bitte und die fehlende Antwort fest. Trage keine erhaltene Hilfe oder erledigte Arbeit ein. Du kannst einen anderen machbaren Schritt wählen, das Ziel ändern oder pausieren. Suche bei anhaltender Belastung oder erheblicher Beeinträchtigung fachliche Unterstützung, statt die Übung zu verstärken. Die NIMH-Orientierung zeigt Wege zu Behandlung und Krisenhilfe. Sie belegt nicht, dass ODA eine Erkrankung behandelt. [M14] Beschreibe im nächsten Eintrag die gewählte Handlung, auch Schutz oder Unterstützung. Mach aus dem ursprünglichen Hindernis keinen Mangel an Glauben."]}],example:{title:"Daniel sucht eine andere Gelegenheit",text:"Daniel wollte nach dem Abendessen seinen Lebenslauf bearbeiten. Seine Tochter brauchte aber den gemeinsamen Laptop für Hausaufgaben. Er notiert den Konflikt. Er fragt, ob er ihn morgen zehn Minuten vor dem Abendessen nutzen kann. Sie einigen sich. Dann verbessert er einen Satz und hört auf. Die Bewerbung ist noch nicht fertig."}},{id:"manifest-4",v2:i[3],photo:{id:"1591462391971-9ffc57b382b9",alt:"Bunte Haftnotizen und Stifte"},schemaVersion:2,title:"Warte nicht länger auf die richtige Stimmung",minutes:6,goal:"Nutze ein erkennbares Startsignal und eine kleine Reaktion auf die beobachtete schwierige Stelle.",reading:["Ein Startsignal und eine Reaktion auf ein Hindernis erfüllen verschiedene Aufgaben. „Wenn die Teller abgeräumt sind, schreibe ich einen Lebenslaufsatz“ schafft eine Gelegenheit. „Wenn ich hängen bleibe, beschreibe ich eine Schichtänderung“ hilft dir während dieser Gelegenheit weiter.","Studien mit unterschiedlichen Zielen fanden, dass konkrete Wenn-dann-Pläne im Durchschnitt beim Dranbleiben halfen. Erinnern, Anstrengung und praktische Hindernisse verschwinden dadurch nicht vollständig. Behalte deine Aufgabe bei. Reagiere auf ein Hindernis aus deinen Notizen, falls es eines gibt. Wähle ein erkennbares Signal und eine Reaktion, die du dort umsetzen kannst. Bleibt das Signal aus, halte die fehlende Gelegenheit fest und suche eine andere."],practice:["Beschreibe ein erkennbares Hindernis mit „Wenn …“.","Schreibe nach „dann …“ eine einzige kleine Handlung auf.","Prüfe, ob der Plan zur verfügbaren Zeit und deinen Hilfsmitteln passt. Übe ihn dann einmal."],reflection:"Wie lautet dein Wenn-dann-Satz?",question:"Welchen Plan kannst du tatsächlich ausprobieren?",options:["Es wird sich alles von selbst regeln.","Wenn ich beim Öffnen der Datei stocke, schreibe ich zuerst den Titel.","Wenn ich gute Energie aussende, verschwinden alle Hindernisse."],correct:1,feedback:"Die zweite Antwort verbindet eine konkrete Situation mit einer beobachtbaren Handlung. Diese Art von Handlungsplanung ähnelt dem Vorgehen in den Studien.",takeaway:"Schaff eine Gelegenheit zum Anfangen und eine Antwort aufs Stocken. Prüfe dann, was wirklich passiert ist.",sources:["M02","M10","M11"],deeper:[{heading:"Wobei konkrete Planung helfen kann",paragraphs:["Gollwitzer und Sheerans Kapitel von 2006 fasste 94 unabhängige Tests mit 8.461 Teilnehmenden zusammen. Wenn-dann-Pläne zeigten im Durchschnitt einen Effekt auf die Zielerreichung von d = 0,65, mit einem 95%-Konfidenzintervall von 0,60 bis 0,70. Aufgaben und Verfahren waren unterschiedlich. Diese älteren Studien waren nicht durchgängig vorab registriert. Sie belegen nicht, dass jeder selbst geschriebene Satz wirkt. [M02]","Im Experiment zur Gelegenheitsplanung wählten Studierende eine konkrete Zeit und einen Ort, um mit einem Bericht anzufangen. Der Vergleich zur rechtzeitigen Bearbeitung betraf eindeutig zuordenbare Rücksendende, nicht alle Personen mit dieser Aufgabe. [M10] Daraus folgt weniger als „Ein Plan ersetzt Willenskraft“. Leg vorher fest, wie du reagieren willst. Prüfe dann, ob die Situation eintrat, du sie bemerkt hast und die Reaktion passte. Behalte äußere Erinnerungen, wenn du sie brauchst. Ein Zettel neben einem Hilfsmittel ist eine ODA-Option. Dass du damit das Signal sicher bemerkst, ist wissenschaftlich nicht belegt."]},{heading:"Zwei Aufgaben, ein fortlaufender Versuch",paragraphs:["Deine geplante Gelegenheit beantwortet, wann du die Aufgabe angehst. Deine Reaktion auf ein Hindernis beantwortet, was du bei einer beobachteten Schwierigkeit tust. Das geprüfte Verfahren zum mentalen Kontrastieren verband ein Hindernis mit einer Reaktion und ergänzte die übliche Zeit und den Ort. Es belegte nicht, dass jeder zwei getrennte Regeln braucht. [M11] Dieser Kurs unterscheidet ihre Aufgaben, damit du besser erkennen kannst, wo dein bisheriger Versuch stockt.","Angenommen, die geplante Gelegenheit entsteht gar nicht. Dann kannst du nicht sagen, dass deine Reaktion auf das Hindernis gescheitert ist. Kommt die Gelegenheit und du verpasst sie, ändere Signal oder Erinnerung. Bemerkst du sie, aber die Reaktion ist zu groß, verkleinere den nächsten sinnvollen Aufgabenteil. Das sind Möglichkeiten zum Ausprobieren. Ein privates Protokoll beweist sie nicht. Lass frühere Einträge mit ihrem ursprünglichen Minimum verbunden. Ein anderer nächster Plan macht einen unvollständigen alten Versuch nicht nachträglich fertig. Prüfe deine tatsächliche Handlung. Unterstützung, Erholung, Pausieren und ein anderes Ziel bleiben mögliche Entscheidungen."]}],example:{title:"Daniel nutzt das Startsignal",text:"Daniel legt einen Zettel neben den gemeinsamen Laptop: „Wenn die Teller abgeräumt sind, verbessere einen Satz. Wenn du hängen bleibst, beschreibe eine Schichtänderung.“ Am Donnerstag kommt das Signal. Er bemerkt den Zettel und schreibt einen brauchbaren Satz. Den Abschnitt schafft er vor den nächsten Familienaufgaben nicht. Seine Notizen halten beide Tatsachen fest."}},{id:"manifest-5",v2:i[4],photo:{id:"1762920738995-f393efe82205",alt:"Ein hölzerner Wegweiser zeigt im Wald in mehrere Richtungen"},schemaVersion:2,title:"Noch kein Ergebnis? Schau auf deine tatsächlichen Versuche",minutes:6,goal:"Nutze deine bisherigen Einträge, um einen machbaren nächsten Schritt und den Rückblick für nächste Woche zu wählen.",reading:["Lies die Einträge zu demselben Ziel. Trenne, was du geplant, im Kopf geübt, tatsächlich getan und von anderen erhalten hast. Ein gespeicherter Entwurf belegt Arbeit am Entwurf. Er belegt weder eine abgeschickte Bewerbung noch das Interesse eines Arbeitgebers.","Eine Übersichtsarbeit über 138 Experimente fand im Durchschnitt Vorteile, wenn Fortschritte häufiger beobachtet wurden. Dieses genaue Protokoll und ein idealer Rhythmus für Rückblicke wurden nicht geprüft. Wähle anhand deiner Tatsachen: einen machbaren Schritt wiederholen, ein Problem ändern, Rückmeldung suchen oder ein ungeeignetes Ziel aufgeben. Gibt es keinen Versuch, benenne diese Lücke und erarbeite deinen ersten brauchbaren Teil."],practice:["Mach deinen ersten kleinen Versuch oder lege genau fest, wann du ihn machst.","Wähle einen sinnvollen Rückblicktermin. Nutze die Fragen: „Was habe ich versucht, und was habe ich gelernt?“","Wähle, was passt: weitermachen, verkleinern, Unterstützung suchen oder das Ziel ändern."],reflection:"An welchem Tag und anhand welcher Informationen prüfst du deinen Plan?",question:"Welcher Rückblick hilft am meisten, wenn dein gewünschtes Ergebnis ausbleibt?",options:["Meine Gedanken waren nicht stark genug.","Meine versuchten Handlungen und die Bedingungen prüfen und dann die nächste Entscheidung treffen.","An derselben Erwartung festhalten, ohne auf die Wirklichkeit zu schauen."],correct:1,feedback:"Der Vergleich von Plan und Wirklichkeit liefert neue Informationen. Kein Kurs garantiert Ergebnisse. Du kannst deinen eigenen Anteil und die äußeren Bedingungen zusammen abwägen.",takeaway:"Lass deine Einträge den nächsten Schritt verändern. Einsatz, Vorbereitung und äußere Ergebnisse sagen Unterschiedliches aus.",sources:["M03","M01"],deeper:[{heading:"Fortschritte festhalten hilft bei einer Entscheidung",paragraphs:["Harkin und Kollegen untersuchten 2016 in ihrer Übersichtsarbeit 138 Experimente mit zufälliger Zuteilung und insgesamt 19.951 Teilnehmenden. Die Analyse zur Zielerreichung umfasste 18.398 Personen. Sie ergab d = 0,40, mit einem 95%-Konfidenzintervall von 0,32 bis 0,48. Eine Zusatzanalyse zu Verzerrungen durch kleine Studien lieferte eine niedrigere Schätzung. Interventionen, Ziele und Aufzeichnungsweisen unterschieden sich. Die Übersichtsarbeit prüfte weder ODAs Zusammenfassung noch die Karte für den nächsten Tag. [M03]","Über die Studien hinweg gingen schriftlich oder öffentlich berichtete Fortschritte mit größeren Effekten einher. Diese Vergleiche von Studienmerkmalen belegen weder, dass öffentliches Teilen nötig ist, noch dass ein bestimmtes App-Format den Nutzen verursacht. Behalte persönliche Angaben für dich, wenn das zu deiner Situation passt. Vergleiche anhand deiner Einträge, was der Plan verlangte und was du tatsächlich berichtet hast. Ohne Eintrag bleibt das Geschehen unbekannt. Erledigte Vorbereitung, eine unbeantwortete Bitte oder ein gestoppter Versuch behalten jeweils ihre eigene Bezeichnung. So lässt sich deine nächste Entscheidung prüfen, ohne dass du eine positive Geschichte liefern musst."]},{heading:"Plane die nächste Woche, ohne die vorige umzuschreiben",paragraphs:["Ein kurzes privates Protokoll kann ein Muster nahelegen. Es beweist aber nicht, warum ein äußeres Ergebnis eingetreten ist. Bewerbungen, Bestellungen und Antworten anderer können von Qualität, Zeitpunkt, Mitteln oder Umständen abhängen, die dein Protokoll nicht erfasst. Forschung zum Beobachten von Fortschritten stützt die Nutzung von Informationen. Sie legt keine allgemeingültige Anzahl von Versuchen fest, bevor du ein Ziel ändern solltest. [M03] Lass diese Unsicherheit beim Rückblick sichtbar.","Wähle eine machbare nächste Gelegenheit und einen Rückblicktermin für die kommende Woche. Behalte dein brauchbares Minimum und das, was dir Zugang zur Aufgabe verschafft hat. Ändere den Teil, den deine Einträge tatsächlich infrage stellen. Ist kein Versuch erfasst, berichte bekannte Tatsachen oder behandle die nächste kleine Handlung als deinen ersten Versuch. Erfinde keine geleistete Arbeit. Planungsstudien fanden im Durchschnitt Vorteile, aber die Ergebnisse unterschieden sich. Sie garantieren keinen Erfolg. [M01] Pausieren, Rückmeldung erbitten, praktische Unterstützung suchen oder eine andere Richtung wählen kann eine bewusste Entscheidung aus dem Rückblick sein. Behalte den früheren Eintrag, damit der Grund sichtbar bleibt."]}],example:{title:"Daniel plant die nächste Woche",text:"Daniel liest drei datierte Änderungen und eine ungenutzte Gelegenheit am Laptop. Sein Lebenslauf ist klarer, aber er hat noch keine Bewerbung abgeschickt. Er wählt eine passende Stelle, prüft ihre Anforderungen und schickt am Freitag die vorbereitete Fassung ab. Er notiert den Versand und plant einen Rückblick nächste Woche. Noch keine Antwort."}},...r.map(a)]},g=Object.freeze(Object.defineProperty({__proto__:null,COURSE:l,MANIFEST_LESSONS_V2:i,SOURCES:u},Symbol.toStringTag,{value:"Module"}));export{g as m};
